/* ÇEVİRİ es · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("es","olay",{
"OLAYLAR_EK21:1811-05-01:0":{"b": ["Evacuación de Silistra — la fortaleza central del Danubio es abandonada con sus murallas demolidas", "561628bb"], "d": ["Silistra, una de las fortalezas otomanas más fuertes del Danubio, había sufrido en 1810 el bombardeo de la artillería rusa, y con la explosión de un depósito de armas la fortaleza y el arrabal habían sufrido graves daños. Después de tomar la ciudad, los rusos, en lugar de conservarla, optaron por destruir su fortificación: el general Kutúzov ordenó demoler las murallas e informó al zar en mayo de 1811 de que las murallas de Silistra habían sido voladas. El registro de la TDV: «En 1810 la ciudad fue bombardeada por los rusos… Después de que los rusos tomaron la ciudad y antes de su retirada, el general Kutúzov ordenó la destrucción de Silistra. En mayo de 1811 informó al zar de que las murallas de Silistra habían sido voladas». Esta misma fortaleza sería tomada de nuevo por los rusos en la guerra de 1827-1828, y Helmuth von Moltke describiría ese asedio con detalle.", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["El fin de la dinastía Zand — dominio qajar en Irán", "5dda30a4"], "d": ["Con la derrota de Lutf Ali Jan, último soberano de la dinastía Zand, terminó la dinastía fundada en 1751 y todo Irán pasó a manos de Agha Muhammad Jan. La fundación oficial del Estado qajar se fecha dos años más tarde, cuando Agha Muhammad Jan se puso en Teherán la corona de sha de reyes (1796); pero el control se había transferido en 1794.", "793d45c6"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Acuñación del primer akçe otomano", "38d2d638"], "d": ["El primer akçe de plata acuñado en nombre de Orhan Gazi es la proclamación monetaria de la soberanía independiente del beylicato; el akçe siguió siendo la unidad monetaria básica durante cinco siglos.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Se estableció el beylerbeyilato de Rumelia", "ffa16089"], "d": ["Las conquistas del lado europeo se reunieron bajo un único marco militar y administrativo; el sistema del beylerbeyilato se convirtió en la columna vertebral de la organización provincial del imperio.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Matrimonio de Bayezid el Rayo con Despina Hatun", "4b10dc6c"], "d": ["El vasallaje establecido con el despotado serbio tras Kosovo quedó sellado con el matrimonio de Olivera, hija de Lazar, con Bayezid: ejemplo típico de la diplomacia matrimonial de la época temprana.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Se estableció el beylerbeyilato de Anatolia", "5ef8d3a7"], "d": ["Se organizó el beylerbeyilato de Anatolia para administrar los territorios de los beylicatos anexionados; quedó completo el sistema administrativo de doble ala, Rumelia-Anatolia.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Finalizó la Gran Mezquita de Bursa", "27bcc4a5"], "d": ["La gran mezquita de veinte cúpulas, construida con el botín de Nicópolis, es un ejemplo monumental de la arquitectura otomana temprana y un museo al aire libre de la caligrafía.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Destitución y ejecución de Çandarlı Halil Pasha", "5e19438f"], "d": ["Tras la conquista, el gran visir de la arraigada familia Çandarlı, que se había mostrado distante respecto del asedio, fue ejecutado; por primera vez un gran visir era muerto por orden del sultán y se abría la era de los visires de origen devshirme.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Moldavia pasó a ser tributaria", "25bd3693"], "d": ["El voivodato de Moldavia aceptó pagar tributo; junto con Valaquia y Transilvania, el triple cinturón vasallo al norte del Danubio se convirtió en el tampón septentrional del imperio. Otro lugar incorporado en la misma fecha: Iași.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Tributo de Dubrovnik (Ragusa)", "d127c78a"], "d": ["La república mercantil de Ragusa aseguró su autonomía y sus privilegios comerciales a cambio de tributo; se enriqueció como ventana del Imperio otomano en el Adriático. La isla de Mljet, territorio de la república, compartió también este estatuto.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Campaña de Valaquia: el Voivoda Empalador", "fd4530bb"], "d": ["Con la campaña dirigida contra Vlad Tepeş, que se negó a pagar tributo y mató a los enviados, Valaquia volvió a ser vasalla; el ataque nocturno y las escenas de horror de los empalamientos se hicieron legendarios en Europa. Otro lugar incorporado en la misma fecha: Bucarest.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Se inauguró el complejo de Fatih", "a150ea55"], "d": ["Con sus ocho madrasas (Sahn-ı Semân), el complejo fue el primer gran paso del programa para convertir Estambul en centro del saber del mundo islámico.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu en Estambul", "8508229d"], "d": ["Ali Kuşçu, último gran representante del observatorio de Samarcanda, fue nombrado profesor de la Madrasa de Santa Sofía por invitación de Fatih; fundó en Estambul la tradición de matemáticas y astronomía.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Código de Fatih (Kanunnâme)", "b08944c9"], "d": ["Primer código consuetudinario (örfî) de amplio alcance que recopila la organización del Estado, el protocolo y las penas; es objeto de debate por su célebre artículo que autorizaba el fratricidio «por el orden del mundo».", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Acuñación del primer oro otomano (sultanî)", "2fd5c0dd"], "d": ["Se acuñó la primera moneda de oro otomana, equivalente al ducado veneciano; las finanzas imperiales se incorporaron al orden monetario internacional.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Traslado al Palacio de Topkapı", "b9cd6a5e"], "d": ["Al completarse el Palacio Nuevo (Topkapı), el centro de la administración del Estado se trasladó allí; el palacio siguió siendo durante cuatro siglos el cerebro del imperio.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["La República de Florencia se convirtió en ducado: Alessandro de' Medici", "c08764e1"], "d": ["Por presión del papa Clemente VII, la comisión gobernante de Florencia (la Balìa) adoptó una nueva constitución; se abolió el régimen republicano de cinco siglos y Alessandro de' Medici fue proclamado duque hereditario, ocupando de hecho el trono el 1 de mayo. Florencia pasó así de ciudad-república independiente a ducado hereditario de la dinastía Médici.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Matrimonio de Solimán el Legislador con Hürrem Sultan", "abc05f26"], "d": ["El matrimonio oficial de Solimán con Hürrem cambió de raíz la tradición palaciega; nació la institución de la «Haseki Sultan» y se abrió la puerta a una era de mujeres en la política dinástica.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Primeras capitulaciones amplias a Francia", "e2264e48"], "d": ["Como parte de la alianza con Francia contra la tenaza de los Habsburgo, se firmaron privilegios comerciales entre Jean de la Forest y Makbul İbrâhim Pachá; las capitulaciones, que entonces eran un instrumento diplomático, se convertirían con los siglos en la puerta de la dependencia financiera.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Expedición al océano Índico: sitio de Diu", "fcd1217a"], "d": ["La flota que zarpó de Suez cruzó el mar Rojo y sitió Diu, en Guyarat; aunque no se tomó la fortaleza, el poder otomano llegó por primera vez al océano Índico y el monopolio portugués se tambaleó.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Viaje a la India de Seydi Ali Reis", "e5da3b2c"], "d": ["Seydi Ali Reis, encargado de llevar a Egipto la flota de Basora, fue arrastrado a la India por las tempestades; el Mir'âtü'l-memâlik, en que relató su aventura de regreso, es uno de los primeros libros de viajes otomanos.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Ejecución de Pîrî Reis", "63026444"], "d": ["El gran navegante y cartógrafo, que regresó de la expedición a Ormuz dejando la flota en Basora, fue ejecutado a los 84 años; una de las decisiones más controvertidas de nuestra historia de la ciencia.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Se inauguró el complejo de Solimán", "1c6458b2"], "d": ["El complejo que el arquitecto Sinan llamó «mi obra de oficial», con sus madrasas, su hospital (dârüşşifâ) y su biblioteca, fue el mayor complejo educativo y benéfico de la época clásica.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Sitio de Malta", "f57f6a85"], "d": ["Malta, la llave del Mediterráneo, fue sitiada durante cuatro meses; Turgut Reis cayó mártir y se levantó el sitio. Fue el primer gran revés de la marina de la época de Solimán el Legislador.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Finalizó la Mezquita de Selim", "3b0484e1"], "d": ["La Selimiye, que Sinan llamó «mi obra de maestro» y en la que una sola cúpula domina el espacio, se considera la cumbre de la arquitectura clásica otomana (Patrimonio Mundial de la UNESCO).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Se fundó el Observatorio de Estambul", "169bdf5d"], "d": ["El observatorio de Takiyyüddin, uno de los mejor equipados de su tiempo, fue demolido en 1580 tras las polémicas surgidas después del cometa de 1577; la astronomía institucional se retrasó tres siglos.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Victoria de Çıldır: comenzó la guerra del este", "13125a54"], "d": ["Con la derrota del ejército safávida en Çıldır se abrieron las puertas del Cáucaso; se tomó Tiflis y Georgia entró bajo dominio otomano.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Batalla de las Antorchas: Şirvan definitivamente otomana", "3bbc23bc"], "d": ["En la batalla, llamada así porque continuó de noche a la luz de las antorchas, los safávidas sufrieron una derrota decisiva; se consolidó el dominio otomano en Şirvan y Bakú.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Gran tağşiş — crisis del akçe", "9205c3d4"], "d": ["Por la presión de las largas guerras y de la plata americana, el contenido de plata del akçe se redujo a la mitad; la revolución de los precios alimentó la disolución del orden de los sipahis y el desorden celalí.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Conquista de Tabriz", "6506bdb9"], "d": ["El serdar Özdemiroğlu Osman Pasha entró en Tabriz; la antigua capital de los safávidas pasó a la administración otomana. Osman Pasha falleció en el campamento unas semanas más tarde.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Tratado de Ferhad Pasha: las fronteras más amplias en el este", "c429972f"], "d": ["Tras la llegada a Estambul del enviado del sah Abbas, Haydar Mirza (18 de enero de 1590), el tratado, concluido con la condición de que los territorios conquistados quedaran en poder otomano y que puso fin a la guerra de 12 años, dejó en manos otomanas Tabriz, Karabaj, Şirvan, Georgia y Luristán; el imperio alcanzó en el este las fronteras más amplias de su historia.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Comenzó la guerra otomano-safávida (1603-1612): contraataque del sah Abbas, pérdida de Tabriz", "abf27dd8"], "d": ["El sah Abbas, tras reorganizar su ejército, pasó a la ofensiva aprovechando las revueltas celâlíes; cayó Tabriz y las ganancias del Cáucaso se perdieron en pocos años. Otros asentamientos perdidos en la misma campaña y después: Najicheván, Hoy, Merend, Selmâs; los beys de Karacadağ (Ahar) y Mukrî pasaron también al bando safávida.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Nació Evliya Çelebi", "2b6051ff"], "d": ["Evliya Çelebi, que reunió en el Seyahatnâme, en diez volúmenes, sus viajes de más de cincuenta años, dejó un panorama incomparable del mundo otomano del siglo XVII.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Tratado de Nasuh Pasha", "bb69e388"], "d": ["Con el tratado que puso fin a la guerra vigente desde 1603 se renunció a las ganancias de 1590 y se volvió a la frontera de Amasya de 1555; se restableció el equilibrio en el frente oriental.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Se inauguró la Mezquita del Sultán Ahmed", "e39dfd43"], "d": ["La «Mezquita Azul», con sus seis minaretes y sus azulejos azules de Iznik, es el último gran complejo sultaniano de la época clásica.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Asesinato del sultán Ibrahim", "bc4eb452"], "d": ["Alegando derroche y crisis de gobierno, la alianza de la guarnición y los ulemas depuso a Ibrahim; diez días después fue estrangulado mediante una fetua. Subió al trono Mehmed IV, de siete años; el poder pasó de hecho a manos de la gran valide Kösem Sultan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Muerte de Kâtib Çelebi", "e167e89d"], "d": ["Figura cumbre de la historia del saber otomano con su bibliografía Keşfü'z-zunûn y su geografía Cihannümâ; es conocido por su enfoque pionero de utilizar fuentes europeas.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Suceso de Edirne: deposición de Mustafa II", "0291c1cd"], "d": ["La residencia del sultán en Edirne y la ira contra la influencia de Feyzullah Efendi se convirtieron en una gran sublevación de ejército y artesanos; el sheij al-Islam fue linchado, el sultán fue depuesto y la corte volvió a Estambul.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Embajador en París: Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["La gran embajada enviada a Francia fue la primera observación sistemática de Occidente sobre el terreno; su Sefâretnâme inspiró la renovación de la Era de los Tulipanes.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Se fundó la primera imprenta otomana", "4943f7e5"], "d": ["Se concedió el permiso para imprimir libros en turco; la primera obra, el Diccionario de Vankulu, se imprimió en 1729. La imprenta es el legado más duradero de la renovación de la Era de los Tulipanes.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Las capitulaciones se hicieron permanentes", "d044a79e"], "d": ["Los privilegios concedidos a Francia dejaron de estar limitados a la persona del sultán y fueron vinculados a un tratado permanente; el régimen de capitulaciones, que pasó a ser imposible de denunciar unilateralmente, solo pudo ser abolido en Lausana.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Se fundó la Mühendishâne-i Bahrî-i Hümâyun", "9bf3f439"], "d": ["Fundada tras el desastre de Çeşme para formar oficiales navales modernos, la escuela de ingeniería es la primera institución duradera de enseñanza técnica de estilo occidental; la escuela de ingeniería militar terrestre la siguió en 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Primera embajada permanente en Londres", "6b5630eb"], "d": ["Como parte del programa del Nizâm-ı Cedîd se abrieron embajadas permanentes en las capitales europeas; la diplomacia otomana pasó al principio de reciprocidad.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Muerte de Alemdar Mustafa Pasha", "4426534e"], "d": ["En la sublevación de los jenízaros iniciada en la noche del 15 de noviembre de 1808, el gran visir reformista, sitiado en la Sublime Puerta, al no llegar la ayuda que esperaba hizo volar al día siguiente el polvorín y murió con cientos de atacantes; con él se enterraron el orden del Sened-i İttifak y el primer intento de reforma.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Primer periódico oficial: Takvîm-i Vekāyi", "c637f623"], "d": ["Comenzó a publicarse el periódico oficial del Estado; es el inicio de la tradición de la opinión pública moderna y de los comunicados oficiales.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Tratado de Comercio de Balta Limanı", "e790b383"], "d": ["A Inglaterra se le reconoció la posición más privilegiada incluso en el comercio interior y se abolió el sistema de monopolio (yed-i vahit); mientras la producción local quedaba sin protección, el tratado fue el documento de la apertura total del mercado otomano al libre comercio.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Fin del Emirato del Líbano: destitución de Beshir III Shihab", "f85ae454"], "d": ["El emir Beshir II (III), que no pudo controlar la rivalidad entre cristianos y drusos ni los equilibrios internos de la región de Chouf, fue destituido en enero de 1842; terminó el régimen emiral local vigente desde 1516 (a manos de los Ma'n y después de los Shihab) y la región pasó a la administración otomana directa y luego al sistema de la doble caimacamía.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke: el sistema Mecidiye", "c77be809"], "d": ["Con la reforma monetaria se retiraron las monedas de ley alterada y se estableció un sistema bimetálico estable basado en la lira de oro (Mecidiye).", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Fin del dominio local de la familia Harfush en Baalbek", "8438f4ae"], "d": ["La influencia de la familia Harfush, que gobernaba Baalbek desde 1521 (tras la rebelión de Canbirdi Gazâlî) como una pequeña dinastía local, terminó con la nueva ordenación administrativa de la Sublime Puerta; la ciudad quedó convertida en una simple cabecera de distrito (kaza) del vilayato de Damasco.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Se fundó la Şirket-i Hayriyye", "462830e7"], "d": ["La compañía, creada para explotar vapores en el Bósforo, se considera la primera sociedad anónima otomana; los embarcaderos de vapores marcaron la vida de la ciudad.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Primer contrato de deuda externa", "9017c579"], "d": ["Para financiar la guerra de Crimea se obtuvo en el mercado de Londres el primer empréstito exterior; el punto al que se llegó en 21 años con 15 endeudamientos fue la moratoria de 1875 y la Düyûn-ı Umûmiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Línea telegráfica en Estambul", "d320f39f"], "d": ["La primera línea telegráfica, instalada por las necesidades de la guerra de Crimea, entró en servicio; en pocas décadas el imperio llegó a contar con una de las mayores redes telegráficas del mundo.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Código de Tierras (Arazi Kanunnâmesi)", "6bae243a"], "d": ["El código que modernizó el derecho de la tierra vinculó al registro de la propiedad (tapu) la posesión efectiva de las tierras del Estado (mîrî); es uno de los documentos fundamentales del régimen de propiedad del Oriente Medio actual.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Primeras clases en el Dârülfünun", "08f74066"], "d": ["El Dârülfünun, que impartiría enseñanza de nivel universitario, comenzó a funcionar con clases públicas; la institución, que continuó de forma intermitente, se abrió de manera permanente en 1900 y fue el núcleo de la Universidad de Estambul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Reglamento de Provincias (Vilâyet Nizamnâmesi)", "ad20853b"], "d": ["En lugar del sistema de eyalatos se estableció la organización provincial (vilayato) según el modelo francés; tomando como ejemplo la aplicación de Midhat Pasha en el vilayato del Danubio, se extendió a todo el país.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Viaje de Abdülaziz a Europa", "9ff0fa1e"], "d": ["Primer viaje a Europa de un sultán otomano con fines pacíficos; la exposición de París y las visitas a Londres sirvieron a la vez de escaparate de diplomacia y de modernización.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Se inauguró el Liceo Imperial de Galatasaray (Mekteb-i Sultânî)", "f9688524"], "d": ["El liceo, que impartía enseñanza en francés, se convirtió con un alumnado sin distinción de religión ni de comunidad (millet) en símbolo del ideal de igualdad en la educación de las Tanzimat.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Entró en vigor el primer libro de la Mecelle", "6475461c"], "d": ["La Mecelle, que recopiló con técnica legislativa moderna el derecho islámico de obligaciones y bienes, se considera el primer código civil islámico; la comisión presidida por Cevdet Pasha completó los 16 libros en 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Deposición de Abdülaziz", "eb7397ea"], "d": ["Los estadistas constitucionalistas y los mandos militares depusieron a Abdülaziz mediante un golpe silencioso; su sospechosa muerte cinco días después y los sucesos de Çırağan que siguieron provocaron ajustes de cuentas que durarían años.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Asalto de Çırağan (suceso de Ali Suâvi)", "d2a9ac87"], "d": ["El periodista Ali Suâvi asaltó el palacio de Çırağan para volver a entronizar a Murad V; el asalto fue reprimido con sangre y el régimen de Abdülhamid endureció de forma duradera su cerco de seguridad.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Establecimiento de la Administración de la Régie (monopolio del tabaco)", "bad9b030"], "d": ["Los ingresos del tabaco fueron cedidos a la compañía Régie, de capital extranjero, integrada en la Düyûn-ı Umûmiyye; los enfrentamientos de «contrabando de la Régie» entre los campesinos y los guardas se prolongaron durante décadas. Otro asentamiento perdido en la misma fecha: Zeila.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Visita del káiser Guillermo II a Estambul y Jerusalén", "2988cd06"], "d": ["La segunda visita del emperador alemán consolidó el acercamiento otomano-alemán; se abrió el camino a la concesión del ferrocarril de Bagdad y en Damasco se pronunció el discurso del «amigo de trescientos millones de musulmanes».", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["El ferrocarril del Hiyaz llega a Medina", "95009b9c"], "d": ["La línea de 1464 km, construida solo con donaciones de musulmanes e ingeniería local, llegó a Medina; el viaje de peregrinación se redujo de semanas a días. Es la mayor obra de infraestructura de la época de Abdülhamid II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Suceso del 31 de Mart", "1d7c2bb2"], "d": ["La gran sublevación contraria al régimen constitucional se apoderó de Estambul; el Ejército de Acción, llegado de Salónica, reprimió la revuelta y Abdülhamid II fue depuesto.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Comenzó el sitio de Edirne", "234d9b28"], "d": ["La defensa de cinco meses de Şükrü Pasha se convirtió en la epopeya de resistencia dentro del desastre de los Balcanes; la ciudad cayó por hambre y fue recuperada en julio de 1913.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Asalto a la Sublime Puerta", "b304d02d"], "d": ["El gobierno, que se preparaba para entregar Edirne, fue derribado por el asalto armado de los unionistas; fue muerto el ministro de Guerra Nâzım Pasha. Comenzó el período de poder total de Unión y Progreso.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Abolición de la mutasarrifía del Monte Líbano", "b5639051"], "d": ["El régimen autónomo de la mutasarrifía, basado en el Règlement Organique de 1861 y en el protocolo internacional renovado en 1864, fue abolido unilateralmente por el Estado otomano durante la Primera Guerra Mundial; el Ministerio del Interior comenzó a nombrar directamente mutasarrifes musulmanes para la región. Así se cerró el período de autonomía en que habían servido ocho mutasarrifes entre 1861 y 1915.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["División del país entre los príncipes", "82f26bfb"], "d": ["Tras el desastre de Ankara, Süleyman Çelebi pasó a Rumelia y proclamó el sultanato en Edirne; İsa Çelebi conservó Bursa y Çelebi Mehmed la región de Amasya-Tokat-Sivas. En el mapa estas tres partes se muestran en colores distintos.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Tratado de Galípoli: se cedió a Bizancio la costa del mar Negro hasta Mesembria", "a4164eca"], "d": ["Tras el desastre de Ankara, el emir Süleyman, que quería afianzarse en Rumelia, firmó en Galípoli un tratado con el emperador bizantino Manuel. Cedió a Bizancio Kartal, Pendik y Gebze con algunas islas, Salónica y Tesalia en Rumelia, y en el mar Negro la franja costera hasta Mesembria; también se suprimió el tributo que Bizancio pagaba a los otomanos. Ahtapolu, İğneada y Rezve, en la costa de Istranca, permanecieron así veintiún años bajo administración bizantina; Murad II recuperó la mayoría de estos lugares con la paz de 1424.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Muerte de Bayezid el Rayo en cautiverio", "7e968d83"], "d": ["El sultán, prisionero en manos de Tamerlán, falleció en Akşehir; su cuerpo fue llevado a Bursa y sepultado. Su muerte hizo irreversible la lucha por el trono entre los príncipes.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Tratado de Galípoli: concesiones a Bizancio", "dfacbd00"], "d": ["Süleyman Çelebi, que quería asegurar su posición en Rumelia, llegó a un acuerdo con Bizancio y los Estados latinos y devolvió Salónica, las costas del Mármara y algunas islas; aceptó incluso pagar tributo.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Choque de Ulubat: derrota de İsa Çelebi", "500c5d24"], "d": ["İsa Çelebi, que conservaba Bursa, fue derrotado en Ulubat por su hermano Mehmed; sus varios intentos de recuperarse también fueron infructuosos.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Desaparición de İsa Çelebi", "0effa11e"], "d": ["İsa Çelebi, que con el apoyo de Süleyman Çelebi volvió varias veces a Anatolia, desapareció tras su última derrota; su parte pasó a Çelebi Mehmed y en el mapa el territorio de Mehmed se amplió hacia el oeste.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebi pasó a Valaquia", "8441267a"], "d": ["Çelebi Mehmed, que había perdido Bursa y Ankara ante Süleyman Çelebi y se había retirado a Tokat-Amasya, animó a su hermano Musa a ir a Rumelia. Musa, aceptando la invitación del voivoda de Valaquia, Mircea, llegó a Valaquia por mar; desde allí emprendería una lucha que dejaría a Süleyman entre dos frentes.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çelebi Mehmed recuperó Bursa y Ankara: la parte de Anatolia salió de manos de Süleyman Çelebi", "bfb69f12"], "d": ["Ante los éxitos de Mûsâ Çelebi en Rumelia (Yambol, 13 de febrero de 1410), el emir Süleyman Çelebi, que se hallaba en Anatolia, pasó a Rumelia. Tras la salida de Süleyman de Anatolia, Mehmed Çelebi volvió a tomar la región de Bursa, incluida Ankara, e hizo acuñar una moneda con fecha 813 como señal de su ascenso al trono. En el mapa, el lado anatolio del Mármara pasa de la parte del emir Süleyman al color de Çelebi Mehmed.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Batalla de Kosmidion", "0efc2caa"], "d": ["En la batalla librada ante las murallas de Constantinopla con apoyo bizantino, Süleyman Çelebi derrotó a su hermano Musa; pero su apoyo en Rumelia había comenzado a menguar rápidamente.", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Sitio de Constantinopla por Musa Çelebi", "4932f586"], "d": ["Musa Çelebi, que quería castigar a Bizancio por apoyar a Süleyman, sitió Constantinopla; este sitio empujó a Bizancio a aliarse con Çelebi Mehmed.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Muerte del emir Süleyman: Musa domina Rumelia", "325c1549"], "d": ["Süleyman Çelebi, capturado cuando huía de Edirne, fue muerto; toda Rumelia pasó a manos de Musa Çelebi. En el mapa Rumelia pasa del color azul al morado.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Batalla de Çamurlu: restablecimiento de la unidad", "0b23173e"], "d": ["Çelebi Mehmed, con el apoyo de Bizancio, del despotado serbio y de los beyes de Rumelia, derrotó de forma decisiva a su hermano Musa en Çamurlu; Musa fue muerto mientras huía. Rumelia, en manos de Musa, pasó a Mehmed junto con Edirne, y Mehmed Çelebi se proclamó en Edirne único soberano del Estado otomano. Terminó el Interregno (Fetret Devri) de once años y las partes de los príncipes en el mapa se reunieron en un solo cuerpo.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Decisión de la campaña de Viena: no se renovó la paz de Vasvár, el objetivo pasó de Győr a Viena", "1bf278f2"], "d": ["El emperador Leopoldo I quería renovar el tratado de Vasvár, cuyo plazo aún no había vencido, y Mehmed IV parecía favorable a la paz. El gran visir Merzifonlu Kara Mustafa Pasha, en cambio, alegando las quejas de Imre Thököly, a quien había hecho proclamar rey de la Hungría Central, no hizo renovar la paz; movilizando a predicadores, con Vânî Mehmed Efendi a la cabeza, convenció al sultán de ir a la guerra. En la consulta celebrada se decidió que el sultán permaneciera en Belgrado y que el serdar-ı ekrem avanzara para tomar Győr (Yanıkkale); pero, en la consulta de Belgrado, a pesar de las objeciones del jan de Crimea Murad Giray y del gobernador de Buda, Uzun Ibrahim Pasha, el objetivo fue cambiado por el sitio de Viena, según lo propuso İstolni.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Comenzó el segundo sitio de Viena: el ejército ante Viena", "bb542e49"], "d": ["El ejército otomano al mando del gran visir Kara Mustafa Pasha llegó ante Viena el 14 de julio de 1683. El emperador Leopoldo I, dejando la defensa de la ciudad a Starhemberg, se retiró al interior de Austria. Este segundo sitio, preparado a diferencia del primero con Viena directamente como objetivo, duraría hasta el 12 de septiembre.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Derrota de Párkány y pérdida de Esztergom", "a7366740"], "d": ["El ejército que se retiraba de Viena fue derrotado por segunda vez en Párkány; luego cayó Esztergom, una de las fortalezas clave de Hungría. La retirada empezaba a convertirse en un desmoronamiento.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Ejecución de Merzifonlu Kara Mustafa Pasha", "ce8b10ac"], "d": ["El gran visir, considerado responsable de la derrota de Viena, fue estrangulado en Belgrado; pero su ejecución no enderezó el frente ni devolvió el prestigio quebrantado del Estado.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Se formó la Santa Liga", "060280d0"], "d": ["Bajo la iniciativa del papado se formó la Santa Liga (Mukaddes İttifak) contra los otomanos entre Austria, Polonia y Venecia; en 1686 se unió también Rusia. Así el imperio entró en una guerra de múltiples frentes que duraría dieciséis años.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Primera defensa de Buda", "ccc43630"], "d": ["El primer sitio de Buda por el ejército de la Santa Liga fue rechazado con la tenaz defensa de la fortaleza durante cuatro meses; pero las fortalezas de Hungría seguían cayendo una a una.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Pérdida de Uyvar", "689ab78c"], "d": ["La fortaleza de Uyvar (Érsekújvár), que permaneció veintidós años en manos otomanas y era proverbial en Europa, cayó; la presencia otomana en la Alta Hungría se deshizo.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Arresto de Thököly en Varad: se disolvió el reino de la Hungría Central, las fortalezas de la Alta Hungría se rindieron", "1741aaaf"], "d": ["Después del desastre de Viena, los otomanos habían empezado a ver también a Thököly entre los responsables de la guerra y de la derrota. El 15 de octubre de 1685, por orden del serdar Melek Ibrahim Pasha, el beylerbeyi de Varad, Ahmed Pasha, hizo apresar a Thököly, que había acudido en su ayuda; se esperaba obtener mejores condiciones de paz entregándolo a los Habsburgo. Al difundirse la noticia del arresto, todas las fortalezas y ciudades del reino de la Hungría Central, salvo Munkács, defendida por su esposa Ilona Zrínyi, se rindieron a los Habsburgo; la mayoría de los soldados kuruc pasó al ejército de los Habsburgo. Cuando Thököly fue puesto en libertad en Belgrado el 2 de enero de 1686, el reino ya había desaparecido.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Pérdida de Buda: la capital húngara de 145 años", "70800e2b"], "d": ["Buda cayó al cabo de un sitio de setenta y ocho días; el último beylerbeyi, Abdurrahman Abdi Pasha, murió mártir en las murallas. La pérdida de la ciudad, bajo administración otomana desde 1541, se considera el símbolo de la pérdida de Hungría. Otro asentamiento perdido en la misma fecha: Pest.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Segunda derrota de Mohács (Harsány): pérdida de Transilvania y de Mohács", "a7922681"], "d": ["En la llanura donde se había obtenido la gran victoria de 1526 se sufrió esta vez una grave derrota; el ejército se dispersó y los soldados sublevados hicieron destituir al gran visir. La derrota llevó también a la pérdida de Transilvania.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Pérdida de Atenas y explosión del Partenón", "b6691730"], "d": ["Una bomba lanzada por la artillería veneciana hizo volar el Partenón, que los otomanos usaban como polvorín; el templo de dos mil años quedó en ruinas. La ciudad pasó a manos venecianas (será recuperada en 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Deposición de Mehmed IV y acceso al trono de Solimán II", "9f53037c"], "d": ["Ante los desastres del frente y la sublevación del ejército, Mehmed IV fue depuesto tras un reinado de 39 años; en su lugar fue entronizado su hermano Solimán II, que llevaba cuarenta años encerrado en el kafes.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Primera pérdida de Belgrado: sitio de la Santa Liga", "c6b9b19a"], "d": ["Belgrado, en manos otomanas desde 1521, se rindió al ejército de la Santa Liga; las puertas de Serbia quedaron abiertas al enemigo y el peligro llegó hasta la línea Niš-Sofía.", "33c7db1f"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden cruzó el Morava ante Pasarofça: Pasarofça cayó en poder de Austria", "bcf3fc59"], "d": ["El margrave Luis de Baden cruzó el Morava en Pasarofça en agosto de 1689 y avanzó hacia Niš; la ciudad permaneció en manos austríacas hasta el verano de 1690 (TDV suleyman-ii dice que Pasarofça fue recuperada en 1690). El día y la lectura de Röder no se volvieron a verificar en esta sesión.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Pérdida de Niš: avance de los Habsburgo (corona del reino de Hungría), el año más crítico", "c5e27b3f"], "d": ["El avance de los Habsburgo (corona del reino de Hungría) quitó también Niš a la administración otomana; las incursiones llegaron hasta Skopie y Pristina. Vidin, en cambio, cayó después, en octubre de 1689 (artículo aparte). En el año más sombrío de la guerra, el Estado sintió amenazada incluso su capital.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova y Fethülislâm pasaron a guarnición austríaca", "ee8dd875"], "d": ["Tras la toma sin lucha de Vidin (octubre de 1689, TDV vidin), Baden reparó y guarneció Orsova y Fethülislâm el 25 de octubre de 1689; Orsova permaneció en poder de Austria hasta el otoño de 1690. El día se apoya en Bánlaky/Röder y no se volvió a verificar en esta sesión.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš vuelve a ser otomana", "0c4f44eb"], "d": ["Fâzıl Mustafa Pasha salió de campaña en julio de 1690; tras la toma de Şehirköy, Pasarofça y Güvercinlik, Niš, sitiada, pasó a manos de los otomanos el 27 de septiembre de 1690 (TDV semendire). Por entonces Vidin también había sido recuperada.", "f252f3ae"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Las tropas austríacas se rindieron en Semendire", "90da20c4"], "d": ["Tras la toma de Niš el 27 de septiembre de 1690, las tropas austríacas de Semendire se rindieron después de un sitio de cuatro días (TDV semendire). Bánlaky/Röder da el 24 de septiembre; las fuentes se contradicen y se adoptó la TDV.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Belgrado recuperada", "ab435838"], "d": ["El gran visir Köprülüzâde Fâzıl Mustafa Pasha recuperó Belgrado de manos de Austria el 8 de octubre de 1690; la ciudad, perdida en 1688, volvió así a los otomanos (TDV suleyman-ii).", "c93eeef6"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Derrota de Slankamen: Fâzıl Mustafa Pasha murió mártir", "10d626f1"], "d": ["En una de las batallas campales más sangrientas del siglo, el gran visir cayó mártir con un disparo en la frente; el ejército se dispersó. Con esta batalla se extinguió la esperanza de recuperación.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Pérdida de la isla de Quíos", "07c084f8"], "d": ["La flota veneciana ocupó Quíos; el dominio otomano en el Egeo quedó amenazado. La isla será recuperada al año siguiente.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Decisión de Mustafa II de salir en persona a campaña", "61c3ba9c"], "d": ["El nuevo sultán anunció que, siguiendo el camino de sus antepasados, saldría a campaña al frente del ejército; esta decisión elevó la moral del ejército e inició un período de campañas personales que duraría dos años.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Recuperación de Quíos", "6b496fca"], "d": ["Mezomorto Hüseyin Pasha, que derrotó a la flota veneciana en las batallas navales de las islas Oinousses (Koyun Adaları), recuperó Quíos; fue señal de un breve resurgir de la marina otomana.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Victoria de Lugoj: campaña de Him II", "6527cee3"], "d": ["En la primera campaña en que participó personalmente el sultán se recuperó Lipova y las fuerzas austríacas fueron derrotadas en Lugoj; se produjo la primera ruptura en la cadena de derrotas de años.", "54aa0f54"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Pérdida de la fortaleza de Azov", "2b78b5cd"], "d": ["Pedro I, que aspiraba a salir al mar Negro, tomó Azov en su segundo sitio; Rusia se estableció por primera vez de forma permanente en una fortaleza otomana y dio su primer paso hacia convertirse en potencia naval.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Victoria de Ulaş (Olaşin)", "02ac9ca8"], "d": ["La victoria obtenida a orillas del Danubio en la segunda campaña del sultán frustró el plan austríaco de tomar Timișoara; sin embargo, no cambió el equilibrio general de la guerra.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Derrota de Zenta: se decidió el destino de la guerra", "475c4a7b"], "d": ["El ejército, que cruzaba el río Tisza, fue sorprendido por el ataque repentino del príncipe Eugenio; las fuerzas, divididas a ambas orillas del río, fueron aniquiladas en pocas horas y murieron miles de soldados y estadistas, entre ellos el gran visir Elmas Mehmed Pasha. Zenta, una de las peores derrotas de la historia otomana, hizo inevitable la mesa de paz.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Comenzaron las negociaciones de paz de Karlowitz", "1f395cf3"], "d": ["En las negociaciones iniciadas con la mediación de Inglaterra y los Países Bajos, la delegación otomana se vio obligada por primera vez a aceptar el principio de «uti possidetis» (que cada cual conserve lo que posee); las conversaciones, que duraron setenta y dos sesiones, se consideran el nacimiento de la diplomacia otomana moderna.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmed Ali de Kavala desembarcó en Egipto", "514c943f"], "d": ["En el ejército otomano enviado para recuperar el Egipto ocupado por Francia había también un contingente de voluntarios reclutados en Kavala. Mehmed Ali, que rondaba los treinta años, era el segundo comandante de este contingente; pisó Egipto no como gobernador, sino como oficial de una compañía.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Los soldados albaneses derrocaron al gobernador de Egipto", "c76a0ec2"], "d": ["Las tropas albanesas, a las que no se pagaba el salario (ulûfe), se sublevaron y obligaron al gobernador Hüsrev Pasha a huir de la ciudadela. En el vacío creado por la retirada de los franceses, los beyes mamelucos, la guarnición albanesa y los gobernadores nombrados por la Sublime Puerta entraron en una lucha a tres bandas; Mehmed Ali destacó estableciendo equilibrios en este triángulo. Otro asentamiento perdido en la misma fecha: Taif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Los ulemas de El Cairo proclamaron gobernador a Mehmed Ali", "a16752f2"], "d": ["Los artesanos y ulemas de El Cairo, agobiados por la presión fiscal, se sublevaron bajo la dirección del nakîbüleşraf Ömer Mekrem, declararon que no reconocían al gobernador Hurşid Pasha y colocaron a Mehmed Ali en el cargo de gobernador. Que un gobernador fuera elegido por el pueblo es un hecho de rara ocurrencia en la historia otomana.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["La Sublime Puerta aceptó el hecho consumado: firmán del gobierno de Egipto", "b86736a3"], "d": ["La Sublime Puerta, sin fuerza para sostener a su propio candidato en Egipto, envió a Mehmed Ali el firmán del gobierno de Egipto con el rango de visir. En el mapa, Egipto pasa desde esta fecha a la capa tributaria (tono claro): jurídicamente territorio otomano, de hecho país de la dinastía de Kavalalı. Otros asentamientos que pasan a la capa tributaria en la misma fecha: El Cairo, Alejandría, Damieta, Asiut, Asuán, Ibrim, Suez, Rashid (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["La expedición británica de Fraser desembarcó en Alejandría", "4d6c31be"], "d": ["En respuesta al acercamiento otomano a Francia, Gran Bretaña envió a Egipto una fuerza de desembarco. Mehmed Ali se hallaba entonces en el Alto Egipto ocupado con los mamelucos; regresó rápidamente y organizó la defensa.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Derrota de Rashid (Rosetta): los británicos fueron rechazados", "3636004c"], "d": ["La columna británica que entró en la ciudad de Rashid sufrió graves pérdidas en los combates callejeros; en septiembre las fuerzas evacuaron por completo Egipto. Esta victoria afianzó el prestigio de Mehmed Ali tanto en Egipto como en Estambul.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Suceso de la Ciudadela: liquidación de los beyes mamelucos", "84030b97"], "d": ["Los beyes mamelucos, invitados a la procesión ceremonial organizada para la expedición al Hiyaz, fueron aniquilados tras quedar atrapados en el estrecho paso de la Ciudadela de El Cairo. Así terminó la influencia mameluca de cinco siglos y Mehmed Ali no tuvo ya rivales en Egipto.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Comenzó la expedición al Hiyaz: el ejército marchó a Yanbu, por mar desde Suez y por tierra por la ruta de la peregrinación", "1c05c159"], "d": ["Recuperar los Haramain, bajo dominio saudí-wahabí desde 1803, era el mayor problema de legitimidad de Mahmud II; como la Sublime Puerta no tenía fuerza para ello, la misión se encomendó al gobernador de Egipto. Mehmed Ali envió al frente del ejército a su hijo Tosun, de dieciséis años.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Yanbu fue tomada: primera base costera de la expedición al Hiyaz", "179bc78d"], "d": ["Unos dos mil infantes albaneses, que zarparon de Suez en naves recién construidas, desembarcaron cerca de Yanbu en octubre de 1811; la localidad se rindió tras dos días de débil resistencia. La caballería al mando de Tosun, que siguió por tierra la ruta de la peregrinación, solo llegó a Yanbu dos semanas después, por Áqaba y Wajh. Yanbu fue la primera base en el Hiyaz del ejército egipcio que marcharía sobre Medina y La Meca.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Primera derrota en el desfiladero de Safra-Cedîde", "99ef804d"], "d": ["La vanguardia egipcia, emboscada en estrechos pasos de montaña, se dispersó. La derrota fue la lección táctica de la expedición: se comprendió que no era posible marchar por el Hiyaz sin el apoyo de las tribus beduinas.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Medina recuperada", "6f6a5d55"], "d": ["Tras un largo sitio, Medina se rindió. La recuperación de la ciudad del Profeta se celebró en Estambul con salvas de cañón; como recompensa se concedió también a Mehmed Ali el gobierno de Yeda.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["La Meca recuperada: se abrió la ruta de la peregrinación", "3d6d66a0"], "d": ["Las fuerzas egipcias que entraron en La Meca hicieron leer de nuevo en la Kaaba la jutba en nombre del sultán otomano. Las caravanas de peregrinos, interrumpidas desde hacía diez años, pudieron ponerse en camino de nuevo. En el mapa el Hiyaz vuelve al dominio otomano, pero, como se administra desde El Cairo, se muestra en tono tributario. Otro lugar que pasó a la administración tributaria en la misma fecha: Yeda.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Recuperación de Taif: culminación de la expedición al Hiyaz", "6315fb31"], "d": ["Tras Medina (diciembre de 1812) y La Meca (enero de 1813), el ejército egipcio al mando de Tosun Pasha recuperó por último Taif de manos de los wahabíes. Terminó el dominio saudí de diez años y los tres centros sagrados del Hiyaz volvieron a quedar bajo control otomano-egipcio.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali pasó personalmente al Hiyaz", "fda0ea2d"], "d": ["El gobernador, viendo que la expedición avanzaba con lentitud, tomó la administración directamente en sus manos; negociando con los jefes tribales procuró desmantelar desde dentro el frente saudí. Con esta expedición creció también la parte de Egipto en el comercio del mar Rojo.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Batalla de Bisel: las fuerzas saudíes fueron derrotadas", "9c9ab91f"], "d": ["Los saudíes, que sufrieron una grave derrota en batalla campal, se retiraron al interior. El armisticio concertado no fue duradero; dos años después las operaciones se trasladarían al corazón de Néyed.", "4a8ae0e2"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ibrahim Pasha emprendió la expedición a Néyed", "d5ed80d1"], "d": ["Ibrahim Pasha, que asumió el mando tras la muerte de su hermano Tosun, se lanzó a una pesada marcha de dos años por el desierto. El ejército, avanzando de pozo en pozo y eliminando una a una las tribus, llegó hasta la capital saudí.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Cayó Dir'iya: terminó el primer Estado saudí", "aa96206d"], "d": ["Tras un sitio de seis meses, Dir'iya se rindió y fue destruida. El emir Abdullah b. Saud fue enviado a Estambul y ejecutado. La bandera otomana llegó por primera vez tan adentro en el interior de Arabia; la guarnición de Néyed permaneció hasta 1824. Otro lugar incorporado en la misma fecha: Dir'iya (Néyed).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Comenzó la expedición a Sudán", "b1fc6905"], "d": ["El propósito de Mehmed Ali era triple: reclutar soldados para su ejército, alcanzar el oro de Sennar y destruir los restos de los mamelucos fugitivos. La fuerza al mando de su hijo Ismail Pasha descendió hacia el sur siguiendo el Nilo.", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["Dongola tomada: se dispersaron los restos mamelucos", "ba6bc24b"], "d": ["El ejército, que entró en Dongola, en la gran curva del Nilo, liquidó al último grupo mameluco refugiado allí. En el mapa Sudán aparece desde esta fecha en la capa tributaria: quien conquista es El Cairo y quien administrará también será El Cairo.", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["El sultanato de Sennar (Funj) se rindió", "3cac7dd2"], "d": ["La dinastía funj, de tres siglos, se rindió sin combatir. El campamento establecido el mismo año en el punto de confluencia de los dos brazos del Nilo se convirtió en poco tiempo en Jartum, centro administrativo de Sudán. Otro lugar incorporado en la misma fecha: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Kordofán conquistada", "06440602"], "d": ["La segunda columna enviada al oeste derrotó a las fuerzas de Darfur en Bâre y tomó Kordofán. El dominio egipcio en Sudán se extendió así desde el valle del Nilo a las estepas occidentales.", "e18d449a"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Fuerzas egipcias desembarcaron en Creta", "835aee90"], "d": ["Cuando la rebelión griega se extendió a Creta, la Sublime Puerta pidió que se enviara una fuerza egipcia a la isla. La influencia de Mehmed Ali en la isla comenzó con esta intervención y ocho años después culminó con la concesión del gobierno de Creta.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Muerte de Ismail Pasha en Shendi", "223860c9"], "d": ["El emir local Nimr, irritado por las exigencias de impuestos y de soldados, prendió fuego a la casa en que se alojaba Ismail Pasha y quemó a este y a su séquito. La expedición de represalia convirtió la región en un lago de sangre; desde entonces la administración de Sudán se basó en la dureza.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II pidió ayuda a Mehmed Ali por la Morea", "03594a42"], "d": ["Para la rebelión de la Morea, que el ejército jenízaro no había podido sofocar en tres años, el sultán recurrió al ejército egipcio, instruido a la europea. A cambio se le prometieron el gobierno de la Morea y Creta. Esta petición fue la primera confesión abierta de que el imperio había llegado a necesitar a una de sus propias provincias.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ibrahim Pasha desembarcó en Modon", "9c993dba"], "d": ["La fuerza de desembarco, protegida por la flota egipcia, puso pie en el extremo suroccidental de la Morea. Este ejército, dotado de infantería regular (nizamî) y artillería de campaña, logró en poco tiempo la superioridad sobre las bandas rebeldes.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Trípoli de la Morea recuperada: cayó el centro de la Morea", "8a478c11"], "d": ["Con la caída de Trípoli, centro administrativo de la rebelión, la mayor parte de la Morea volvió a quedar bajo control. En el mapa la península aparece en tono tributario por estar en manos de las fuerzas egipcias.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Cayó Missolonghi (Mesolongi)", "07257f87"], "d": ["La ciudad fue tomada tras un sitio de un año. Pero el eco que la defensa suscitó en la prensa europea llevó a su cima la simpatía por la causa griega y preparó el terreno para la intervención de las grandes potencias.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["La Acrópolis de Atenas fue tomada", "3b19f946"], "d": ["Con la caída de la Acrópolis, la rebelión griega estaba casi terminada militarmente. Justo en ese punto el asunto dejó de ser una rebelión interna y pasó a ser tema de la diplomacia europea.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Tratado de Londres: tres potencias impusieron la autonomía griega", "7ce46fd8"], "d": ["Gran Bretaña, Francia y Rusia decidieron actuar conjuntamente para hacer aceptar a los otomanos y a los griegos un armisticio y la condición de la autonomía; se notificó que, si se rechazaba, sus flotas intervendrían. La Sublime Puerta rechazó la propuesta.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Convención de Alejandría: decisión de Egipto de retirarse de la Morea", "cc978f37"], "d": ["Mehmed Ali, que perdió su flota en Navarino, llegó a un acuerdo directo con el almirante británico sin consultar a Estambul y aceptó retirar sus fuerzas de la Morea. Que un gobernador concluyera un acuerdo independiente con las grandes potencias era presagio de la crisis futura.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Las fuerzas egipcias evacuaron la Morea", "8fb742dd"], "d": ["Las últimas tropas fueron embarcadas; la península se perdió de hecho y con el Protocolo de Londres de 1830 fue el núcleo de la Grecia independiente. Mehmed Ali, en cambio, no obtuvo el gobierno de la Morea que se le había prometido y a cambio perdió una gran flota y un gran ejército. Otros asentamientos perdidos en la misma fecha: Modon, Coron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["La administración de Creta fue cedida a Mehmed Ali", "7f76396d"], "d": ["Como compensación por la pérdida de la Morea, el gobierno de Creta se concedió a Mehmed Ali. La isla fue administrada desde El Cairo durante diez años; en el mapa aparece en tono tributario durante ese período. Otro lugar incorporado en la misma fecha: Candía (Creta).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ibrahim Pasha entró en Siria: comenzó la primera crisis", "1a5cc386"], "d": ["El pretexto era el gobernador de Acre, que no devolvía a los campesinos (fellah) huidos de Egipto; la razón real era la necesidad que Mehmed Ali tenía de la madera, los puertos y los recursos humanos de Siria. El ejército cruzó el Sinaí y tomó rápidamente la costa de Palestina.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Comenzó el sitio de Acre", "b211d96d"], "d": ["La fortaleza que había detenido a Napoleón en 1799 resistió durante seis meses. El sitio fue la primera gran prueba de la artillería moderna del ejército egipcio.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Cayó Acre", "0f47917b"], "d": ["Cuando las baterías que batían las murallas abrieron brecha, se tomó la fortaleza. La puerta de Siria quedaba abierta; en esos mismos días la Sublime Puerta declaró rebelde a Mehmed Ali y le retiró el gobierno.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Damasco se rindió", "48da3b62"], "d": ["La ciudad se rindió sin combate. Ibrahim Pasha procuró ganar el apoyo local proclamando el régimen fiscal y la igualdad concedida a los no musulmanes; esas mismas políticas serían pocos años después causa de rebeliones contra él. Otros lugares incorporados en los mismos días: Beirut, Trípoli de Siria, Sidón.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Batalla de Homs", "867810ee"], "d": ["El ejército otomano enviado para salvar Siria fue derrotado en campo abierto. Se vio que el nuevo ejército, creado seis años después de la abolición de los jenízaros, aún no estaba preparado.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Alepo tomada", "9c0ead76"], "d": ["También cayó el centro comercial y administrativo del norte de Siria. Así el ejército egipcio llegó a las estribaciones del Tauro y se dirigió hacia los pasos que dan a Anatolia.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Derrota del paso de Belen (Beylan): se abrió la Cilicia", "4bae872b"], "d": ["La línea de defensa fue rota en el estrecho paso de los montes Amanos. Antioquía, Adana y Tarso pasaron a las fuerzas egipcias (según la TDV, la ocupación de Maraş es de 1833, artículo aparte); en el mapa la Cilicia (Çukurova) pasa al tono tributario. El camino al interior de Anatolia quedaba ya sin defensa.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Cayó el desfiladero de Gülek: la costa de İçil (Mersin, Silifke) pasó a control egipcio", "d9049b5b"], "d": ["El desfiladero de Gülek, puerta de la Cilicia en el Tauro, cayó en manos del ejército egipcio. Ibrahim Pasha nombró a su propio mütesellim para el sanjacado de İçil y todos los embarcaderos de la costa pasaron a control egipcio. En el mapa Mersin y Silifke aparecen vinculadas a Egipto desde este día (límite inferior; la fecha del nombramiento no consta en la fuente); como en la decisión de Kütahya solo se menciona la muhassıllık de Adana, este control termina con la evacuación de Anatolia.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Ereğli de Konya bajo ocupación egipcia: la boca del Tauro en la ruta Konya–Adana", "fb908900"], "d": ["Ereğli, situada en el camino a Konya del ejército egipcio que cruzó el desfiladero de Gülek, entró en 1832 bajo la ocupación de Ibrahim Pasha y, al ser evacuada con el arreglo de Kütahya de 1833, volvió a quedar vinculada al vilayato de Karaman. En el mapa es el punto intermedio documentado de la línea de ocupación entre Adana y Konya; para Ulukışla y Karapınar no se halló testimonio a nivel de ciudad.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["El ejército egipcio entró en Konya", "13952a2d"], "d": ["El ejército, que cruzó el Tauro, alcanzó Anatolia Central. Por primera vez las fuerzas de un gobernador otomano avanzaban por el territorio nuclear del imperio. Otro lugar incorporado en la misma fecha: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Batalla de Konya: el gran visir cayó prisionero", "ec82cc9a"], "d": ["El ejército otomano, dispersado en la niebla, sufrió una grave derrota y el gran visir Reşid Mehmed Pasha fue capturado. El ejército central del Estado ya no existía; no quedaba fuerza alguna que se interpusiera entre Estambul y las fuerzas egipcias.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş sufrió la ocupación egipcia", "f558e383"], "d": ["Según la TDV, Maraş sufrió en 1833 la ocupación de Ibrahim Pasha de Kavalalı y permaneció casi diecinueve meses bajo su administración. Como Maraş quedó fuera de los límites provinciales del arreglo de Kütahya, esta administración no es jurídica sino de hecho.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) sufrió la ocupación egipcia: la ruta Konya–Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, situada en el camino del ejército egipcio que avanzaba hacia Kütahya tras la batalla de Konya, permaneció algún tiempo en 1833 en manos de Ibrahim Pasha. En el mapa es el punto intermedio documentado de la línea de ocupación entre Konya y Kütahya; para Akşehir, Ilgın e İshaklı no se halló testimonio a nivel de ciudad, y aparecen en el color otomano.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["El ejército egipcio llegó a Kütahya", "214f8df6"], "d": ["Ibrahim Pasha se detuvo en Kütahya, a tres jornadas de Estambul. Que no avanzara más no fue por razones militares sino políticas: se habían tenido en cuenta la intervención rusa y la reacción de Europa.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["La flota rusa ante Büyükdere", "6f836d61"], "d": ["Mahmud II, que no obtuvo ayuda de Gran Bretaña ni de Francia, recurrió a Rusia, su enemiga de la víspera. Esta decisión, recordada por la frase del sultán «el que se ahoga se agarra a una serpiente», desembocó en el desembarco de soldados rusos en los estrechos e hizo sonar las alarmas en Europa.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Convención de Kütahya: Siria y Adana para el de Kavalalı", "c16c5a94"], "d": ["La Sublime Puerta dejó a Mehmed Ali, además de Egipto, Creta y el Hiyaz, los gobiernos de Damasco, Alepo, Trípoli de Siria y Sidón, y a Ibrahim Pasha la muhassıllık de Adana. A cambio, el ejército se retiró al sur del Tauro. No fue un tratado sino firmanes concedidos por el sultán a un gobernador: el problema no estaba resuelto, solo aplazado.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Se completó desde Gülek la retirada del ejército egipcio de Anatolia", "a53ac2a3"], "d": ["Tras el arreglo de Kütahya, las fuerzas egipcias evacuaron Anatolia; hacia mediados de junio todo el ejército había pasado a la Cilicia por el desfiladero de Gülek. La costa de İçil (Mersin, Silifke) vuelve a la administración otomana; la muhassıllık de Adana y Siria quedan en manos de Egipto.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Tratado de Hünkâr İskelesi", "da741d5c"], "d": ["Se firmó con Rusia una alianza defensiva mutua de ocho años. Según una cláusula secreta, si Rusia era atacada, los otomanos cerrarían los estrechos a los buques de guerra. Fue una de las decisiones más controvertidas de la diplomacia otomana e hizo que Gran Bretaña participara activamente en la cuestión egipcia.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Rebelión de Palestina-Nablus contra la administración egipcia", "4fe43e27"], "d": ["El servicio militar obligatorio, la recogida de armas y los nuevos impuestos provocaron una amplia sublevación en Palestina. La rebelión fue reprimida con dureza; el apoyo de la administración egipcia entre la población local se erosionó rápidamente.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Fin de la administración egipcia de Maraş (aproximado)", "bb46ca42"], "d": ["Si la frase de duración «casi diecinueve meses» de la TDV se cuenta desde la ocupación de 1833, la administración egipcia termina hacia el verano de 1834. El hecho de que Mustafa Bey, de los Küçükalioğulları, no pudiera resistir en 1834 al ejército egipcio y se retirase hacia Maraş muestra también que Maraş era entonces un refugio fuera del control egipcio.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Sublevación del Yebel Druso", "12e74626"], "d": ["La resistencia surgida en la región drusa duró dos años. El descontento acumulado en Siria dejaría desguarnecida la retaguardia del ejército egipcio cuando en 1840 las flotas aliadas desembarcaron en la costa.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali anunció su intención de independencia", "48633bbd"], "d": ["El gobernador declaró a los cónsules de las grandes potencias que pensaba proclamar la independencia de Egipto y Siria. Gran Bretaña se opuso a ello de manera terminante: el nacimiento en el Mediterráneo de un Estado fuerte y cercano a Francia amenazaría la ruta de la India.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["El ejército otomano cruzó el Éufrates", "9af1ea69"], "d": ["Mahmud II lanzó su ejército a la frontera siria para recuperar lo perdido en Kütahya. El oficial prusiano Moltke, presente en el ejército como asesor, objetó la elección de posiciones y el ataque prematuro; sus objeciones no fueron escuchadas.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Batalla de Nizip: el ejército otomano se dispersó", "156b3cdf"], "d": ["El ejército otomano, mal desplegado, fue derrotado en pocas horas. El sultán murió antes de que la noticia de la derrota llegara a Estambul; en pocos días el Estado perdería su ejército, su soberano y después su flota.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Muerte de Mahmud II", "07eccfff"], "d": ["El sultán, que durante su reinado de treinta y un años abolió los jenízaros y restableció la administración central, falleció sin haber vencido a su mayor adversario. Su enfermedad no había recibido un diagnóstico acertado. Su muerte se mantuvo oculta hasta el 30 de junio, hasta que se tomaron medidas militares en la ciudad por temor a que se movilizara la mentalidad jenízara.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Acceso al trono de Abdülmecid y funeral de Mahmud II", "d0f3d2cc"], "d": ["A la muerte de su padre, Abdülmecid, de dieciséis años, subió al trono. El mismo día el féretro de Mahmud II fue llevado al Palacio de Topkapı; no se produjeron los disturbios temidos y amplias masas de musulmanes y no musulmanes participaron en el cortejo fúnebre.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Entrega de la flota a Alejandría", "a53e6103"], "d": ["El kapudán-ı derya Ahmed Fevzi Pasha, sospechando que el gran visir Koca Hüsrev Pasha entregaría la flota a Rusia, llevó la flota a Alejandría y la entregó a Mehmed Ali. El Estado otomano quedó en el mismo mes sin ejército, sin sultán y sin flota.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Nota conjunta de las grandes potencias", "2a3b8316"], "d": ["Las cinco potencias entregaron una nota a la Sublime Puerta pidiéndole que no llegara a un acuerdo por su cuenta en la cuestión egipcia. Así, un asunto interno pasó oficialmente a ser una «cuestión europea»; el Estado otomano perdió de hecho la facultad de decidir sobre su propia provincia.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Tratado de Londres: cuatro potencias al lado del Imperio otomano", "a517f775"], "d": ["El tratado, firmado dejando fuera a Francia, dirigió un ultimátum a Mehmed Ali: si aceptaba en diez días, el gobierno hereditario de Egipto y Acre con carácter vitalicio; si aceptaba en veinte días, solo Egipto; si rechazaba, nada. El gobernador lo rechazó.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardeo de Beirut y desembarco aliado", "0905ce92"], "d": ["La flota anglo-austríaca bombardeó Beirut; se repartieron armas a la población que se sublevó contra la administración egipcia en el Monte Líbano. El control de Ibrahim Pasha en Siria se derrumbó entre la rebelión interna y la intervención exterior.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beirut y las ciudades costeras se perdieron", "09bdaf23"], "d": ["Tras los combates en dirección a Baalbek, las fuerzas egipcias se retiraron de la costa. En el mapa la costa libanesa sale del tono tributario y vuelve a la administración otomana directa.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Acre cayó en dos horas", "5aec21f0"], "d": ["En el bombardeo de la flota aliada estalló el polvorín de la fortaleza y Acre se rindió en pocas horas. La fortaleza que Ibrahim Pasha había podido tomar ocho años antes en seis meses mostró la superioridad de la artillería naval.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Convención de Alejandría", "85cb47b0"], "d": ["Mehmed Ali aceptó renunciar a Siria, Adana, Creta y el Hiyaz, devolver la flota otomana y reconocer la soberanía del sultán; a cambio se aseguró el gobierno hereditario de Egipto.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["El ejército egipcio evacuó Siria y la Cilicia", "719a28dc"], "d": ["Terminó la ocupación de nueve años; el ejército de Ibrahim Pasha regresó a Egipto por el Sinaí. En el mapa, la amplia franja que va de Alepo a Gaza y de Adana a Creta pasa de nuevo a la administración otomana directa. Otros asentamientos perdidos en la misma fecha: Urfa, Maraş, Tarso, Antioquía, Candía (Creta), Hama, Damasco, Jerusalén, Jaffa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Firmán: el gobierno de Egipto quedó hereditario en la familia de Kavalalı", "87b89ff8"], "d": ["El firmán del sultán reconoció el gobierno de modo que pasara de padre a hijo dentro de la dinastía; en contrapartida, el número de efectivos del ejército se redujo a dieciocho mil, los impuestos se vincularon a Estambul y se suprimió la facultad de acuñar moneda y de concluir tratados. Egipto siguió siendo una provincia, pero ya era el país de una dinastía aparte. La administración del Hiyaz y de los Haramain volvió a la Sublime Puerta. Otros asentamientos que vuelven de la capa tributaria a la directa en la misma fecha: La Meca, Medina, Yeda, Yanbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Convención de los Estrechos de Londres", "0e95a1ea"], "d": ["La convención, que sustituyó a la de Hünkâr İskelesi, dispuso que los estrechos permanecieran cerrados en tiempo de paz a todos los buques de guerra. El privilegio que Rusia había obtenido por sí sola pasó así a ser garantía común de Europa; la cuestión de los estrechos adquirió un estatuto internacional.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ibrahim Pasha fue de hecho gobernador de Egipto", "9e14f5d9"], "d": ["En lugar de Mehmed Ali, que envejecía y perdía las facultades mentales, fue nombrado gobernador su hijo Ibrahim Pasha. Pero pocos meses después, en noviembre de 1848, murió antes que su padre.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Muerte de Mehmed Ali Pasha de Kavalalı", "871310e0"], "d": ["El gobernador, nacido en Kavala, que fundó una dinastía en Egipto y llevó dos veces al imperio al borde del abismo, murió a los ochenta años. La dinastía que fundó reinó en Egipto hasta 1953; el Estado, por su parte, al ver que solo había podido cerrar la herida que él abrió mediante la intervención europea, avanzó por el camino de las Tanzimat.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Solimán b. Kutalmış fue derrotado y murió en Ayn Salm; Antioquía salió de manos de los selyúcidas de Anatolia", "0412dfa1"], "d": ["Solimán b. Kutalmış, que había tomado Antioquía a Bizancio en 1084, murió en la batalla de Ayn Salm que libró con Tutuş, soberano de los selyúcidas de Siria; la ciudad pasó al control del sultán de los Grandes Selyúcidas Malik Shah y fue nombrado gobernador Yaghi-Siyan.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Murió Malik Shah; Antioquía, junto con Yaghi-Siyan, quedó ligada a Tutuş, de los selyúcidas de Siria", "c61da1b4"], "d": ["Tras la muerte del sultán de los Grandes Selyúcidas Malik Shah, el Estado se dividió entre los herederos; Yaghi-Siyan, gobernador de Antioquía, quedó ligado a Tutuş, señor de Siria.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Nicea se rindió a los cruzados; el centro selyúcida se replegó a Konya, Bizancio comenzó a recuperar Anatolia occidental", "8a4e90fa"], "d": ["Tras el asedio de Nicea por los cruzados, la ciudad se rindió a Bizancio el 19 de junio de 1097; el sultán selyúcida Kılıç Arslan I replegó su centro hacia el interior, a Konya, y Bizancio recuperó lugares como Éfeso, en las costas de Anatolia occidental.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Kılıç Arslan II tomó a Bizancio Dorileo (Eskişehir) y Kütahya", "3ddee6c2"], "d": ["Tras Miriocéfalo (1176), las fortalezas bizantinas de Dorileo y Kütahya, en el interior de Anatolia, pasaron a manos de Kılıç Arslan II en 576/1180, en los últimos años de Manuel o después de su muerte.", "4358e7d4"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Muerte de Ertuğrul Gazi y paso de Osman Bey al beylicato: la herencia de Söğüt y Domaniç", "395fb9fa"], "d": ["Según la TDV, Ertuğrul Gazi falleció en el año 680 (1281-82); el artículo registra que también se dan las fechas de 1288 y 1289. Osman Bey no heredó de su padre una ciudad conquistada, sino las dos concesiones que el sultán selyúcida había dado a Ertuğrul, al instalarlo en la línea más avanzada de la región fronteriza: el invernadero (yurtluk) en Söğüt y el pasto de verano (yaylak) en Domaniç. Es decir, el beylicato empezó no con una herencia de conquista, sino con dos concesiones de pastos; en el mapa estos dos lugares se muestran como «herencia» y no como «conquista».", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Vísperas Sicilianas — la casa de Anjou perdió la isla de Sicilia", "547db635"], "d": ["La sublevación que estalló en Palermo, a la hora de las vísperas del lunes de Pascua, contra el gobierno de Carlos I de Anjou arrancó la isla de Sicilia a la casa de Anjou. El Reino de Sicilia quedó dividido en dos: la isla se orientó hacia Aragón, mientras que la casa de Anjou se mantuvo en el reino continental con sede en Nápoles. Las posesiones exteriores de la dinastía en el Adriático y el Mediterráneo permanecieron también vinculadas a este reino: Corfú, en su poder desde 1267, y Durazzo, que tenían desde la década de 1270, continuaron como parte del Reino de Nápoles; los castillos de Valona, Kanina y Himara, en la costa de Albania, siguieron igualmente en el reino con sede en Nápoles (el comandante de Valona, John of Taxis, resistió a los bizantinos durante todo 1282; Durazzo, Valona y Kanina pasaron a Bizancio probablemente a comienzos de 1285). Malta, en cambio, sólo pasó a manos de los aragoneses en 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Incursión a Kulacahisar: primera operación militar de Osman Bey", "79b00b14"], "d": ["Artículo Osman I de la TDV: «Saqueó e incendió el pequeño castillo de Kulaca, cerca de İnegöl (684/1285)». Es la primera acción militar de Osman Bey que puede fecharse en las fuentes. No se ocupó ningún asentamiento permanente, sino que se saqueó y quemó el castillo; por tanto, más que una conquista es una incursión fronteriza clásica. Se considera el punto de partida de la actividad militar del beylicato.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Conquista de Karacahisar: primera ciudad ganada y dominio de Eskişehir", "178ae619"], "d": ["Artículo Osman I de la TDV: en el año 687 (1288) Osman Bey «conquistó Karacahisar y se hizo dueño de Eskişehir». Es la primera verdadera ganancia urbana del beylicato y, según la tradición, con este éxito Osman Bey ascendió en la frontera al sanjacbeyilato; se transmite que en Karacahisar se leyó la primera jutba del viernes en su nombre y se nombró allí al primer cadí. El artículo Eskişehir de la TDV señala que la tradición otomana da la fecha de 1291, pero que su exactitud es dudosa.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Caída de Acre ante los mamelucos — expulsión de los cruzados de la costa de Siria: Sidón y Beirut", "3ca7a464"], "d": ["Acre, que durante mucho tiempo fue el centro del Reino Cruzado de Jerusalén, fue conquistada por el sultán mameluco al-Ashraf Jalil, y el dominio de los cruzados en Palestina llegó a su fin. Los caballeros templarios que se retiraron de Acre se refugiaron en Sidón; al acercarse el ejército mameluco abandonaron el castillo marítimo y huyeron a Chipre, y la ciudad pasó a los mamelucos ese mismo verano. Beirut, en manos de los cruzados desde 1197, fue tomada también en 1291 por el gobernador de Damasco, Sanŷar al-Shuŷāʿī. Así, la presencia cruzada de dos siglos fue borrada de la costa sirio-palestina.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Conquista de Bilecik y Yarhisar mediante un ataque nocturno", "f461b0af"], "d": ["Artículo Bilecik de la TDV: «Aunque los demás tekfures de la región, entre ellos el tekfur de Bilecik, prepararon un atentado contra Osman Gazi, al conocerse la trama las fuerzas otomanas conquistaron Yarhisar y Bilecik con un ataque repentino (1299)». Las dos fortalezas fueron tomadas en una sola operación, en el mismo ataque nocturno. Esta fecha es el punto de inflexión aceptado como año de fundación del Estado otomano. Otro lugar incorporado en la misma fecha: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Batalla de Koyunhisar (Bapheus): primera gran victoria sobre el ejército bizantino", "584a9512"], "d": ["Artículo Osman I de la TDV: Osman Bey combatió y derrotó al ejército bizantino en Bapheus (Koyunhisar) el 27 de julio de 1302. Esta victoria es el punto de inflexión que elevó a Osman Bey de bey fronterizo regional a fundador de dinastía. Tras la batalla, la llanura de Bursa entró bajo control otomano y comenzó el bloqueo de Iznik.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Victoria de Dimbos y subsiguiente toma de Kite y Ulubat", "e168ab64"], "d": ["Artículo Osman I de la TDV: en el año 702 (1303) la alianza formada por los tekfures de Bursa, Kestel, Kite y Adranos fue derrotada en el desfiladero de Dimbos; el enemigo fue empujado combatiendo hasta el estrecho paso y el tekfur de Kestel murió en el campo de batalla. Inmediatamente después de la victoria se tomaron las fortalezas de Kite y Ulubat, con lo que se cortó la comunicación terrestre de Bursa y se estrechó su bloqueo. El joven Orhan participó también en esta batalla.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Campaña del Sakarya: toma de Leblebicihisar, Lefke, Mekece y Geyve", "a51ba4d3"], "d": ["El artículo Osman I de la TDV da el orden de la campaña del Sakarya de 704 (1304): «Cuando llegó a Leblebüci Hisarı, el tekfur se sometió... Llegó a Lefke... Alcanzó Mekece... Fue a Geyve y tomó la fortaleza que encontró vacía». Lefke es la puerta del valle del Sakarya que se abre hacia Bilecik. Esta sola campaña puso bajo control otomano la cadena de fortalezas a lo largo del valle y cerró el flanco oriental de la cuenca de Iznik.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Quíos pasó al control de la familia genovesa Zaccaria", "9eebe4de"], "d": ["Ante la amenaza de los Aydínidas, el emperador bizantino pidió ayuda al genovés Benedetto Zaccaria; la isla pasó a su control (vasallaje nominal bizantino). El dominio de los Zaccaria duró hasta 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samos pasó a propiedad de los genoveses (Zaccaria) de Quíos", "0e6f51e3"], "d": ["La familia genovesa Zaccaria, que tomó el control de Quíos, incorporó a su propiedad también Samos, casi despoblada (TDV: 1304-1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Conquista de las fortalezas del desfiladero de Geyve: Karaçepüş, Karatigin y Absu", "76907c78"], "d": ["Artículo Orhan de la TDV: en la campaña del Sakarya de 705 (1305), Orhan «conquistó las fortalezas de Karaçepüş (Katoikia), de Karatigin ante Iznik y de Absu (Hypsu: en el desfiladero de Geyve)». Estas tres fortalezas, al cerrar el paso entre el valle del Sakarya y la cuenca de Iznik, cortaron por completo la ayuda terrestre a Iznik. En Karaçepüş y Absu, en el desfiladero de Geyve, se instaló a Gazi Abdurrahman; la ciudad ya solo podía ser tomada por hambre.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Campaña de Adranos (Orhaneli): última campaña de Osman Bey", "4811546c"], "d": ["El artículo Orhan de la TDV registra la campaña de otoño de 1323 contra la fortaleza de Adranos como la última campaña de Osman Bey. El tekfur de Adranos era miembro de la alianza de tekfures formada veinte años antes en Dimbos contra los otomanos; esta campaña significó saldar aquella cuenta. El día exacto de la conquista de la fortaleza no se conoce; la operación fue continuada por Orhan Bey.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Fallecimiento de Osman Gazi y acceso de Orhan Bey al beylicato", "021487cd"], "d": ["Osman Gazi, que dio nombre al beylicato, falleció en 724 (1324), según atestiguan las fundaciones piadosas (vakfiye) de Asporça Hatun y de Mekece. Su hijo Orhan, que desde 1305 estaba al frente del ejército en las campañas, ocupó la jefatura del beylicato a la muerte de su padre sin que hubiera disputa alguna por el trono. Que la generación fundadora transmitiera el estandarte sin sobresaltos muestra que la dinastía superó en calma su primera gran prueba en el camino que lleva de beylicato de frontera a Estado.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Quíos fue arrebatada a los Zaccaria y ligada a Bizancio", "f6741b26"], "d": ["El emperador Andrónico III alejó de la isla a los Zaccaria y ligó la isla a Bizancio con el gobierno de Benedetto III. La isla sería ocupada en 1346 por el genovés Simone Vignosi.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samos volvió de los Zaccaria a Bizancio (cadena de Quíos)", "08034974"], "d": ["Con la caída del señorío de los Zaccaria (la vinculación de Quíos a Bizancio en 1329), terminó también la propiedad genovesa en Samos.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Batalla de Pelekanon (Maltepe) y toma de todo Kocaeli", "389e7bd4"], "d": ["Artículo Orhan de la TDV: el primer día de la batalla, Orhan Gazi envió una fuerza de trescientos hombres para atraer hacia sí al ejército bizantino; el segundo día, al descender a la llanura las tropas al mando de Pazarlu, la batalla se amplió y, herido el emperador por una flecha, cundió el pánico en el ejército bizantino. El resultado es claro: «Orhan se apoderó de todo Kocaeli; tras la victoria los de Iznik no tuvieron ya ninguna esperanza». Las localidades costeras de Hereke a Üsküdar entraron bajo dominio otomano y Gebze fue convertida en centro de la región. Fue el último ejército imperial bizantino que acudió para salvar Constantinopla.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Fundación de la primera madrasa otomana en Iznik", "c85fb625"], "d": ["Orhan Bey, inmediatamente después de tomar Iznik, nombró cadí allí a Çandarlı Kara Halil, convirtió una basílica en mezquita y, mandando construir junto a ella un imaret y una madrasa, inició la reconstrucción de la ciudad. Según el artículo Dâvûd-i Kayserî del TDV, la construcción de la madrasa se terminó en 1336 y Orhan Gazi puso a Dâvûd-i Kayserî como profesor con 30 akçe diarios. Esta madrasa es el primer paso institucional de la vida científica otomana; el beylicato añadió así una tradición de saber al poder de conquista. La transformación de una capital bizantina conquistada en centro del saber islámico fue la primera señal concreta de la pretensión otomana de ser un Estado asentado.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Bizancio pasó a ser tributario: sitio de Izmit y tratado", "0c1ec8d3"], "d": ["Artículo Orhan de la TDV: en el verano de 733 (1333) Orhan sitió Izmit con un gran ejército y con mangoneles, y el emperador accedió a un tratado. A cambio de que desistiera del sitio, Bizancio aceptó pagar a Orhan 12.000 monedas de oro (hyperpyra) al año; «así, a los ojos del emir otomano, Bizancio quedó como un país tributario». A cambio, Orhan sería amigo del emperador y no atacaría las ciudades sujetas a Bizancio. Que un beylicato fronterizo impusiera tributo al Imperio romano de Oriente fue la proclamación de cuánto había girado el equilibrio de poder.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samotracia pasó de los venecianos a la familia genovesa Gattilusio", "c499ed5f"], "d": ["La familia genovesa Gattilusio expulsó de la isla a los venecianos, que la poseían desde 1204.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Anexión del beylicato de Karesi: Balıkesir, Pérgamo, Biga, Edremit y Erdek", "c7cb0511"], "d": ["El artículo Orhan de la TDV (İnalcık) fecha la anexión en 735 (1334-35): a la muerte de Demirhan Bey, los gazis de Karesi y Hacı İlbey invitaron a Dursun Bey al trono y pidieron ayuda a Orhan. Orhan marchó primero sobre Balıkesir; cuando Dursun Bey, que iba a unas conversaciones de paz, murió por una flecha disparada desde la fortaleza de Pérgamo, el beylicato se incorporó por completo al territorio otomano. En la misma operación Kirmasti y Mihaliç se sometieron, se tomó Gölyazı y Ulubat, antes dejada con salvoconducto, fue ocupada definitivamente. Orhan nombró a Süleyman Pasha para el sanjacado de Karesi e hizo de Biga el centro fronterizo; así se ganó el cuadro marinero para el paso a Rumelia. Nota: el artículo Karesioğulları de la TDV da para el mismo hecho la fecha de 746 (1345); la enciclopedia se contradice a sí misma. Otro lugar incorporado en la misma fecha: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samos pasó a propiedad de la Maona de Quíos", "01628b2f"], "d": ["Con la toma de Quíos por el genovés Simone Vignosi y la entrega de la administración a la compañía de la Maona, Samos pasó también a propiedad de los genoveses (Maona) de Quíos (TDV: 1346-1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Primeras capitulaciones de Orhan Gazi con los genoveses", "e64cb196"], "d": ["Orhan Gazi, que durante la guerra veneciano-genovesa se había aliado con los genoveses, tras la batalla del Bósforo de febrero de 1352 envió 1000 arqueros a la defensa de Pera y proporcionó 60.000 monedas de oro para el transporte de tropas; a cambio concedió a los genoveses las primeras capitulaciones. El texto completo del acuerdo no ha llegado hasta hoy. Es el primer acuerdo oficial de los otomanos con una potencia marítima europea, y sería renovado treinta y cinco años después, en 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Toma de Galípoli — cabeza de puente permanente en Rumelia", "ba51a160"], "d": ["Los otomanos tomaron en 1354 Galípoli, cuyos alrededores habían conocido entre 1349 y 1352 como aliados de Cantacuceno; el gran terremoto que derribó las murallas de la ciudad les dio la ocasión. La estrecha cabeza de puente de Çimpe se convirtió así en una verdadera base en la orilla de Rumelia del estrecho, y la puerta hacia Tracia quedó abierta de par en par. Galípoli se perdería en 1366 por la cruzada de Saboya, pero entraría definitivamente en el dominio otomano con la segunda conquista de 1376. Otros lugares incorporados en la misma fecha: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Muerte de Süleyman Paşa, conquistador de Rumelia", "2dc98228"], "d": ["Süleyman Paşa, hijo mayor de Orhan Bey y artífice de las conquistas de Rumelia, murió cayendo del caballo durante una cacería en el otoño de 1357, la más aceptada de las fechas que las fuentes dan como 758 (1357), 759 y 760 (1359). La muerte del príncipe, que entre 1352 y 1354 estableció con sus travesías la presencia otomana permanente en Rumelia, dejó el orden de sucesión a su hermano Murad. La tumba de Süleyman Paşa, sepultado en Bolayır, siguió siendo el monumento dinástico más antiguo de los otomanos en Europa.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Ley de Pençik — sentado el fundamento del Cuerpo de Jenízaros", "e5877c2d"], "d": ["Tras las conquistas de Rumelia, por consejo del ulema Karamanlı Kara Rüstem, entró en vigor el sistema de pençik, que prevé que una quinta parte de los prisioneros de guerra, o su equivalente en dinero, se reserve al Estado. Con la selección de entre estos prisioneros, su crianza en familias turcas y su alistamiento, se formó el núcleo de una fuerza de infantería permanente dependiente directamente del sultán: el Cuerpo de Jenízaros. Con esta disposición comenzó la transformación de un beylicato de frontera basado en la caballería tribal en un Estado con ejército central.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Descenso a Tracia occidental: conquista de Gümülcine", "9ef69221"], "d": ["Las fuerzas de marca que, tras la toma de Adrianópolis, se dirigieron al oeste del Maritsa, bajo el mando de Gazi Evrenos Bey, se apoderaron de Gümülcine, centro de Tracia occidental. La ciudad se convirtió en el cuartel avanzado desde el que Evrenos Bey llevaría sus incursiones a Macedonia. Así, la parte de Tracia que se extiende hasta la costa del Egeo pasó al control otomano y se abrió el camino de Salónica.", "0206d2bb"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Al oeste de Filibe: incorporación de Tatarpazarcığı e İhtiman", "1664d0e1"], "d": ["Tras la toma de Filibe en 1372, Tatarpazarcığı, en el extremo superior del valle del Maritsa, e İhtiman, que guardaba el paso hacia Sofía, quedaron sujetas a la administración otomana. Esta línea, en manos de señores locales vasallos desde la batalla de Çirmen, pasó a administración directa y la ruta Filibe-Sofía quedó sin interrupción. Este avance es la preparación del camino que doce años después conduciría a la conquista de Sofía.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Rebelión de Savcı Bey — sublevación conjunta de un príncipe y del heredero bizantino", "75198c33"], "d": ["Savcı Bey, hijo de Murad I, y Andrónico Paleólogo, hijo del emperador bizantino Juan V, se sublevaron simultáneamente contra sus padres en Bursa y Constantinopla a comienzos de mayo de 1373. Esta alianza, que unía a los herederos de dos dinastías, fue sofocada rápidamente; Savcı Bey fue capturado, cegado con hierro candente y ejecutado. La fecha 787 (1385) que la tradición otomana da para la rebelión es errónea; el suceso se sitúa inmediatamente después de los años en que Bizancio pasó a ser vasallo otomano y muestra lo entrelazados que estaban los dos palacios.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Valles del Struma y del Mesta: incorporación de Köstendil, Petriç, Nevrokop y Drama", "8c0980c4"], "d": ["Los valles del Struma y del Mesta, en manos de señores locales serbios y búlgaros que tras la victoria de Çirmen empezaron a pagar tributo a los otomanos, pasaron a administración otomana directa con el avance de los señores de marca. Con la incorporación de Köstendil, Petriç, Nevrokop y Drama se abrió la mitad oriental de Macedonia y Salónica y Serres quedaron cercadas. La expansión de Rumelia hacia el suroeste en el mapa es resultado de esta campaña.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Tamerlán tomó Herat: fin de la dinastía kert y paso de Jorasán a los timúridas", "15f6019e"], "d": ["Jorasán se hallaba fragmentado en 1380 por la lucha entre los sarbadáridas, los kert y los muzafáridas. Tamerlán, tras enviar a la región a su hijo Mîrân Shah, marchó él mismo sobre Herat y, tras sitiarla durante algún tiempo, recibió la rendición de la ciudad del melik kert Gıyâseddin Pîr Ali. La rebelión surgida tras su partida fue sofocada con sangre por Mîrân Shah y se puso fin a la dinastía kert, que reinaba en Herat desde 1255. Todo Jorasán, de Mashhad a Nishapur, entró en esta fecha bajo administración timúrida.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["Fin del beylicato de Eretna y fundación del Estado de Kadı Burhâneddin", "60dcaf57"], "d": ["Los Eretnaoğulları, nacidos en 1335 de un gobierno provincial ilcánida y que durante cuarenta y seis años gobernaron Anatolia central con centro en Sivas y Kayseri, se desintegraron por las disputas internas de palacio. Kadı Burhâneddin, que se había hecho visir en mayo de 1378, tras eliminar a sus rivales Kılıcarslan y Hacı Şadgeldi, proclamó su sultanato en el otoño de 1381, puso fin al beylicato y fundó el Estado que se conoce por su nombre. Así cambió de manos el vecino oriental de los otomanos; la línea Sivas-Kayseri permanecería en poder de Kadı Burhâneddin durante diecisiete años más.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Avance hacia el interior de Macedonia: conquista de Manastır y Ohrid", "63bb7838"], "d": ["Manastır (Bitola), en la Via Egnatia, y Ohrid, a orillas del lago, entraron en la administración otomana durante las incursiones hacia Albania. Ambas eran puntos clave del camino que llegaba al Adriático; Ohrid era además la sede arzobispal ortodoxa más antigua de los Balcanes. El TDV registra que no hay información cierta sobre la fecha de la conquista de Ohrid y que se han propuesto 787 (1385) y 797 (1395), después de la muerte de Marko Kraljević; aquí se ha adoptado 1385. Manastır sería en los siglos siguientes uno de los centros militares más importantes de Rumelia.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Batalla de Savra — apertura de las puertas de Albania", "dda6671b"], "d": ["A petición de ayuda del señor albanés Karlo Topia, acosado por la casa de Balsha, las fuerzas otomanas derrotaron en la llanura de Savra al ejército de Balsha II; Balsha perdió la vida en el campo de batalla. Esta batalla, en la que se entró por invitación de un señor local, proporcionó a los otomanos la primera influencia duradera en las tierras albanesas que se extienden hasta las costas del Adriático. Esta política, que aprovechaba las disensiones entre los señores de la región, sería durante el siglo siguiente el método invariable de las conquistas balcánicas.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["La «campaña de los tres años» de Tamerlán: toma de Azerbaiyán y del norte de Irán", "2a98ec51"], "d": ["Tamerlán, que durante las campañas de Jorasán había visto de cerca la dispersión de Irán, marchó hacia el oeste en 788 (1386). En la campaña de 1386-1388, llamada «campaña de los tres años», pasó a Azerbaiyán por Mazandarán, Luristán y Georgia y llegó a Karabaj; Tabriz, Ardabil, Urmia y Najicheván entraron bajo administración timúrida. La toma del norte de Irán y de Azerbaiyán fue también el comienzo de una larga disputa con la Horda de Oro, como antaño entre el ulus de Yochi y los iljánidas.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Batalla de Frenkyazısı y asedio de Konya — primera campaña contra Karaman", "af4e5d77"], "d": ["Murad I salió en persona a campaña contra Karamanoğlu Alâeddin Ali Bey, que, aunque yerno suyo, se sentía incómodo por la expansión otomana en Anatolia occidental; en la batalla librada en el lugar llamado Frenk Yazısı, el ejército otomano, disciplinado y experimentado, venció a las fuerzas de Karaman. A continuación se asedió la fortaleza de Konya, pero con el perdón a Alâeddin Bey el beylicato no fue suprimido por completo. Esta campaña es el acto de apertura de un largo ajuste de cuentas entre los otomanos y Karaman, que duraría un siglo y sólo terminaría con la anexión definitiva de 1468.", "087a605a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Fundación del Arsenal de Galípoli — nacimiento de la flota otomana", "47546241"], "d": ["El primer arsenal organizado del Estado otomano fue fundado en 1390 por Bayezid el Rayo en Galípoli, en el lugar del arsenal que había quedado de los bizantinos. Los otomanos, que heredaron la tradición marinera de los beylicatos de Anatolia occidental, se convirtieron así por primera vez en una potencia naval que construía sus propias naves. Situado en un punto clave del estrecho de los Dardanelos, el arsenal sirvió durante siglo y medio como base principal de la flota otomana, desde el asedio de Constantinopla hasta las campañas del Egeo.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Toma de Varna en la costa del mar Negro", "a84b2abf"], "d": ["En el curso del acorralamiento de las tierras del zarato búlgaro entre el Danubio y el mar Negro, Varna, el mayor puerto de la costa, pasó a la administración otomana. La toma del puerto despejó el avance hacia Dobruja y proporcionó a los otomanos el primer gran embarcadero en la costa occidental del mar Negro. Varna sería, cincuenta y tres años después, también el escenario de la victoria de 1444 en que fue aniquilado el ejército cruzado.", "421a978f"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Fin de la dinastía muzafárida: derrota de Shah Mansûr ante Shiraz", "5fd14eb8"], "d": ["Shah Mansûr, último soberano poderoso de los muzafáridas, que reinaban desde 1318 en Yazd, Fars, Isfahán y Kirmán, se unió a sus parientes y se movió contra Tamerlán. En la batalla cerca de Shiraz, al pasarse al otro bando uno de sus emires, perdió la mayor parte de sus fuerzas y fue derrotado y muerto. Cuando Tamerlán hizo matar después a todos los miembros de la dinastía, terminó el dominio muzafárida y Fars y Kirmán se incorporaron a la administración timúrida.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Incorporación de Amasya a las tierras otomanas", "fe2860cf"], "d": ["El emir de Amasya, sitiado durante la campaña de Bayezid el Rayo en Anatolia central, entregó la ciudad a los otomanos, y Bayezid entró en ella en 1393. El sultán dejó su administración a su hijo Mehmed Çelebi; Amasya, como sanjacado de príncipes, se convirtió desde entonces en uno de los centros de formación más importantes de la dinastía otomana. Esta elección sería decisiva en el posterior Interregno: Çelebi Mehmed llevaría adelante su lucha por reunificar el Estado precisamente desde esta base de Amasya.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Tamerlán tomó Bagdad: los celâyirlíes huyeron a Anatolia", "4d5602b3"], "d": ["Tamerlán tomó Bagdad tras un largo sitio; el soberano de la ciudad, el sultán celâyirlí Ahmed, huyó hacia el oeste y se refugió primero con los mamelucos y después en la corte otomana. Así, la expansión de Tamerlán hacia el oeste entró por primera vez en contacto directo con la esfera de influencia otomana. De aquí parte el primer eslabón de la enemistad entre los dos soberanos.", "2fac674f"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["La región de Nevşehir y Ürgüp pasó de los Karamánidas a manos otomanas", "06ff59e8"], "d": ["En las campañas de Bayezid el Rayo contra los Karamánidas, la región de Nevşehir (Muşkara) y Ürgüp pasó a la administración otomana en 800/1398; en 1402, tras la batalla de Ankara, Timur devolvió la región a los Karamánidas.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Caída del Estado de Kadı Burhâneddin", "b13391e3"], "d": ["Kadı Burhâneddin, caído prisionero de Kara Yülük Osman Bey, soberano de los Ak Koyunlu, ofreció ser liberado a cambio de la entrega de Sivas, pero la población de la ciudad resistió y el sultán fue ejecutado ante las murallas. Los notables de Sivas pusieron a su hijo Alâeddin Ali Çelebi al frente, pero ante la presión de los Ak Koyunlu pidieron ayuda a Bayezid el Rayo; las fuerzas otomanas al mando de Süleyman Çelebi derrotaron a Kara Yülük y se hicieron con la ciudad. Así desapareció el Estado de Kadı Burhâneddin, y Sivas, Tokat, Niksar y Kayseri se incorporaron a las tierras otomanas. Otros lugares incorporados en la misma fecha: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Pulso de Tamerlán: se rechazó la devolución de los fugitivos", "33790bc8"], "d": ["Por la presión de Tamerlán, el sultán celâyirlí Ahmed y el líder de los Kara Koyunlu, Kara Yûsuf, se refugiaron en territorio otomano; Tamerlán pidió la devolución de estos dos fugitivos y Bayezid el Rayo se negó. Entonces comenzaron a intercambiarse entre los dos soberanos cartas con graves insultos recíprocos. El terreno ideológico de la guerra se fijó con esta correspondencia sin que se hubiera movido aún un solo soldado.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Hospital de Yıldırım en Bursa — primer hospital otomano", "5f0dc59a"], "d": ["En los años en que Bayezid el Rayo hacía construir en Bursa la magnífica Mezquita Mayor (Ulucami), dotó también a la ciudad de un dârüşşifa; era el eslabón dedicado a la medicina dentro de su amplio programa de obras pías, compuesto por imaret, madrasa, han y puente. Este edificio, el primer hospital fundado por el Estado, funcionó también como escuela de medicina que formaba médicos y fijó el modelo de las instituciones sanitarias otomanas. La obra, terminada sólo dos años antes del desastre de Ankara, es uno de los últimos eslabones de la visión de Yıldırım de convertir Bursa en capital imperial.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Tamerlán arrasó Sivas", "f4d79de6"], "d": ["Tamerlán, que marchó sobre Sivas guiado por Karayülük Osman Bey, de los Ak Koyunlu, y por Mutahharten, emir de Erzincan, sitió la ciudad dieciocho días y, tras recibir su rendición con la promesa de que no se derramaría la sangre de nadie, cometió una gran matanza; hizo llenar las zanjas con los defensores y cubrirlos vivos. Se destruyeron las obras importantes de la ciudad, empezando por las murallas, y Sivas se desplomó demográficamente. Este fue el primer gran golpe que Tamerlán asestó al territorio otomano, dos años antes de la batalla de Ankara.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Bayezid el Rayo recuperó Erzincan y Kemah", "7047ca08"], "d": ["Bayezid el Rayo, aprovechando que Tamerlán partía en campaña a Siria, tomó Erzincan y Kemah de manos del emir de Erzincan, Mutahharten, sujeto a Tamerlán. Aunque no había intervenido en la destrucción de Sivas, este movimiento significaba un desafío directo a la esfera de influencia de Tamerlán en Anatolia oriental. La relación entre los dos soberanos se hizo desde entonces irreparable.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimátum de Tamerlán desde Tabriz: cuatro condiciones", "3e1ac50e"], "d": ["Tamerlán comunicó mediante un enviado desde Tabriz cuatro condiciones: la devolución de Kemah a Mutahharten, la restitución a sus dueños de las tierras tomadas a los beyes de Anatolia, el envío de un príncipe otomano como rehén y la aceptación del gorro (külâh) y el cinturón como signo de sujeción, y la entrega de Kara Yûsuf. Bayezid no aceptó ninguna; a pesar de la insistencia de los estadistas y de la mediación de Mutahharten, las negociaciones se rompieron. Tamerlán estaba decidido a cerrar definitivamente la cuestión de Anatolia antes de partir a su campaña de China.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Se restableció el beylicato de Saruhan: Manisa salió del dominio otomano", "ac747b05"], "d": ["Tres semanas después del desastre de Ankara, Orhan Bey asumió con apoyo de Tamerlán la jefatura del beylicato y la tierra de Saruhan volvió a ser independiente. La región con centro en Manisa desapareció del mapa doce años después de la anexión otomana de 1390. Esta es una de las primeras aplicaciones, de fecha conocida con certeza, de la política de Tamerlán de resucitar los beylicatos.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["El emir Süleyman huyó a Rumelia con el tesoro del Estado", "0a2b7363"], "d": ["El emir Süleyman, que tomó consigo el tesoro del Estado, los archivos, su familia y sus hermanos en Bursa, pasó en barco desde Gemlik a Güzelcehisar (Anadoluhisarı), llegó desde allí a Galípoli y proclamó su soberanía en Edirne. El traslado a Rumelia del archivo y del tesoro del Estado es el comienzo del desplazamiento del centro de gravedad otomano hacia los Balcanes durante una generación. En el mapa Rumelia se dibuja desde esta fecha con el color propio del emir Süleyman.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Tamerlán restableció los beylicatos de Anatolia: se disolvió la unidad turca", "15187774"], "d": ["Tamerlán, tras la victoria de Ankara, devolvió a los beyes que estaban a su lado sus antiguas tierras. A Karamanoğlu Mehmed y Ali Beyes se dieron la tierra de Karaman, además de Kayseri, Kırşehir, Sivrihisar y Beyşehir; a Germiyanoğlu Yâkub Bey II, Kütahya y la tierra de Germiyan; a Candaroğlu İsfendiyar Bey, además de la línea Kastamonu-Sinope, Çankırı y Kalecik. Las tierras de Aydın, Menteşe y Teke volvieron también a sus antiguas dinastías. La unidad turca de Anatolia que Bayezid el Rayo había construido en diez años se disolvió en un solo verano; en el mapa estos beylicatos reaparecen en sus propios colores.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Tamerlán tomó Esmirna a los caballeros de San Juan", "66dd1dd4"], "d": ["Tamerlán, que descendió hacia el oeste por Kütahya, Denizli, Aydın, Ayasuluk y Tire, sitió y tomó la costera Esmirna, en manos cristianas desde 1344. Tamerlán, que tomó en poco tiempo esta fortaleza que Bayezid el Rayo no había podido tomar en años, tras ocupar también las fortalezas de los alrededores, dejó la tierra de Aydın a sus antiguos dueños y volvió hacia el este. La ciudad pasó desde entonces a la administración de Aydınoğlu Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Îsâ Çelebi se apoderó de Bursa: nació la parte de Anatolia", "955128c1"], "d": ["Îsâ Çelebi, que tras el desastre de Ankara se había retirado hacia Karesi, tomó Bursa mientras Tamerlán estaba en Esmirna. Proclamó su soberanía en la antigua capital, saqueada e incendiada por los soldados de Tamerlán, e hizo acuñar moneda a su nombre; en enero de 1403 era reconocido en Anatolia como soberano de los «turcos». En el mapa, esta parte que se extiende a lo largo de la costa asiática del Mármara aparece con el color propio de Îsâ Çelebi.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Retirada de Tamerlán de Anatolia", "93a98839"], "d": ["Tamerlán, al recibir la noticia de que Bayezid el Rayo había fallecido en Akşehir, dio por terminada su tarea en Anatolia y se dirigió hacia el este. Quedaron atrás los beylicatos que le declaraban lealtad y los príncipes otomanos enfrentados entre sí; algunas ciudades, como Sivas, quedaron en manos de emires sujetos a Tamerlán como Mezid Bey. Tamerlán no volvió a Anatolia, pero el orden fragmentado que estableció duró diez años.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["El emir Süleyman pasó a Anatolia: Bursa pasó a su poder", "9b27aa5f"], "d": ["El emir Süleyman, al saber de la derrota de Îsâ Çelebi, pasó a Anatolia con un ejército poderoso junto con Çandarlı Ali Pasha y tomó Bursa; los registros de marzo de 1404 muestran que Karadeniz Ereğlisi también estaba bajo su administración. Çelebi Mehmed no pudo resistir a Süleyman, que dominó en poco tiempo tanto Rumelia como la mayor parte de Anatolia. En el mapa, desde esta fecha hasta que Çelebi Mehmed recupera Bursa (1410), las dos orillas aparecen de un solo color, en la parte del emir Süleyman.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Batalla de la llanura de Yenişehir: Çelebi Mehmed se retiró a Amasya", "f1568288"], "d": ["Çelebi Mehmed, que había perdido Bursa y Ankara, fue derrotado por el emir Süleyman en la llanura de Yenişehir, perdió todas sus ganancias en Anatolia occidental y se retiró a su base de Tokat-Amasya. Tras esta derrota evitó el enfrentamiento directo y se orientó a consolidar su autoridad en el interior de Anatolia. Así comenzó la fase silenciosa más larga del Interregno.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["El emir Süleyman tomó Ankara a Çelebi Mehmed", "d6a2acd6"], "d": ["El emir Süleyman sitió en 1406 Ankara, que había quedado en manos de Çelebi Mehmed tras la retirada de Tamerlán de Anatolia. El comandante de la fortaleza, Yâkub Bey, resistió algún tiempo, pero entregó la fortaleza a Süleyman por una estratagema del gran visir Çandarlı Ali Pasha. Entonces Çelebi Mehmed se puso en movimiento contra Süleyman, tras llegar a un acuerdo con Karamanoğlu Mehmed Bey.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed recuperó Sivas del timúrida Mezid Bey", "90079b0c"], "d": ["Tras la invasión de Tamerlán, la administración de Sivas se había dejado a Mezid Bey, sujeto a Tamerlán. Çelebi Mehmed, desde Amasya, envió a su comandante Bayezid Pasha a tomar la ciudad y, tras una fuerte resistencia, Sivas pasó por segunda vez a manos de la dinastía otomana. Así la parte de Mehmed alcanzó en el este su antigua frontera, seis años después de la batalla de Ankara.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Fin de la dinastía artúquida: entrega de Mardin a los Kara Koyunlu", "15b06f33"], "d": ["Los artúquidas, que reinaban en Mardin desde 1106 y eran la rama más duradera de la dinastía, no pudieron resistir la presión de los Ak Koyunlu. Melik Ahmed, comprendiendo que no podría defender la ciudad, llegó a un acuerdo con el soberano de los Kara Koyunlu, Kara Yusuf, y le entregó Mardin. Así terminó el dominio artúquida, que había superado los tres siglos; Mardin y su entorno fueron escenario de la lucha entre Kara Koyunlu y Ak Koyunlu hasta su paso a los otomanos un siglo después.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Batalla de Yanbolu — Musa Çelebi entró en Adrianópolis", "8f978408"], "d": ["Musa Çelebi, que había pasado a Rumelia por Valaquia, derrotó con apoyo valaco y serbio a las fuerzas del emir Süleyman en Yanbolu y entró en Adrianópolis. Por primera vez durante el Interregno (Fetret Devri), Rumelia escapó de las manos del emir Süleyman. Sin embargo, su dominio no fue duradero: cuatro meses después sería derrotado en Kosmidion y se retiraría al interior de los Balcanes.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Batalla de İnceğiz — primera derrota de Çelebi Mehmed en Rumelia", "3c35cd43"], "d": ["Çelebi Mehmed, que había pasado a Rumelia con las naves bizantinas, se enfrentó a Musa Çelebi en İnceğiz; Musa derrotó a Mehmed con los siete mil jenízaros bajo su mando, y Mehmed tuvo que regresar a Anatolia. Esta derrota llevó a Mehmed a adoptar la estrategia de ganarse a los señores de las marcas de Rumelia y al despotado serbio en lugar de combatir directamente. Con esta diplomacia se preparó el terreno de la victoria de Çamurlu, nueve meses después.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Asedio de Konya y tratado con los Karamanoğlu — recuperación de Hamid-ili, Said-ili, Beyşehir, Seydişehir y Akşehir", "0996257e"], "d": ["Contra los Karamanoğlu, que durante el Interregno atacaron las tierras otomanas y asediaron e incendiaron Bursa, Çelebi Mehmed organizó una gran campaña y puso sitio a Konya en Muharram de 818. Karamanoğlu Mehmed Bey II tuvo que pedir la paz; por el tratado, Hamid-ili (región de Isparta) y Said-ili volvieron a incorporarse a las tierras otomanas, también se devolvieron Beyşehir, Seydişehir y Akşehir, y Sivrihisar, que Tamerlán había dado a los Karamanoğlu en 1402, volvió a los otomanos. Esta campaña, con la que empezó a remendarse la unidad de Anatolia disuelta en la batalla de Ankara, es una de las razones concretas por las que Çelebi Mehmed es considerado «segundo fundador».", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Toma de Esmirna a Cüneyd Bey de los Aydınoğlu", "2377ca51"], "d": ["Esmirna, sede de Cüneyd Bey de los Aydınoğlu —que durante el Interregno cambió constantemente de bando entre los príncipes—, fue tomada por Çelebi Mehmed tras un asedio de diez días; Cüneyd fue perdonado y enviado al beylicato (sanjacado) de Nicópolis. La ciudad, que Tamerlán había devuelto a los Aydınoğlu en 1402, volvió así a manos otomanas trece años después. Cüneyd volvería a apoderarse de la ciudad en 1422, y el asunto sólo sería cerrado por Murad II en 1424-1426.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Ejecución de Torlak Kemal — Saruhan pasa definitivamente a los otomanos", "8a09dbf1"], "d": ["Torlak Kemal, que dirigía en Anatolia occidental el brazo del movimiento del sheij Bedreddin, fue derrotado en la región de Manisa y ejecutado. A partir de esta fecha la región de Saruhan quedó definitivamente bajo control otomano, y el beylicato que Tamerlán había resucitado en 1402 desapareció de la historia. Así se limpiaron los últimos restos políticos del Interregno en Anatolia occidental.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Conquista de Valona, Berat y Kanina", "1e1949b8"], "d": ["En 1417 los otomanos pusieron bajo su dominio Valona, en la costa del Adriático, junto con la ciudad de Berat, en el interior del país, y el castillo de Kanina. Un año después fracasó el intento de Venecia de recuperar la ciudad, y con el establecimiento allí de una organización de sanjacado la autoridad otomana se hizo permanente. La toma de Valona, que por primera vez hizo a los otomanos dueños directos de un puerto en el Adriático, les proporcionó un trampolín ultramarino frente a Italia.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Recuperación de Anatolia central: Kayseri y Kırşehir", "204eacb3"], "d": ["Las ciudades de Anatolia central que habían pasado a manos de los Karamanoğlu durante el Interregno volvieron a la administración otomana en el curso de las campañas de Çelebi Mehmed para recomponer el Estado. Con la incorporación de Kayseri y Kırşehir se recuperó en gran parte la cuenca del Kızılırmak, perdida en la batalla de Ankara. Este avance es la continuación de la política de orientación hacia el este iniciada cuatro años antes con el asedio de Konya.", "c663fc08"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Fallecimiento de Mehmed I y entronización de Murad II", "98acac77"], "d": ["Mehmed I, que puso fin al Interregno y volvió a reunir en una sola mano el país otomano, murió en Edirne el 25 de junio de 1421, y su hijo Murad subió al trono en Bursa. Según el acuerdo hecho con Bizancio antes de su muerte, los hijos menores serían enviados como rehenes junto al emperador, y el emperador no pondría en libertad al pretendiente al trono Mustafa Çelebi, que tenía en su poder; Murad II se negó a enviar sus hermanos al emperador.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Liquidación definitiva de los Tekeoğlu: toma de Antalya", "e65565b2"], "d": ["El beylicato de los Tekeoğlu, restablecido tras la batalla de Ankara por obra de Tamerlán, llegó a su fin cuando las fuerzas otomanas al mando de Hamza Bey asediaron Antalya; fue eliminado Osman Çelebi, el último hombre importante del beylicato. Así, el territorio de Teke, en la costa mediterránea, se incorporó definitivamente al Imperio otomano tras veintiún años de separación. El beylicato había reinado en Antalya desde 1321 como rama desgajada de los Hamidoğlu.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Campaña de Turahan Bey a la Morea y derribo de la muralla del Hexamilion", "c6c2706d"], "d": ["Cuando Bizancio apoyó al pretendiente rival al trono, Mustafa Çelebi, Murad II envió a Turahan Bey contra la Morea. Turahan Bey derribó la muralla del Hexamilion, que cerraba de lado a lado el istmo de Corinto, entró en la península y causó grandes destrozos. La paz se logró con la condición de que la muralla no volviera a levantarse y se pagara un tributo anual; el despotado de la Morea quedó así militarmente indefenso, y se preparó treinta y siete años antes el terreno de la conquista definitiva de 1460.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Los monasterios del Athos (Aynaroz) pasan bajo protección otomana", "562de5ea"], "d": ["En los años en que Salónica estaba sitiada, la república monástica del Athos, en el dedo oriental de la Calcídica, se dirigió a Murad II pidiendo protección y aceptó el dominio otomano. Se garantizaron los derechos de propiedad y de culto de los monjes; los monasterios quedaron libres en sus asuntos internos a cambio de un impuesto. Este régimen fue el ejemplo más duradero de la relación de protección que los otomanos establecieron con las instituciones ortodoxas, y se prolongó cinco siglos.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Anexión del beylicato de los Tâceddinoğlu: Niksar", "370ffd47"], "d": ["Por la presión del beylerbeyi de Amasya, Yörgüç Paşa, Tâceddinoğlu Hüsâmeddin Hasan Bey entregó en 830 (1427) las llaves de su país, cuyo centro era Niksar; se le concedió un sanjacado en Rumelia. Así terminó el beylicato, fundado en la segunda mitad del siglo XIV y cuyas fronteras llegaron en ocasiones hasta Kelkit, Amasya, Samsun, Ordu y Giresun. Ese mismo año se registraron también las tierras de los Hacıemiroğlu y se vincularon al sanjacado de Canik; se cerró la época de los beylicatos del mar Negro central.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Cesión de Belgrado a Hungría — Tratado de Tata", "62481183"], "d": ["A la muerte del déspota serbio Stefan Lazarević, en virtud del Tratado de Tata entre el rey húngaro Segismundo y el heredero Đurađ Branković, la fortaleza de Belgrado fue cedida a Hungría. La fortaleza, que se alza en el punto de confluencia del Danubio y el Sava, había estado hasta entonces en manos del despotado serbio y era para los otomanos la llave de la puerta que se abre a Europa central. Esta cesión convirtió a Belgrado, durante cien años, en el obstáculo más duro ante el avance otomano: los asedios de 1440 y 1456 fracasarían y la fortaleza solo caería en 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin pasó de la guarnición Kara Koyunlu a Kara Yülük Osman Bey de los Ak Koyunlu", "d82bc97f"], "d": ["Los Kara Koyunlu administraron con gobernadores Mardin, tomada por Kara Yusuf en 1409; el emir Nâsır, dejado como guarnición, entregó la ciudad en 835 (1432) a Kara Yülük Osman Bey de los Ak Koyunlu. La administración Ak Koyunlu duró hasta comienzos del siglo XVI.", "407382cb"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Suceso de Buçuktepe — primera sublevación de los jenízaros y regreso de Murad II al trono", "6388dda1"], "d": ["El suceso de Buçuktepe, estallado en Adrianópolis y primera sublevación de jenízaros que registra la historia, comenzó con la exigencia de un aumento de medio akçe en sus ulûfe y terminó con la destitución del joven Mehmed II. Murad II partió apresuradamente de Manisa el 8 de Safar de 850 e inició su segundo sultanato. El suceso fue la primera señal de que el cuerpo de los kapıkulu se había convertido en una fuerza con voz en el trono, y moldeó la cautela de toda la vida del Conquistador respecto a los jenízaros.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Incorporación de la costa del Epiro: Arta y Preveza", "796f7ecf"], "d": ["Diecinueve años después de la rendición de Ioánina en 1430, también Arta y Preveza, en la parte costera del despotado del Epiro, pasaron a la administración otomana. Así se puso bajo control el golfo de Ambracia, abierto al mar Jónico, y se completó la conexión marítima de Ioánina. Preveza es el punto clave de la bahía que daría su nombre, noventa años después, a la célebre victoria de Barbaros.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Fallecimiento de Murad II y segundo acceso al trono de Mehmed II", "8f8256ad"], "d": ["Murad II, que cayó enfermo tras la boda de su hijo, falleció en Adrianópolis el 1 de Muharram de 855 (3 de febrero de 1451). Mehmed II, de diecinueve años, subió por segunda vez al trono otomano el 16 de Muharram de 855 (18 de febrero de 1451), esta vez de forma definitiva. El regreso del joven soberano, destronado cinco años antes en Buçuktepe, es el comienzo de un sultanato que dos años después se coronaría con la conquista de Constantinopla y transformaría el beylicato otomano en un imperio mundial.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Primer asedio de Caffa por las fuerzas conjuntas otomano-tártaras de Crimea", "e346d163"], "d": ["Hacı Giray, kan de Crimea, que en junio de 1454 se había puesto de acuerdo con Mehmed el Conquistador, asedió Caffa por tierra con 7000 jinetes; una flota otomana de cincuenta o sesenta galeras se apostó además mar adentro. La Caffa genovesa hizo levantar el asedio pagando tributo, y la conquista definitiva quedó para veintiún años después, 1475. Esta primera operación conjunta fue el primer ejemplo de la cooperación militar otomano-tártara de Crimea, que se repetiría más adelante en la conquista definitiva de Caffa.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Toma de las islas del Egeo septentrional: Bozcaada, Imbros y Thasos", "76575895"], "d": ["Inmediatamente después de la conquista de Constantinopla, Mehmed el Conquistador se dirigió a las islas de la boca egea de los Dardanelos para asegurar la ruta marítima de la nueva capital; Bozcaada e Imbros fueron tomadas a Bizancio, y Thasos a la familia Gattilusio, de origen genovés. Estas islas, que cerraban ambas orillas del estrecho, fueron desde entonces el primer eslabón de la línea de abastecimiento y defensa de Estambul. El dominio osciló durante un tiempo por la intervención de las flotas papal y veneciana, y sólo se consolidó en 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Conquista de Kosovo: toma de Pristina y Yenipazar", "d7ed2345"], "d": ["El ejército otomano que marchó contra el despotado serbio se apoderó de Pristina, en la llanura de Kosovo, y de Yenipazar (Novi Pazar), centro de la región de Raška; en la misma campaña se tomó también Novo Brdo, célebre por sus minas de plata. Así la mitad meridional de Serbia quedó vinculada a la administración otomana directa y el despotado de Semendire (Smederevo) fue separado de sus territorios centrales. Esta conquista fue el paso decisivo en el camino hacia la anexión total de Serbia cuatro años después.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["İpek (Peć) pasó a la administración otomana — uno de los centros del sanjacado de Dukakin", "19511588"], "d": ["Poco después de la campaña de Serbia de Mehmed el Conquistador en 1455, İpek, sede del patriarcado serbio, pasó a la administración otomana; en las fuentes otomanas no hay registro de este paso. Con el tiempo la localidad se convirtió en una pequeña población musulmana y fue una de las residencias del sanjak beyi en el sanjacado de Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Conquista de Enez y Samotracia — completada la costa de Tracia occidental", "106e723b"], "d": ["Enez, en la desembocadura del río Maritsa, fue tomada a la familia Gattilusio, de origen genovés, que la poseía desde hacía ochenta años; la isla de Samotracia, dependiente de ella, se capturó en la misma campaña. Con la caída de Enez la franja costera de Tracia occidental, de Salónica a Galípoli, pasó a ser territorio otomano ininterrumpido. En manos de los Gattilusio sólo quedó Lesbos, que sería tomada seis años después.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Fracaso del asedio de Belgrado", "3d53a604"], "d": ["Mehmed el Conquistador, tras la conquista de Constantinopla, sitió Belgrado, considerada la llave de Europa central; pero los refuerzos que Juan Hunyadi trajo por el Danubio y los voluntarios reunidos por el predicador cruzado Capistrano impidieron la caída de la fortaleza. El sultán, pese a la valentía personal mostrada ante el asedio, tuvo que retirarse herido. Este fracaso cerraría durante sesenta y cinco años la frontera húngara al avance otomano; Belgrado sólo pudo ser tomada en 1521 por el Legislador.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Conquista de la Morea septentrional: Balyabadra (Patras)", "c08a8509"], "d": ["Las fuerzas de Mehmed el Conquistador, que en los mismos años de la anexión de Serbia se dirigieron al despotado de la Morea, se apoderaron de Balyabadra, en el noroeste de la península. Este puerto, que guarda la boca del golfo de Corinto, es la llave de la entrada por tierra a la Morea; su toma preparó el terreno de la conquista definitiva dos años después. La ciudad era el último gran embarcadero por el que los déspotas bizantinos se comunicaban con el mundo latino.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Toma de Amasra, en la costa del mar Negro occidental", "f43608fc"], "d": ["Amasra, colonia fortificada de Génova en el mar Negro occidental, se rindió sin resistencia ante la presión conjunta de la flota y las fuerzas terrestres de Mehmed el Conquistador. Este puerto de la costa de Bartın-Zonguldak se mantenía como un enclave latino entre los Candaroğlu y las tierras otomanas; con su toma la costa quedó integrada. La caída de Amasra es el primer paso de la gran campaña del mar Negro que dos años después (1461) se dirigiría contra Sinope y Trebisonda.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Conquista de la isla de Lesbos", "fe17aeba"], "d": ["El ejército otomano al mando de Mehmed el Conquistador tomó Lesbos en Dhu l-Hiŷŷa de 866, tras un asedio breve pero violento, a la familia Gattilusio, de origen genovés, y la anexionó. La caída de la mayor isla del Egeo septentrional liquidó también la última base importante de los genoveses en la región. Por su proximidad a la costa de Anatolia, la isla serviría desde entonces de puesto avanzado de la flota otomana y pasaría a la historia marítima también como lugar de formación de los hermanos Barbaros.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Comienzo de la guerra otomano-veneciana de dieciséis años", "563ddb68"], "d": ["Los venecianos iniciaron la guerra en 1463, aliándose con los gobernantes de Karaman y de los Ak Koyunlu, para detener el avance otomano en la Morea y en el Egeo. Esta estrategia de cerco, formada por Uzun Hasan en el este, Venecia en el oeste y Karaman en medio, obligó al Conquistador a combatir en varios frentes a la vez. La lucha, que duró dieciséis años, abarcó todas las grandes operaciones de la época, de Otlukbeli a las campañas de Albania, y sólo terminaría con el Tratado de Estambul de 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Conquista de la mayor parte de Herzegovina: Trebinje y Mostar", "f54c0100"], "d": ["Los territorios del duque de Herzegovina, Stjepan Vukčić-Kosača, que había establecido una administración separada de Bosnia, pasaron en gran parte a la administración otomana tres años después de la caída del Reino de Bosnia: en el sur, Trebinje fue tomada en 1466 «junto con casi toda la región de Herzegovina». Mostar, formada en torno a las dos pequeñas fortalezas del puente sobre el Neretva, debió de ser tomada poco antes de la conquista de Blagaj, centro de Herzegovina, en 1466-1468; en el registro sumario (icmal) de Bosnia de 1468-1469 figura con el nombre de «Köprülü Hisar». La conquista de Herzegovina, con las fortalezas restantes del ducado, se completó en 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Segunda campaña de Albania — marcha personal del Conquistador contra Skanderbeg", "9cdd2bfa"], "d": ["Para quebrar la resistencia de Skanderbeg, que superaba el cuarto de siglo, Mehmed el Conquistador organizó en 1466-1467 grandes campañas que él mismo dirigió. El ejército otomano asedió Akçahisar (Kruja) y construyó la fortaleza de İlbasan (Elbasan) para controlar la región. La campaña quebró la espina dorsal de la resistencia albanesa, pero no consiguió hacer caer la fortaleza; la sumisión completa de la región tendría que esperar diez años tras la muerte de Skanderbeg.", "00e75aca"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Hundimiento del Estado Kara Koyunlu: muerte de Jahan Shah", "30bc6358"], "d": ["Jahan Shah, soberano de los Kara Koyunlu, que al regresar de una campaña contra Uzun Hasan fue atacado por sorpresa a causa de la llegada del invierno, murió mientras huía entre Bingöl y Kiğı. Tras este golpe el Estado no pudo recomponerse; el último soberano, Hasan Ali, fue capturado y muerto en 1469 por Uğurlu Mehmed, hijo de Uzun Hasan. El dominio Kara Koyunlu, que durante casi un siglo había reinado en Anatolia oriental, Azerbaiyán e Irak, pasó así a los Ak Koyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Muerte de Skanderbeg — extinción de la resistencia albanesa", "9158c35f"], "d": ["Skanderbeg, que se había formado en el palacio otomano y se sublevó en 1444 tras el desastre de İzlâdi, y que resistió en Albania durante más de un cuarto de siglo, murió en Lezhë, donde se había refugiado. Esta resistencia, que entretuvo repetidamente a los ejércitos otomanos en tiempos de Murad II y del Conquistador, perdió con su muerte su dirección central. Con el derrumbe del frente albanés, alimentado por el papado y Venecia, los otomanos tomaron en diez años Akçahisar e Iskodra (Shkodër) y anexionaron definitivamente la región.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Se estableció la administración otomana en Kayseri: Gedik Ahmed Pachá puso fin a los Karamánidas", "33cf35fc"], "d": ["Con el fin de los Karamánidas por obra de Gedik Ahmed Pachá en 1474, Kayseri pasó a la administración otomana; durante el siglo XV la ciudad había cambiado de manos entre los Dulkadiridas, los Ramazánidas y los Karamánidas. Bajo la administración otomana, Kayseri se convirtió en capital de sanjacado del beylerbeylicato de Karaman.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samos fue abandonada: terminó la propiedad genovesa (Maona)", "5bdc380c"], "d": ["Según el TDV, la isla fue abandonada después de 1475; en 1479 Mehmed II el Conquistador conquistó la isla y mandó construir una fortaleza.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Desastre de Racova (Vaslui) en Moldavia", "a1a74bf7"], "d": ["Esteban el Grande, voivoda de Moldavia, atrajo a terreno pantanoso a las fuerzas otomanas al mando del beylerbeyi de Rumelia, Hadım Süleyman Paşa, y les infligió una grave derrota. Este desastre, una de las mayores derrotas terrestres de la época del Conquistador, tuvo gran eco en Europa y dio a Esteban fama en el mundo cruzado. El sultán saldría en persona a campaña al año siguiente como represalia.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Victoria de Akdere (Valea Albă) — campaña de Moldavia", "45a66791"], "d": ["Mehmed el Conquistador, que salió en persona a campaña para vengar el desastre de Racova del año anterior, infligió una gran derrota a las fuerzas moldavas en el paraje de Akdere con el ejército otomano y entró en Suceava, centro del principado. Pero no se lograron tomar las fortalezas; por la escasez de provisiones, la peste desatada entre los jenízaros y los preparativos húngaros, el ejército tuvo que retirarse. La sumisión definitiva de Moldavia sólo se alcanzaría en los años siguientes y con la toma de Kili y Akkerman en 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Conquista de Akçahisar (Kruja) y consumación de la conquista de Albania", "559a79b4"], "d": ["Diez años después de la muerte de Skanderbeg, con la toma en 1478 de Akçahisar, Drivasto, Lezhë y Jabyak, la conquista de Albania quedó en gran parte completada. La caída de la fortaleza de Kruja, que durante años resistió a los ejércitos otomanos y era símbolo de la resistencia de Skanderbeg, significaba el fin de la alianza veneciano-albanesa en la región. En cuanto a Iskodra, que quedaba, sería cedida a los otomanos por el Tratado de Estambul firmado al año siguiente.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Incorporación de la península de Tamán", "4ef917b8"], "d": ["Tras la toma de Caffa y Kerch en 1475, la flota que Mehmed el Conquistador envió a las costas caucásicas se apoderó, junto con Anapa y Kopa, de la Matrega genovesa (Tamatarkha) en la península de Tamán. Así quedaron bajo control ambas orillas del estrecho y la entrada al mar de Azov pasó a estar plenamente controlada. Tamán se vinculó al sanjacado de Caffa como puerta abierta al Cáucaso septentrional.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Entrada de Samos en la administración otomana (Mehmed el Conquistador)", "c877bc14"], "d": ["Mehmed II el Conquistador conquistó Samos, mandó construir una fortaleza y reorganizó el censo; la fortaleza fue demolida en 1483 por Bayezid II por razones políticas.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Fracaso del asedio de Rodas", "35a85c28"], "d": ["Por orden de Mehmed el Conquistador, una flota de 160 unidades al mando de Mesih Paşa sitió Rodas en la primavera de 885 (1480), y la isla permaneció bloqueada durante tres meses. Los caballeros de San Juan, bajo el gran maestre Pierre d'Aubusson, resistieron con fiereza pese a las graves pérdidas; tras rechazar también el último gran asalto, dado el 20 de Ŷumādà l-Ūlà de 885, la flota se retiró el 3 de agosto. Tras este fracaso las murallas de la ciudad fueron renovadas desde los cimientos y convertidas en la fortificación más fuerte de Europa, y la isla sólo pudo ser tomada en 1522 por el Legislador.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Nicaria (Icaria) pasó a la administración de los Caballeros de San Juan de Rodas", "5cbc2669"], "d": ["Nicaria, entre Samos y Quíos, estuvo de 1481 a 1521 bajo la administración de los Caballeros de San Juan de Rodas.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Batalla de Yenişehir — derrota del sultán Cem", "c35abee2"], "d": ["Los dos hermanos que se movilizaron por el trono tras la muerte del Conquistador se enfrentaron en la llanura de Yenişehir, y el sultán Cem sufrió una derrota decisiva. El príncipe, que había reinado dieciocho días en Bursa y había hecho leer la jutba en su nombre, tuvo que refugiarse, tras la derrota, primero en Konya y luego en tierras mamelucas. Yenişehir inició la crisis dinástica más larga de la historia otomana: el asunto de Cem paralizaría durante catorce años la política exterior otomana frente a Europa.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Anexión de Herzegovina", "bf247891"], "d": ["Las tierras del Ducado de Herzegovina, que subsistió tras la conquista de Bosnia en 1463, pasaron por etapas a la administración otomana: Trebinje y Mostar fueron tomadas en 1466, el sanjacado de Herzegovina se organizó en 1470, y los últimos territorios del ducado en la costa del Adriático, junto con Herceg Novi, fueron conquistados a comienzos de 1482 y agregados al sanjacado. Así la región montañosa que se extiende tras el Adriático pasó por completo a los otomanos, y Bosnia y Herzegovina se convirtieron en una única geografía administrativa. El hijo del último duque, que entró en el palacio otomano, es Hersekzâde Ahmed Paşa, que más adelante llegaría a gran visir.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Zante (Zaklise/Zakynthos) es dejada a Venecia a cambio de un tributo anual", "268a691a"], "d": ["Al final de la época de Fatih, Zante, una de las islas Jónicas tomadas a la familia Tocco, fue dejada a Venecia por el nuevo sultán, que, ocupado con la cuestión de Cem Sultan, buscaba tranquilidad en Occidente. La isla fue cedida a una administración veneciana que reconocía la soberanía del sultán otomano y pagaba un tributo anual de quinientos ducados. Así, el dominio otomano directo en el mar Jónico quedó limitado a Santa Maura.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Refugio del sultán Cem en Rodas", "2228d6da"], "d": ["El sultán Cem, cuyo intento de asediar Konya también resultó infructuoso, huyó de Anatolia con unos treinta hombres hasta llegar a Rodas y fue recibido con ceremonia por los caballeros de San Juan. Pero la hospitalidad se convirtió pronto en cautiverio; el príncipe fue entregado primero a Francia y luego al papado, y pasó a ser una baza en manos de la política europea. Bayezid II tuvo que hacer pagos anuales a cambio de la custodia de su hermano, y las iniciativas militares otomanas contra Occidente quedaron suspendidas hasta la muerte de Cem.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Comienzo de la guerra otomano-mameluca (frente de la Çukurova)", "3fe3f0c7"], "d": ["La lucha por la influencia sobre los Dulkadiroğlu y la enemistad que dejó el refugio del sultán Cem en tierras mamelucas iniciaron en 1485 una guerra de seis años entre las dos grandes potencias suníes. En los combates librados en la Çukurova, en torno a Adana y Tarso, las partes no lograron imponerse una a otra; los ejércitos otomanos recibieron varios golpes graves. Esta guerra es la primera fase de la ruptura de las relaciones otomano-mamelucas y la apertura del proceso que treinta años después concluirían las campañas de Marŷ Dābiq y Ridaniya de Selim el Severo.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Paz otomano-mameluca — mediación de Túnez", "60dd6719"], "d": ["En la guerra otomano-mameluca iniciada en 1485, las partes no consiguieron una victoria decisiva; por la mediación del soberano de Túnez, Osman Hafsí, se llegó a un acuerdo en 1491. El tratado devolvió las fronteras en gran parte a su estado anterior a la guerra, y el ajuste de cuentas entre los dos Estados islámicos quedó aplazado durante una generación. La lucha desgastante de seis años es una de las principales causas de la política exterior prudente de Bayezid II y de que diera prioridad a los arreglos internos en lugar de volverse hacia el este.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Acogida por los otomanos de los judíos sefardíes expulsados de España", "5c2b5c24"], "d": ["Tras la caída de Granada, parte de los judíos que huían de la persecución de la Inquisición en España se refugiaron en tierras otomanas y fueron asentados en diversas ciudades. Bajo la administración otomana, estas comunidades sefardíes alcanzaron una libertad que hasta entonces no habían conocido: instalarse donde quisieran, vivir su fe, abrir instituciones de enseñanza y construir nuevas sinagogas. Esta inmigración, que con los conocimientos de imprenta, medicina y finanzas que trajo consigo transformó la vida económica de Salónica y Estambul, fue el ejemplo del orden de tolerancia otomano más comentado en Europa.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Muerte del sultán Cem — fin de un rehén de catorce años", "f6588b70"], "d": ["El sultán Cem, entregado por el papado al rey de Francia Carlos VIII, murió en el lugar llamado Castel Capuana después de salir de Roma el 27 de enero de 1495; las fuentes registran que pudo haber sido envenenado por círculos papales. La muerte del príncipe, mantenido durante catorce años por los Estados europeos como carta de amenaza contra los otomanos, dejó por fin libres las manos de Bayezid II. En efecto, el sultán declararía desde entonces la guerra a Venecia y llevaría su flota a la primera gran victoria.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Victoria naval de Sapienza (Zonchio) — primer gran éxito de la flota en el Mediterráneo", "9754aaef"], "d": ["Bayezid II, que con el fin del asunto de Cem se encontró con las manos libres, declaró la guerra a Venecia en 1499; la flota otomana derrotó a la flota veneciana frente a Sapienza (Zonchio) y obtuvo la primera gran victoria naval en el Mediterráneo. Con esta victoria la flota proclamó que ya podía hacer frente a Venecia en el mar.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Pérdida de Cefalonia e Ítaca", "60f0f687"], "d": ["Venecia, sacudida por la toma de Modon y Coron, se unió a España, pasó al contraataque y sitió Cefalonia, que estaba en manos otomanas desde 1479. Tras una resistencia de cuarenta y siete días, la fortaleza cayó, la isla pasó con Ítaca a Venecia y durante trescientos años no volvió a la administración otomana. Esta pérdida creó un equilibrio en el que lo ganado en la Morea se devolvía en el Jónico.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Caída del Kanato de la Horda de Oro y auge de Crimea", "0d1dc515"], "d": ["Şeyh Ahmed Han (1481-1502), su último soberano, no pudo salvar a su país de la crisis en que había caído, y el Kanato de la Horda de Oro desapareció de la historia en 1502 por el golpe del kan de Crimea Mengli Giray. Como resultado de las luchas por el trono y de la fragmentación, en las antiguas tierras de la Horda de Oro surgieron los kanatos de Crimea, Kazán, Nogay, Astracán y Siberia. Esta victoria de Crimea, bajo protección otomana, hizo indiscutible la influencia otomana al norte del mar Negro, mientras que el vacío surgido en la región sería llenado en el siglo siguiente por Moscú.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Fin de la guerra otomano-veneciana y paz", "125b1526"], "d": ["La guerra iniciada en 1499, que sacudió a Venecia con las pérdidas de Sapienza, Lepanto, Modon y Coron, terminó con la paz en 1502. Venecia, tras perder sus bases más importantes en la Morea, tuvo que reconocer la superioridad otomana a cambio de conservar sus privilegios comerciales en el Mediterráneo oriental. Con esta guerra, el sultanato de Bayezid II, considerado prudente, había elevado por primera vez a los otomanos a la condición de una potencia naval de peso en el Mediterráneo.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Rebelión de Şahkulu — sublevación kızılbaş desde la región de Teke hasta Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, que por la influencia de la propaganda safávida en Anatolia manifestó abiertamente su rebelión en 1510, había asaltado el bazar de Antalya en marzo de 1511 y en abril había derrotado a las fuerzas otomanas en Kütahya y alrededores. En el último combate librado cerca de Sivas con el gran visir Hadım Ali Paşa, ambos bandos sufrieron graves pérdidas; murieron tanto el gran visir como el jefe de la rebelión. Esta sublevación, que sacudió la autoridad del Estado en Anatolia, puso de manifiesto el vacío de poder de los últimos años de Bayezid II y fue la razón más sólida de la marcha del príncipe Selim hacia el trono.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Abdicación de Bayezid II y acceso al trono de Selim el Severo", "c4cfab69"], "d": ["Bajo la presión del príncipe Selim, que en la lucha por el trono con sus hermanos tenía el apoyo de los jenízaros, Bayezid II abdicó el 24 de abril de 1512 y Selim I subió ese mismo día al trono como noveno soberano otomano. El anciano sultán murió en el camino, cuando se dirigía a Dimetoka, donde había nacido, en la aldea de Abalar, cerca de Çorlu, el 25 de Rabī' al-Awwal de 918 (10 de junio de 1512). A un sultanato prudente y replegado sobre sí mismo de treinta y un años lo sucedió la época de Yavuz, que en ocho años duplicaría las fronteras del imperio.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Conquista de la fortaleza de Sin (Sinj)", "83271ea5"], "d": ["Las fuerzas de akıncı otomanas de la frontera de Bosnia tomaron al reino de Hungría la fortaleza de Sin (Sinj), que se adentra en el interior de Dalmacia. Fue un eslabón temprano de la línea fronteriza de Dalmacia, que nueve años después se ampliaría con la conquista de Knin y sus alrededores por Gazi Hüsrev Bey; la fortaleza se perdería a favor de Venecia en 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Batalla de Yenişehir y eliminación del príncipe Ahmed", "e2ed15dd"], "d": ["Selim el Severo derrotó en la llanura de Yenişehir, cerca de Bursa, a su hermano mayor el príncipe Ahmed, el rival más fuerte por el trono, y lo eliminó tras capturarlo. Así se cerró la disputa entre hermanos que duraba desde 1511 y terminó la división interna de Anatolia. Selim, asegurada su retaguardia, ganó libertad para volverse hacia la cuestión safávida.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Entrada de Selim el Severo en Tabriz", "dad2e227"], "d": ["Tras la victoria de Çaldıran, el ejército otomano entró en Tabriz, capital safávida, y en la ciudad se leyó la jutba en nombre del sultán. Selim permaneció allí una semana e hizo trasladar a Estambul a una parte de los artistas y ulemas de Tabriz; este traslado influiría profundamente en el arte palatino otomano. Aunque la ciudad fue abandonada por la proximidad del invierno y el descontento de los jenízaros, la superioridad safávida en Oriente había sido quebrada. En el mapa, los lugares que ese día pasan a los otomanos no son contiguos, y es correcto: Tabriz es una ocupación militar de nueve días; la llanura de Erzincan se rindió sin lucha durante la campaña, y la fortaleza de Kemah, en su centro, resistió en manos safávidas hasta el 19 de mayo de 1515; Siirt la recuperó de los safávidas Halil Bey, melik de Hasankeyf, liberado de la prisión del sah Ismail en Tabriz, al someterse a los otomanos; Diyarbakır, a su alrededor, siguió siendo safávida hasta 1515 y Hasankeyf hasta 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muş y Bingöl (Çapakçur) pasaron de los safávidas a la administración otomana", "b0a53b5a"], "d": ["Con la toma de Anatolia oriental a los safávidas tras Çaldıran, Muş entró en la administración otomana en 921/1515; la vecina Çapakçur (Bingöl) se unió a los otomanos en el mismo proceso.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Conquista a los safávidas de la fortaleza de Kemah", "73fd8671"], "d": ["Selim el Severo, que pasó el invierno en Amasya a la vuelta de Çaldıran, encargó a Bıyıklı Mehmed Paşa la conquista de la fortificada Kemah, que guarda el paso del Éufrates. Tras un asedio en el que participó personalmente el sultán, la fortaleza fue tomada a los safávidas y se abrió la puerta de Anatolia oriental. Esta conquista es el primer paso concreto que convirtió la victoria de Çaldıran en una ganancia territorial duradera.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Victoria de Turnadağ — el beylicato de Dulkadir pasó a ser vasallo de los otomanos", "fd879145"], "d": ["Las fuerzas otomanas derrotaron en el paraje de Ördekli, entre Göksun y Andırın, a Alâüddevle Bozkurt, bey de Dulkadir, que durante la campaña de Çaldıran había adoptado una actitud ambigua; Alâüddevle murió en esta batalla. El beylicato no fue anexionado en esa fecha: tras Alâüddevle, Selim el Severo puso al frente del beylicato de los Dulkadıroğlu a Şehsuvaroğlu Ali Bey, y el país, con centro en Maraş-Elbistan, continuó como beylicato vasallo de los otomanos. El tapón en la frontera mameluca quedó así bajo control otomano y se abrió el camino de la campaña de Egipto dos años después; la anexión se produciría tras la muerte de Ali Bey.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Conquista de Âmid (Diyarbakır) y fundación del beylerbeyilik de Diyarbakır", "a6867d5b"], "d": ["Tras la labor de İdrîs-i Bitlisî de ganar para los otomanos a los señores kurdos suníes de la región, las fuerzas safávidas no resistieron un largo asedio y las llaves de Âmid fueron entregadas a Bıyıklı Mehmed Paşa. La ciudad fue hecha centro del recién fundado beylerbeyilik de Diyarbakır. Así el núcleo administrativo de la Alta Mesopotamia pasó a manos otomanas.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Conquista de Harput — apertura del camino de Diyarbakır", "564eb269"], "d": ["Hüsrev Paşa, beylerbeyi de Karaman, que salió para liberar del asedio safávida a Diyarbakır, tomada tras Çaldıran, conquistó la fortaleza de Harput, cuyos alrededores había capturado antes Çerkez Hüseyin Bey, tras un asedio de tres días. Así quedó asegurado el camino que, al este del Éufrates, se extiende hasta Diyarbakır.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Batalla de Koçhisar (Kızıltepe) — derrota de Kara Han", "9ea9e843"], "d": ["El ejército otomano al mando de Bıyıklı Mehmed Paşa venció, en una batalla campal que duró todo el día, al gobernador safávida Kara Han en el paraje de Koruk, en la llanura de Dede Garkın, cerca de Koçhisar; la cabeza cortada de Kara Han fue enviada al campamento del sultán. A continuación las fuerzas otomanas entraron en la ciudad de Mardin, pero tras unos días se marcharon; la fortaleza de Mardin, en manos de la guarnición safávida, sólo pudo ser recibida un año después. Esta victoria, asegurando la frontera sur de Selim, hizo posible que se volviera hacia la campaña de Egipto. Otros lugares incorporados en la misma fecha: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Salida de Selim el Severo de Estambul para la campaña de Egipto", "ac258b4b"], "d": ["Selim el Severo partió de Estambul con el aparente propósito de preparar una nueva campaña oriental contra los safávidas y se dirigió al sur por Akşehir. Que el sultán mameluco Qansuh al-Ghawri entrara en contacto con el sah Ismail y amenazara el flanco oriental de los otomanos haría cambiar en poco tiempo el objetivo. La campaña es el comienzo de la gran operación que duraría dos años y transformaría a los otomanos en un imperio de Oriente Próximo.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Toma de Zabid: primera entrada de los marinos otomanos en el Mar Rojo", "38740e0c"], "d": ["Ante la presión de Portugal en el océano Índico, los marinos de origen otomano Hüseyin Bey y Selman Reis, enviados al Mar Rojo a petición del sultán mameluco Qansuh al-Ghawri, tomaron Zabid con su flota. Esta operación, aún realizada al servicio mameluco, constituye la primera presencia efectiva de la marina otomana en la ruta del Mar Rojo y el Índico. Un año después, cuando Egipto pasó a los otomanos, la misma flota quedó vinculada directamente a Estambul.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Declaración oficial del sultán mameluco y de Alepo como objetivo de la campaña", "689e310d"], "d": ["Selim el Severo declaró abiertamente como objetivo de la campaña al sultán mameluco y a Alepo, cuando Qansuh al-Ghawri se entendió con los safávidas y marchó con su ejército sobre Alepo. Así la rivalidad encubierta que desde hacía años existía entre los dos Estados suníes se convirtió en guerra abierta. Esta declaración puso en marcha la cuenta atrás de cuatro semanas que conducía a Marŷ Dābiq.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Fracaso del asedio de Adén: primer intento en el mar Rojo contra Portugal", "8ffd46f2"], "d": ["Selman Reis y Hüseyin Bey llevaron a cabo un asedio de ocho días para tomar Adén, puerta del mar Rojo hacia el océano Índico, pero tuvieron que retirarse ante la fuerte fortificación de la ciudad. El no haber tomado Adén retrasaría durante muchos años la estrategia meridional que se llevaría a cabo contra Portugal. Este intento es la primera prueba de la política oceánica otomana.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Incorporación del beylicato de los Ramazanoğlu a los otomanos", "cfaa3754"], "d": ["En las asignaciones hechas tras la victoria de Marŷ Dābiq, el beylicato de los Ramazanoğlu, con centro en Adana, fue entregado a Mahmud Bey y puesto bajo soberanía otomana. El beylicato, que salió de la sujeción mameluca, no fue suprimido sino dejado a la familia con el estatuto de «ocaklık»; los Ramazanoğlu continuaron administrando la Çukurova como sanjak beyi otomanos. Este régimen privilegiado duró hasta 1608, año en que Pîr Mansûr abandonó el beylicato. Otros lugares incorporados en la misma fecha: Malatya, Tarso, Mosul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Alepo, Raqqa y Deir ez-Zor pasan al dominio otomano", "2088eb6a"], "d": ["Cuatro días después de Marŷ Dābiq, Selim el Severo entró en Alepo sin encontrar resistencia y en las mezquitas de la ciudad se leyó la jutba en su nombre. La rápida caída de Alepo, considerada capital comercial y administrativa de Siria, muestra que la autoridad mameluca en la región se había derrumbado. La toma de la ciudad abrió de golpe el camino hacia Damasco y, desde allí, hacia Egipto. Otros lugares incorporados en la misma fecha: Antioquía, Raqqa, Deir ez-Zor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Entrevista en Gökmeydan, Alepo, con el califa abasí al-Mutawakkil III", "22979f42"], "d": ["El califa abasí de El Cairo al-Mutawakkil III, que cayó prisionero en Marŷ Dābiq junto con el ejército mameluco, fue llevado en Alepo, en Gökmeydan, ante el sultán, y Selim el Severo le mostró gran respeto. Con esta entrevista el califato de El Cairo, un cargo simbólico a la sombra de los sultanes mamelucos desde 1261, pasó de hecho a la protección otomana. El califa sería llevado más tarde a Estambul junto con el sultán.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Trípoli de Siria y Hama pasan a la administración otomana", "a1e19a79"], "d": ["Tras Alepo y Hama, también Trípoli de Siria, en la costa siria, pasó sin resistencia a la administración otomana. La ciudad, uno de los puertos más activos del Mediterráneo oriental, era la puerta de Damasco hacia el mar y centro del comercio de seda y azúcar. Con su toma la franja costera de Bilad al-Sham cambió por completo de manos.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Damasco pasa al dominio otomano", "2b844d91"], "d": ["Selim el Severo, a quien se había abierto el camino con la rendición de Hama y Homs tras Alepo, llegó ante Damasco el 27 de septiembre; no entró de inmediato en la ciudad, sino que plantó su tienda fuera, en el paraje de Mastaba, y entró con una gran ceremonia el duodécimo día de su llegada. Permaneció largo tiempo en Damasco, estableció el orden administrativo de Siria e hizo construir la tumba de Muhyiddin Ibn al-Arabi. Así toda Bilad al-Sham salió de la administración mameluca. Otros lugares incorporados en la misma fecha: Beirut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Proclamación de Tomanbay como sultán mameluco en El Cairo", "6020d90d"], "d": ["Tras la muerte de Qansuh al-Ghawri en Marŷ Dābiq, los emires mamelucos pusieron en el trono a Tomanbay, que sería el último sultán del Estado. El nuevo sultán, de origen circasiano, heredó un Estado que había perdido Siria, con el tesoro agotado y sin armas de fuego. Aun así organizaría una última resistencia contra el avance otomano estableciendo una línea de defensa ante El Cairo.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Combate de Gaza (Han Yûnus): derrota de Canbirdi al-Gazali", "9f1eb8cb"], "d": ["Selim el Severo envió a Gaza al gran visir Hadım Sinan Paşa con una vanguardia de cuatro mil hombres. Canbirdi al-Gazali, nombrado por Tomanbay gobernador (nâib) de Damasco, intentó detener a la vanguardia otomana en la línea Gaza-Han Yûnus, pero sufrió una grave derrota y huyó a Egipto. Con la dispersión de la última fuerza tapón mameluca en Palestina, el camino hacia el desierto del Sinaí quedó totalmente abierto.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Al este del Jordán: Ammán pasa a la administración otomana", "9db62667"], "d": ["Mientras las fuerzas otomanas, que se preparaban para la campaña de Egipto tras el combate de Gaza, descendían hacia el sur, también Ammán, al este del Jordán, pasó a la administración otomana. Las ciudades costeras e interiores de Palestina (Jaffa, Nablus, Sidón, Acre, Jerusalén) ya habían cambiado de manos en el otoño de 1516, después de Marŷ Dābiq. Estas ciudades fueron administradas durante cuatro siglos como sanjacados de la provincia de Damasco.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Llegada de Selim el Severo a Jerusalén", "66d7bfad"], "d": ["A Jerusalén, que tras Marŷ Dābiq había pasado sin resistencia a la administración otomana, llegó Selim el Severo tras el combate de Gaza con los notables del Estado y el ejército. El sultán visitó la Cúpula de la Roca y la mezquita de al-Aqsa y confirmó el estatuto sagrado de la ciudad. Jerusalén permanecería bajo administración otomana desde esta fecha hasta diciembre de 1917, cuatro siglos completos.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Entrada de Selim el Severo en Gaza y marcha hacia el desierto del Sinaí", "2106bfc7"], "d": ["Tras la derrota de Canbirdi al-Gazali en Han Yûnus (21 de diciembre de 1516), Gaza quedó en manos de la vanguardia. El sultán entró en Gaza el 2 de enero de 1517, se encontró allí con Sinan Paşa, que estaba al frente de la vanguardia, y el ejército hizo los últimos preparativos para el paso a Egipto. En el árido desierto de Katya (Sinaí), que se extiende desde Gaza hasta Sâlihiye, se marcharía ocho jornadas, transportando agua en camellos. Este paso es la fase más arriesgada y logísticamente más difícil de la campaña.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Toma de Suez — puerta abierta al mar Rojo", "05f3324e"], "d": ["Con la entrada de las tropas otomanas en El Cairo tras la victoria de Ridaniya, también Suez, en el extremo septentrional del mar Rojo, pasó a la administración otomana. Este puerto-astillero, desde el que los mamelucos enviaban flotas al océano Índico, se convirtió en la base de la política meridional que se llevaría a cabo contra Portugal. Suez es la boca norte de la línea por la que tres siglos después se abriría el canal.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Primera entrada de las tropas otomanas en El Cairo", "0a3f4f4d"], "d": ["Al día siguiente de la victoria de Ridaniya se permitió la entrada de los ejércitos otomanos en El Cairo, y el 24 de enero las tropas se instalaron en la ciudad. Pero esta entrada no significaba el control total de la ciudad; Tomanbay se había retirado al Alto Egipto y la resistencia mameluca aún no estaba quebrada. La conquista de El Cairo no se completaría en un solo día, sino en un proceso sangriento repartido en semanas.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Ataque de Tomanbay a El Cairo y tres días de combates callejeros", "b83b6ce6"], "d": ["Tomanbay, que se había retirado al Alto Egipto, entró de improviso en El Cairo en la noche del 27 al 28 de enero con unos siete mil hombres e inició la resistencia en el interior de la ciudad, dejando a las tropas otomanas en una situación extremadamente difícil. En los violentos combates callejeros que duraron tres días, los mamelucos mantuvieron temporalmente en su poder gran parte de la ciudad. La resistencia sólo pudo quebrarse con la entrada en acción de la artillería otomana y de las fuerzas de refuerzo.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Canbirdi al-Gazali entra al servicio otomano", "a94ea459"], "d": ["El antiguo emir mameluco Canbirdi al-Gazali, que tras Ridaniya se retiró a Sâlihiye, pidió clemencia (aman) al sultán. Selim el Severo, pensando que le sería útil para establecer el orden en Egipto y Siria, lo aceptó a su servicio. Esta decisión es el primer gran ejemplo de la política otomana de incorporar al sistema los cuadros mamelucos en lugar de liquidarlos.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Entrada solemne de Selim el Severo en El Cairo y lectura de la jutba", "6d98080c"], "d": ["Tras la sofocación de los combates callejeros, el sultán entró en El Cairo el 15 de febrero de 1517 con una ceremonia muy brillante, y en las mezquitas se leyó la jutba en su nombre. La lectura de la jutba en El Cairo en nombre del sultán otomano es la proclamación de que el dominio mameluco, vigente desde 1250, había terminado jurídicamente. Esta fecha se considera el momento simbólico de culminación de la conquista de hecho de Egipto.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Captura de Tomanbay, último sultán mameluco, en Terrûce", "7058e6ad"], "d": ["Tomanbay, que tras abandonar El Cairo se ocultaba en el delta del Nilo, fue denunciado por los beduinos que le habían dado refugio y capturado en la región de Terrûce. Su captura eliminó el centro organizado de la resistencia mameluca. El último sultán permanecería desde entonces catorce días en manos otomanas.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Ejecución de Tomanbay en Bab Zuwayla y fin del Estado mameluco", "ad9820be"], "d": ["Catorce días después de su captura, Tomanbay fue ahorcado en Bab Zuwayla, la célebre puerta de El Cairo; su cuerpo fue sepultado después en la madrasa que había hecho construir su tío. Así el Estado mameluco, que desde 1250 gobernaba Egipto y Siria, desapareció oficialmente de la historia. Con la quiebra de la resistencia, ciudades del Alto Egipto (Saíd) como Asiut y Asuán se vincularon también a la administración otomana.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Ataque de la flota portuguesa a Yeda y defensa de Selman Reis", "52322cf5"], "d": ["Una flota portuguesa de unas treinta galeras y galeones atacó Yeda; Selman Reis dirigió la defensa de la ciudad, impidió el desembarco del enemigo y hundió varias naves portuguesas. Esta defensa evitó que el puerto de La Meca, y con él el camino de la peregrinación, cayera en manos de un Estado cristiano. Yeda se incorporaría oficialmente a la administración otomana unos meses después, con la bay'a del Hiyaz.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Rendición de Alejandría a la flota — culminación de la conquista de Egipto", "386878fe"], "d": ["Justo cuatro meses después de Ridaniya y treinta y seis días después de la ejecución de Tomanbay, con la llegada de la flota otomana al mando de Câfer Bey al puerto, Alejandría pasó a la administración otomana; los puertos del delta como Rosetta (Reşîd) y Damieta se vincularon en el mismo proceso. El que este gran puerto de Egipto abierto al Mediterráneo fuera recibido meses después de la caída de El Cairo y por mar y no por tierra muestra claramente que la conquista se completó no con una sola batalla sino región por región. Alejandría se convertiría desde entonces en el puerto vital que unía Estambul con El Cairo. Otros lugares incorporados en la misma fecha: Reşîd (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Incorporación pacífica del Hiyaz: bay'a de Abû Numayy, hijo del sharif de La Meca", "c13b98c7"], "d": ["Selim el Severo había pensado primero en enviar tropas para tomar La Meca y sus alrededores, pero renunció a ello cuando el emir de La Meca, Sharif Barakat, comunicó su obediencia. Abû Numayy, hijo de doce años de Barakat, llegó a El Cairo con los regalos de su padre y las llaves de La Meca y fue recibido por el sultán. Así el Hiyaz se incorporó a los otomanos no como consecuencia automática de Ridaniya, sino cinco meses y medio después y sin que se disparara un solo tiro, por vía pacífica y de bay'a. Otros lugares incorporados en la misma fecha: Taif.", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Aceptación del título de Servidor de los Dos Santuarios y jutba en Medina", "63b32b59"], "d": ["Tras la segunda recepción de la delegación de La Meca, Selim el Severo asumió oficialmente la protección de los Haramayn y comenzó a usar el título de «hâdimü'l-Haremeyni'ş-şerîfeyn» (Servidor de los Dos Nobles Santuarios). Sharif Barakat, vistiendo el kaftán honorífico que se le envió, hizo leer la jutba en nombre del sultán; al viajar también la delegación de Medina a Estambul, el emirato de Barakat fue confirmado con berat. El sultán envió a la población de los Haramayn doscientas mil monedas de oro y abundantes provisiones e inició la tradición del surre, que se repetiría cada año. Otros lugares incorporados en la misma fecha: Yanbu, Tabuk.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Entrada de Selman Reis al servicio otomano y traspaso de la política del mar Rojo", "771da99a"], "d": ["Selman Reis, que defendió Yeda contra los portugueses, llegó a El Cairo y se presentó ante Selim el Severo; aunque fue retenido durante un tiempo, en 1519 fue llamado a Estambul y se comprometió a preparar treinta galeras y algunos galeones contra la amenaza portuguesa. Esta entrevista es el comienzo del traspaso de la política del mar Rojo y del océano Índico desde la herencia mameluca para vincularla directamente a Estambul. Los otomanos eran ahora, además de un Estado mediterráneo, una potencia con política oceánica.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Salida de Selim el Severo de El Cairo y beylerbeyilik de Hayır Bey", "8cd4fb23"], "d": ["Selim el Severo, que permaneció unos ocho meses en Egipto y estableció el orden administrativo, financiero y militar, salió de El Cairo; Hayır Bey, antiguo nâib de Alepo que en Marŷ Dābiq aceleró la derrota mameluca retirando el ala izquierda, comenzó a gobernar desde la Ciudadela como primer beylerbeyi otomano de Egipto. La elección de un gobernador de origen mameluco fue una política de transición deliberada, que evitaba que la nueva administración resultara extraña a la población local. En el camino de regreso el sultán llevó consigo a Estambul al último califa abasí al-Mutawakkil III y a artistas y sabios selectos de Egipto.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Fin del califato abasí de El Cairo — la tradición de la «ceremonia de traspaso»", "1d357640"], "d": ["Selim el Severo, al conquistar Egipto, trajo consigo a Estambul al último califa, al-Mutawakkil III Alà Allāh, hecho prisionero en Marŷ Dābiq; con ello terminó el califato abasí de El Cairo, que desde 1261 subsistía sin autoridad a la sombra de los sultanes mamelucos. En cambio, la célebre tradición de que el califato fue transferido a Selim en una ceremonia oficial en Santa Sofía aparece por primera vez a finales del siglo XVIII en la obra de d'Ohsson y no figura en ninguna de las fuentes de la época de Selim. La Enciclopedia del Islam del TDV considera la tradición inventada, ya que no existe una fuente original que documente la ceremonia, pero registra también que para el traspaso del califato no se necesitaba conforme a la ley islámica semejante ceremonia.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum se incorporó a la administración otomana — quebrada la influencia safávida en Anatolia oriental", "78d1be02"], "d": ["Aunque tras la victoria de Çaldıran (1514) creció la influencia otomana en la región, la toma completa de Erzurum se retrasó hasta que se quebró la influencia iraní; la ciudad pasó a la administración otomana solo en 1518-19, después de la campaña de Egipto. Erzurum había caído bajo dominio safávida en 1502, cuando el sha Ismail puso fin al principado de los Akkoyunlu; así se cerró ese período de dieciséis años. En 1534, durante la campaña de los Dos Irak, se establecerá el beylerbeylik de Erzurum. Entre 1518 y 1519, Aşkale, junto con la región de Erzurum, pasó a la administración otomana (día sin confirmar).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Comienzo de las rebeliones celalíes: sublevación de Şeyh Celâl de Bozok", "99bd8a99"], "d": ["En la región de Bozok, un hombre llamado Şeyh Celâl proclamó ser el mahdi y se sublevó en los alrededores de Tokat; aunque la rebelión fue sofocada, su nombre dio nombre durante un siglo a todos los movimientos de bandolerismo y sublevación en Anatolia. Al combinarse a finales del siglo XVI con la disolución del sistema de timar y la presión demográfica, el celalismo se transformó en el problema de seguridad interna más duradero del imperio. Las sublevaciones provocaron en Anatolia migraciones masivas llamadas «gran huida» (büyük kaçgunluk).", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Vinculación de Argel al Estado otomano", "b8eba4c1"], "d": ["Hayreddin Reis, que resistía en el norte de África a la presión española, se dirigió a Estambul para sostenerse y ofreció Argel al sultán, y la jutba se leyó en nombre de Selim el Severo. Así Argel se incorporó oficialmente a las tierras otomanas, y a Hayreddin se le enviaron tropas y cañones con el título de beylerbeyi. Esta vinculación sentó las bases del dominio naval otomano en el Mediterráneo occidental, que duraría siglos. Otros lugares incorporados en la misma fecha: Constantina, Cherchell (Şerşel), Medea (Titteri), Sétif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Fallecimiento de Selim el Severo en Çorlu", "9fe83744"], "d": ["Selim I, que en ocho años había más que duplicado el territorio del Estado, salió de Estambul el 18 de julio de 1520 para una nueva campaña; no pudo avanzar más allá de Çorlu a causa de un gran tumor aparecido en su espalda. Pese a la intervención de los médicos su enfermedad se agravó y, tras un tratamiento sin esperanza de dos meses, falleció allí el 8-9 de Shawwal de 926 (21-22 de septiembre de 1520). Con Çaldıran, Marŷ Dābiq y Ridaniya había detenido a Irán, hecho desaparecer el Estado mameluco y traído a los otomanos el califato y el patronazgo de los Haramayn. Dejó un solo hijo varón: Süleyman.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["La isla de Nikaria (Icaria) entra en la administración otomana", "6afa972b"], "d": ["Nikaria, situada entre Samos y Quíos, estuvo desde 1481 hasta 1521 bajo la administración de los Caballeros de San Juan de Rodas; el primer período otomano en la isla comenzó en 1522 y duró hasta 1822. En este período, el kaymakam era responsable de la recaudación y el pago de los impuestos; como en las demás islas del Egeo, subsistió también un consejo local de ancianos (demogerontia), que de vez en cuando entró en conflicto con la administración otomana.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Anexión del país de Dulkadir — eyalet de Dulkadır con centro en Maraş", "595c3c30"], "d": ["El país de Dulkadır, que tras el desastre de Turnadağ de 1515 continuaba como beylicato vasallo del Imperio otomano, se anexionó directamente a los territorios otomanos tras el asesinato de Şehsuvaroğlu Ali Bey con sus hijos en Artukova, y se convirtió en un eyalet con centro en Maraş. La región de Bozok del beylicato fue vinculada a la administración otomana como sanjacado aparte. Así se cerró el período dulkadírida, de unos dos siglos, de Maraş, Elbistan, Göksun, Gürün, Zamantı y Darende; el beylicato tapón en la frontera mameluca desapareció por completo.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Conquista de Knin", "a46d3117"], "d": ["Con las incursiones realizadas en los años 927-928 (1521-1522) por el sanjakbey de Bosnia Gazi Hüsrev Bey, pasaron a la administración otomana una serie de fortalezas venecianas, entre ellas Knin, Skradin y Ostrovica; la frontera fue empujada más allá de la segunda cadena montañosa. Esta cadena de conquistas puso los cimientos del sanjacado de Dalmacia, que se completaría quince años después con la toma de Klis.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Retirada de los Caballeros: cesión de Bodrum, Cos y el Dodecaneso", "ea01666e"], "d": ["Conforme a las condiciones de rendición de Rodas, los caballeros de San Juan evacuaron no solo el centro de la isla, sino todas las posiciones que habían mantenido durante doscientos años. La fortaleza de Bodrum (San Pedro), en la costa de Anatolia, y las islas de Cos, Calimnos y Lero pasaron así a la administración otomana sin combate. Con esta cesión, completada dos semanas después de la caída de Rodas, la presencia latina en el rincón sudoriental del Egeo terminó por completo.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Rebelión de Ahmed Paşa el Traidor en Egipto", "b18bb805"], "d": ["Ahmed Paşa, enviado al gobierno de Egipto mientras esperaba el gran visirato, proclamó su independencia en El Cairo declarándose «al-Malik al-Mansûr Sultán Ahmed». La rebelión fue sofocada en poco tiempo y el pachá fue ejecutado, pero el suceso mostró la fragilidad del control central en la provincia más rica del imperio. A raíz de ello İbrahim Paşa fue a Egipto y mandó preparar el célebre Código de Egipto (Mısır Kanunnâmesi), que reorganizó la administración de la provincia.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Anexión de la Bosnia septentrional: Jajce y Banaluka", "8ec86cfa"], "d": ["Cuando la línea de defensa húngara se derrumbó tras Mohács, el sanjakbey de Bosnia Gazi Hüsrev Bey marchó al valle del Vrbas y tomó las últimas fortalezas bosnias que quedaban al reino húngaro. Con la caída de Jajce y Banaluka, el eyalet de Bosnia llegó al norte hasta el río Sava y nació el frente de Croacia. Banaluka se convirtió en poco tiempo en el segundo centro del eyalet.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Toma de Buda y entrega a Zápolya", "fba4f89b"], "d": ["En el camino de la campaña de Viena, el ejército otomano sitió y recuperó Buda, que había caído en manos de Fernando, y entregó la ciudad al rey húngaro János Szapolyai, bajo protección otomana. Así se estableció sobre Hungría un modelo de reino vasallo tapón en la rivalidad entre Habsburgo y otomanos. Este orden duraría hasta 1541; tras la muerte de Zápolya, Buda sería convertida en provincia otomana directa.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["El Legislador salió a la campaña alemana — desafío a Carlos V", "7c3d7055"], "d": ["Tras el fracaso del asedio de Viena y el nuevo asedio de Buda por Fernando, el sultán salió de Estambul esta vez para atraer en persona al emperador Carlos V a una batalla campal. El ejército se vería retenido en agosto por la resistencia de la pequeña fortaleza de Güns, y al no salir el emperador a combatir, la campaña quedaría limitada a incursiones. La campaña preparó el terreno de la primera paz con los Habsburgo al año siguiente.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Campaña alemana y asedio de Güns (Kőszeg)", "8aec937a"], "d": ["El Legislador marchó con su ejército contra Austria con el fin de forzar a Carlos V a una batalla campal; la pequeña fortaleza de Güns resistió veinticinco días y retrasó el avance del ejército. Al no salir el emperador a combatir, los akıncı golpearon los alrededores de Viena y se regresó por el avance de la estación. La campaña no trajo ganancias territoriales, pero al sentar a los Habsburgo a la mesa preparó el terreno de la paz del año siguiente.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Tratado de Estambul — primera paz con los Habsburgo", "b085767a"], "d": ["El sultán, que recibió al enviado de Fernando, Cornelius, consintió en un armisticio, y surgió el primer texto oficial de paz entre los otomanos y Austria. Por el tratado Fernando aceptó pagar un tributo anual por las tierras húngaras que tenía en su poder, y el archiduque de Austria fue considerado en el protocolo igual al gran visir. Este estatuto desigual fue la expresión clara de la pretensión de superioridad de la diplomacia otomana en el siglo XVI.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Toma de Kars y apertura de la frontera nororiental", "742e3101"], "d": ["Mientras la columna de vanguardia de la Campaña de los Dos Irak (Irakeyn Seferi) se dirigía desde Erzurum hacia el este, la fortaleza de Kars, que estaba en poder del atabegato georgiano y yacía en ruinas desde Timur, fue recibida sin encontrar resistencia. Como la ciudad dominaba el paso entre el arco del Aras y Çıldır, se la consideraba la llave de la puerta septentrional que se abre a Irán. Esta ganancia fue el primer eslabón del beylerbeylik de Kars, que se fundaría treinta años después, y de la línea del Cáucaso.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Primera entrada en Tabriz — apertura de la Campaña de los Dos Irak", "cf7ed4e3"], "d": ["İbrahim Pasha, que se adelantó con el título de serdar-ı ekrem, entró sin encontrar resistencia en Tabriz, capital safávida, cuando el shah Tahmasb evitó la batalla campal y se replegó al interior. Kanunî llegó también a la ciudad en septiembre; pero, a causa de la llegada del invierno y del excesivo alargamiento de la línea de abastecimiento, el ejército se dirigió hacia Bagdad y Tabriz no pudo mantenerse durante mucho tiempo. La ciudad, tomada por segunda vez desde Çaldıran, fue el lugar donde los otomanos aprendieron que en el este conquistar era fácil y conservar difícil.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Conquista de Túnez por Barbaros", "d8754216"], "d": ["El kapudán pachá Barbaros Hayreddin Paşa, tras golpear con su flota las costas de Italia, se dirigió a Túnez, hizo huir al soberano hafsí Mulay Hasan y entró en la ciudad. La toma de Túnez, por su posición de control del estrecho de Sicilia, volvió de golpe el equilibrio de poder en el Mediterráneo occidental a favor de los otomanos. Sin embargo, este dominio no duraría mucho: Carlos V respondería al año siguiente con una gran flota.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Pérdida de Túnez ante Carlos V", "a691f0f8"], "d": ["Carlos V, tras derribar La Goleta (Halkulvâd) en una gran campaña apoyada por las flotas genovesa y papal, tomó Túnez y restituyó en el trono a Mulay Hasan bajo protección española. Con el establecimiento de una guarnición española en la ciudad, el avance otomano en el Mediterráneo central quedó detenido temporalmente. La conquista definitiva de Túnez sólo sería posible cuarenta años después, en 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Operaciones de Gazi Hüsrev Bey a lo largo del Sava: Bosanski Brod y Jasenovac", "3740ec83"], "d": ["Tras la toma de Jajce y Banaluka en 1528, las fortalezas a lo largo del río Sava permanecieron todavía algún tiempo en la frontera croata-eslavona dependiente de la corona de los Habsburgo. Gazi Hüsrev Bey, que en 1536 fue sanjakbey de Bosnia por tercera vez, tomó ese mismo año Požega y sus alrededores y agregó a la administración otomana también las fortalezas de Brod y Jasenovac, en la orilla del Sava. Así la frontera septentrional de Bosnia llegó hasta el Sava; la región se completó dos años después con la toma de Dubica.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Ejecución de Makbul İbrahim Paşa", "348aa7b8"], "d": ["İbrahim Paşa, que fue gran visir durante trece años, amigo más íntimo del Legislador y de hecho segundo hombre del Estado, fue estrangulado y ejecutado sin que se adujera motivo alguno en el palacio al que había sido invitado a la ruptura del ayuno. Su actitud en la campaña de los Dos Irak, el uso del título de «sultán serasker» y los equilibrios internos del palacio se consideran factores de su muerte. La ejecución es un punto de inflexión que muestra que los grandes visires no gozaban de seguridad absoluta en la administración central otomana.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Conquista de la fortaleza de Klis y fundación del sanjacado de Dalmacia", "6ffd4ebf"], "d": ["Murad Bey, converso de origen croata y lugarteniente (kethüdâ) de Gazi Hüsrev Bey, tomó a Venecia la fortaleza estratégica de Klis, inmediatamente al norte de Split. Inmediatamente después de la conquista, Klis fue convertida en centro de un nuevo sanjacado y kaza que abarcaba su entorno; los límites de este sanjacado trazaron en gran parte el marco de la Croacia otomana. Esta conquista, llegada quince años después de Knin, completó el esqueleto administrativo del interior de Dalmacia.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Asedio de Corfú y guerra con Venecia", "11af95bd"], "d": ["Tras la campaña de Apulia, el ejército otomano desembarcó en Corfú y puso sitio a la poderosa fortaleza veneciana de la isla. Por lo escarpado de la fortaleza, las graves pérdidas y las condiciones de la estación, el 6 de septiembre se levantó el bloqueo y se retiró. Aunque el asedio resultó infructuoso, la guerra abierta con Venecia terminaría con la incorporación a los otomanos de numerosas islas del Egeo y del Adriático y con la victoria de Preveza al año siguiente.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Campaña de Barbarroja en el Egeo: toma de las islas gobernadas directamente por Venecia", "1b32ed96"], "d": ["La flota que regresaba del asedio de Corfú, aprovechando que se había declarado la guerra a Venecia, fue recibiendo una a una en el Egeo las islas que dependían directamente de Venecia y no del ducado. Egina fue tomada tras una fuerte resistencia; Astipalea, en poder de la familia Querini, Escarpanto y Casos se rindieron, y Patmos, bajo administración monástica, aceptó también la protección otomana. El Ducado de Naxos, en cambio, fue sometido a tributo y dejado en su lugar; su anexión tendría que esperar a 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Campaña de Barbarroja en el Egeo septentrional: toma de Esciros y de las Espóradas del Norte", "20ab688e"], "d": ["En el camino hacia Préveza, la flota fue recibiendo una a una las islas del Egeo septentrional que se habían refugiado en Venecia tras la conquista de Constantinopla. Esciros, al norte de Negroponte, y Escíatos, Escópelos y Alónisos, que guardan la entrada del golfo de Salónica, entraron así en la administración otomana. Estas islas cerraron el último vacío del Egeo septentrional que, aunque Negroponte había sido tomada en 1470, permaneció sesenta y ocho años más en manos de Venecia.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Toma de Adén y anexión de la costa de Yemen", "e7d46d8f"], "d": ["La flota que salió de Suez para la campaña de la India se dirigió primero a la costa de Yemen, porque no se podía salir al océano sin asegurar el mar Rojo. Hadım Süleyman Pasha entró el 3 de agosto de 1538 en el puerto de Adén; Âmir ibn Dâvud, señor tahirí inclinado hacia los portugueses, fue hecho venir a la puerta de la nave capitana y ejecutado, y en la ciudad se dejó una guarnición de 500 hombres. Durante la misma campaña fueron también recibidas Moca y las islas de Kamarán y Farasán, que dominan el estrecho, y se echaron los cimientos del beylerbeylik de Yemen. Así, el Estado otomano poseyó por primera vez toda la costa septentrional de Bab el-Mandeb; Saná y las regiones interiores tendrían que esperar nueve años más.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Campaña de Moldavia y anexión de la región de Bucak (Bender)", "90a88a56"], "d": ["En la campaña emprendida contra el voivoda de Moldavia, Petru Rareș, que no cumplía sus obligaciones con los otomanos, se tomó Suceava y la ciudad de Iași fue saqueada por el kan de Crimea Sahib Giray. El sultán puso a Ștefan Lăcustă (Çekirge Stefan) en el voivodato y anexionó directamente a las tierras otomanas Bender junto con la región de Bucak (Besarabia meridional). Esta anexión fue uno de los eslabones que convirtieron las costas noroccidentales del mar Negro en un mar interior otomano. Moldavia ya era un voivodato vasallo de los otomanos; esta campaña no tomó el territorio a un Estado extranjero, sino que sólo sacó al voivoda la administración interna de Bender y Bucak y la vinculó directamente al sultán; el resto del voivodato mantuvo su estatuto de vasallo. La misma estructura se repetiría en 1484 en Kili y Akkerman y en 1713 en Hotin: fortalezas fronterizas directas, tierras interiores vasallas.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Cesión de Nauplia (Anabolu) por tratado", "104d0937"], "d": ["La guerra con Venecia, que duró tres años desde Préveza, terminó cuando la república aceptó entregar sus dos últimas fortalezas en la Morea. Nauplia y Monemvasía (Benefşe), que no se habían podido tomar mediante asedio, fueron cedidas al Imperio otomano en la mesa de negociación, además de una indemnización de guerra de trescientos mil ducados. La península de la Morea quedó así unificada sin dejar una sola huella veneciana.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Entrada de Szeged en la administración otomana y formación del livâ de Szeged", "019aa000"], "d": ["Tras establecerse plenamente en 1541 la administración otomana en Buda, los notables de Szeged adoptaron la soberanía de Fernando I y se prepararon para la defensa armada. Küçük Bâlî Pasha, beylerbey de Buda, hizo venir a su presencia a los dirigentes de la ciudad a comienzos de 1543 y los hizo ejecutar por traición; a continuación envió una unidad para tomar la ciudad. Entonces se formó el livâ de Szeged y se nombró como primer sanjakbey a Derviş Bey, hijo de Bâlî Pasha; el livâ se extendía al principio entre el Danubio y el Tisza.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Conquista de Valpó, Siklós y Pécs", "2ca030a3"], "d": ["El primer objetivo de la campaña de Hungría emprendida dos años después de la anexión de Buda era asegurar el flanco meridional de la nueva provincia entre el Drava y el Danubio. Tras la toma de las fortalezas de Valpó y Siklós, se rindió Pécs (Peçuy), centro de Baranya. La ciudad se convertiría en el centro más poblado y más embellecido de la Hungría otomana, y el historiador İbrahim Peçuylu tomaría su nombre de ella.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Conquista de Esztergom y Székesfehérvár (İstolni Belgrad)", "efca9e05"], "d": ["En la campaña de Hungría que el Legislador dirigió en persona, tras un asedio de dos semanas y media, Esztergom, centro religioso y sede arzobispal del Reino de Hungría, pasó a la administración otomana. A continuación se tomó también İstolni Belgrad (Székesfehérvár), ciudad de coronación de los reyes húngaros, y quedó completo el cinturón defensivo de la provincia de Buda. Esztergom permanecería hasta 1595 en manos otomanas como fortaleza clave de la línea del Danubio.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Cinturón defensivo septentrional y occidental de Buda: Vác, Hatvan y Simontornya", "733ee5ce"], "d": ["Tras la toma de Esztergom e Istolni Belgrad, el beylerbey de Buda se puso en marcha, sin campaña del sultán, para completar el anillo de fortalezas que rodeaba la capital. Vác, en el recodo del Danubio, Hatvan, puerta del Alföld, y Simontornya, en la línea del Sió, fueron recibidas una a una. Las ganancias de este año silencioso transformaron Buda de una ciudad de frontera en un centro provincial que resistiría ciento cuarenta años.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Anexión de Basora y salida al golfo Pérsico", "02f87c11"], "d": ["Râşid ibn Megâmis, señor de Basora, había comunicado su sumisión a Kanunî durante la conquista de Bagdad (1534) y en 1538 había enviado las llaves de la ciudad. Cuando su sucesor, el jeque Yahyâ, se puso contra los otomanos, el beylerbey de Bagdad Ayas Pasha marchó por tierra y el sanjakbey de Mosul con 120 barcos por el Éufrates; Ayas Pasha entró en Basora el 26 de diciembre de 1545 y la ciudad se convirtió en centro de un beylerbeylik. Este puerto, situado en la desembocadura del Shatt al-Arab, fue la puerta por la que el Imperio otomano se abrió al golfo que Portugal controlaba desde Ormuz; por el Tratado de Amasya de 1555, Irán también reconoció esta situación.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Conquista de Saná y del interior de Yemen", "d31ded85"], "d": ["Tras Taiz fue tomada también Saná, y todo el país quedó incorporado al beylerbeylik. Pero a causa de la geografía escarpada y de la diferencia de escuela jurídica, este dominio no fue nunca cómodo; Yemen se convirtió para el Imperio otomano en un frente que devoraba soldados sin cesar.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Conquista de Taiz", "d4509df9"], "d": ["En Yemen, donde nueve años antes uno se había contentado con la franja costera, ante el fortalecimiento progresivo de los imames zaidíes en el interior montañoso, las fuerzas de Özdemir Pasha subieron a la meseta y tomaron Taiz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-18:0":{"b": ["Tratado de Estambul — paz de cinco años con los Habsburgo", "41f81773"], "d": ["Se firmó una paz de cinco años de duración entre los otomanos y los Habsburgo; Fernando aceptó pagar 30.000 ducados anuales por las tierras húngaras que tenía en su poder. El tratado registró jurídicamente la situación de hecho de Hungría dividida en tres. El haber asegurado así el frente occidental dio al Legislador la posibilidad de organizar nuevas campañas contra Irán.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Segunda Campaña de Irán y nueva toma de Tabriz", "e82365df"], "d": ["En la campaña emprendida por incitación de Elkas Mirza, hermano del shah Tahmasb que se había rebelado contra este y refugiado en Estambul, el ejército entró por segunda vez en Tabriz. Como los safávidas, de nuevo, evitaron la batalla campal y se retiraron quemando el territorio, solo se pudo permanecer en la ciudad unas pocas semanas. La campaña dejó confirmado que Tabriz no podía conservarse y orientó la estrategia otomana a establecer una línea fronteriza permanente, es decir, a fortificar Van.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Conquista de Van y fijación de la frontera oriental", "fc8f930b"], "d": ["La fortaleza de Van, sitiada al regresar de Tabriz, era por su posición sobre la roca de la orilla oriental del lago la llave indiscutible de la región, y se rindió tras un breve asedio. La ciudad fue convertida de inmediato en centro de un beylerbeylik; a ella se vincularon los sanjacados de Erciş, Adilcevaz y Hakkâri. A diferencia de Tabriz, Van se conservó y durante cuatrocientos años siguió siendo la posición permanente más avanzada del Imperio otomano en el este.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Anexión de Lahsa y Qatif — la costa árabe del Golfo", "f6701e60"], "d": ["Tras la toma de Basora, fue capturada Qatif, que se había convertido en el puesto avanzado de Portugal en la costa occidental del golfo, y junto con los oasis de Lahsa del interior se fundó un nuevo beylerbeylik. Fue el punto de partida de las operaciones dirigidas a Bahréin y Ormuz. El Estado otomano obtuvo así voz, a la vez, en las costas del mar Rojo y del golfo de Basora de la península arábiga.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Pérdida de Shahrizor — el bey de Ardalán, Sührâb, se inclinó hacia los safávidas", "5600efc9"], "d": ["La región de Shahrizor, que había reconocido la administración otomana durante la Campaña de los Dos Irak (1535), estaba gobernada por el emir de Ardalán Bige Bey, que residía en la fortaleza de Zalm. A la muerte de Bige Bey en 1550, su hermano Sührâb, que se apoderó de la fortaleza de Zalm y dominó el beylicato, se inclinó hacia los safávidas y rompió su obediencia a los otomanos; la región de Shahrizor salió así de la influencia otomana. La región solo se recuperaría en 1554, durante la campaña de Najicheván, con el asedio y la toma de la fortaleza de Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Toma de Ardahan y de la cuenca de Çıldır", "14c9eb76"], "d": ["El beylerbey de Erzurum, durante la guerra que se libraba con los safávidas, se dirigió a las tierras de los atabegs georgianos en el arco del Kura, y anexionó a la administración otomana Ardahan y los alrededores de Çıldır. La línea Kars-Ardahan quedó así unificada y las mesetas que se abren a Georgia en el nordeste pasaron a estar bajo control. El orden administrativo definitivo de la región se completaría veintisiete años después con el eyalet de Çıldır.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokullu Mehmed Pasha cruza el Danubio — comienzo de la guerra de Transilvania", "38fde931"], "d": ["Se consideró necesaria una nueva campaña por los disturbios provocados por el monje Martinuzzi, tutor del joven rey de Transilvania János Zsigmond, y por la cesión por Transilvania de las fortalezas del Banato a Fernando; el mando se confió al beylerbey de Rumelia Sokullu Mehmed Pasha. El ejército cruzó el Danubio a pesar de los esfuerzos dilatorios de Martinuzzi y tomó Becse, Becskerek, Csanád y Lippa; pero el asedio de Temesvár fue levantado el 16 de noviembre a causa del frío. Así se abrió en Hungría una nueva guerra otomano-habsburgo.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["La ciudad de Lipova (Lippa) pasó al ejército austriaco de Castaldo — la fortaleza se rindió el 5 de diciembre", "a0e1ff0d"], "d": ["El ejército del general Castaldo sitió el 4 de noviembre Lipova, tomada por Sokullu Mehmed Pachá en octubre de 1551; dos días después la ciudad pasó a manos de los austriacos. Ulama Pachá defendió la fortaleza nueve días más con una guarnición de 5.000 hombres y salió el 5 de diciembre de 1551 por acuerdo. Lipova permaneció en manos de los Habsburgo hasta la caída de Timișoara en 1552.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Las fuerzas enviadas desde Timișoara ocupan las palanques del Banato meridional — Vršac, Haram, Keve", "edca0921"], "d": ["Tras la rendición de Timișoara al ejército otomano, las unidades separadas del ejército de asedio se dirigieron a las pequeñas palanques del Banato; según el relato de Bánlaky, las palanques de Versec, Facset, Mehádia, Csákóvár, Haramvár y Keve fueron ocupadas por estas fuerzas. Así también Haram, a orillas del Danubio, pasó a manos otomanas.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Conquista de Szolnok y fracaso del asedio de Eger", "a7156e8f"], "d": ["Tras la toma de Temesvár, los dos ejércitos otomanos unidos tomaron Szolnok, sobre el Tisza, casi sin combate, cuando los guardias mercenarios abandonaron la fortaleza. La fortaleza de Eger, sitiada a continuación, no pudo ser tomada ante la resistencia de treinta y ocho días de la guarnición de dos mil hombres al mando de István Dobó, y el ejército se retiró al llegar el invierno. Que en la misma campaña una fortaleza cayera con facilidad mientras otra resistía fue la primera señal abierta de que en Hungría la frontera ya no avanzaba espontáneamente en favor de los otomanos.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Alianza otomano-francesa — la flota francesa pasa a las órdenes otomanas", "a8e01b22"], "d": ["Por el tratado del 1 de febrero de 1553 la flota de Francia fue puesta a las órdenes de la flota otomana; se previó una operación conjunta en el Mediterráneo occidental contra España. Tras el tratado, Turgut Reis salió el 15 de junio de 1553 con cuarenta y cinco galeras para apoyar a Francia. Fue el primer tratado de alianza oficial que trasladó a una cooperación militar la base comercial de las capitulaciones de 1536.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Ejecución del príncipe Mustafa en Konya Ereğlisi", "dec36858"], "d": ["El príncipe Mustafa, que entró en la tienda de su padre para unirse al ejército reunido para la campaña de Najicheván, se encontró con los verdugos cuando iba a presentarse ante el sultán y fue estrangulado. El asesinato del aspirante a heredero, muy querido en el ejército, provocó una profunda ira entre los jenízaros y Rüstem Paşa fue apartado del gran visirato. El suceso pasó a la literatura y a la memoria popular como una de las rupturas más controvertidas de la política principesca otomana.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Traslado de la frontera de Ibrim y Nubia hacia el sur", "c57d5d77"], "d": ["La frontera meridional del beylerbeylik de Egipto se trasladó más allá de la segunda catarata cuando la fortaleza de Ibrim, que se alza sobre un cabo rocoso del Nilo, fue fortificada por Özdemir Bey y la Baja Nubia quedó plenamente incorporada al Egipto otomano. (La organización administrativa otomana en Ibrim se había establecido tras la conquista de Egipto; en el mapa Ibrim figura como otomana desde 1517. Este año es aproximado, la fuente no da año.) La fortaleza era tanto un dique contra las incursiones procedentes de Nubia como un punto de control de la ruta del oro y de los esclavos que iba a Sennar. La guarnición bosnia instalada allí se hizo tan permanente que sus descendientes seguían en la fortaleza trescientos años después. Las fuentes dan dos relatos distintos sobre el momento de la entrada de Ibrim en la administración otomana: mientras el artículo «Sudán» del TDV vincula la incorporación de la Baja Nubia al Egipto otomano a la campaña de Özdemir Pasha a mediados del siglo XVI, el artículo «Nubia» escribe que la región hasta el valle de Wadi Halfa y la organización administrativa en Ibrim se establecieron inmediatamente después de la conquista de 1517. El sanjacado de Ibrim fue vinculado el 26 de julio de 1573 al eyalet de Abisinia (Habeş).", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Toma de Bugía (Bicâye) a los españoles", "49691cda"], "d": ["Bugía, que llevaba cuarenta y tres años en poder de España y dividía en dos la costa entre Argel y Constantina, se rindió tras ser sitiada por tierra y por mar. Con la caída de la fortaleza, la costa del odjak de Argel quedó continua hasta Orán. En España esta pérdida provocó tal indignación que el comandante que entregó la fortaleza, Alonso de Peralta, fue ejecutado en su patria.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Incorporación de Zeila al eyalet de Abisinia (Habeş)", "7bbf369a"], "d": ["El puerto de Zeila, en la costa africana del golfo de Adén, en el extremo meridional del eyalet de Abisinia, fue incorporado a la administración otomana. Esta ciudad, que era la puerta del Sultanato de Adal al mar, fue el último punto de abastecimiento para los barcos que salían más allá de Bab el-Mandeb. Con la incorporación de Zeila, la frontera del Estado otomano en África alcanzó su punto más meridional.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Batalla de los príncipes en Konya", "1c8de387"], "d": ["El príncipe Bayezid, que entró en la lucha por el trono, llegó ante Konya con unos 30.000 hombres y en un combate de dos días fue vencido por su hermano el príncipe Selim. Bayezid, derrotado, se refugió en Irán, junto al sah Tahmasp, vía Amasya. La batalla convirtió la crisis de sucesión de los últimos años del Legislador en un problema de política exterior.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Victoria naval de Yerba (Cerbe)", "c7b905c1"], "d": ["La flota otomana al mando de Piyâle Paşa dispersó frente a Yerba, con una maniobra de partición en dos, a la flota aliada hispano-genovesa-maltesa reunida para recuperar Trípoli. Los aliados perdieron la mayor parte de sus flotas y la fortaleza de la isla cayó poco después. Yerba es considerada, tras Preveza, la segunda gran victoria naval que consolidó la superioridad otomana en el Mediterráneo.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Ejecución del príncipe Bayezid en Qazvín", "a759de14"], "d": ["El príncipe Bayezid, refugiado en Irán, tras largas negociaciones fue entregado por el sah Tahmasp a la delegación otomana y estrangulado junto con sus cuatro hijos. A cambio de la entrega, los safávidas obtuvieron importantes concesiones materiales y garantías de frontera. Con esta ejecución desapareció el último obstáculo para el acceso de Selim II al trono y se mantuvo el orden de paz del Tratado de Amasya.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Toma de Quíos a los genoveses", "a4559b96"], "d": ["Quíos, que durante doscientos años había sido administrada como colonia comercial por la familia genovesa Giustiniani y pagaba tributo a los otomanos, fue recibida por Piyâle Pasha sin disparar un solo tiro, con el pretexto de que retrasaba el tributo y daba puerto a los barcos enemigos. Con Quíos e Psara fue liquidada también la última presencia genovesa en la costa oriental del Egeo. Conservándose la producción de almáciga y los privilegios de los quiotas, la isla fue vinculada al eyalet de Cezâyir-i Bahr-i Sefîd.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Anexión del Ducado de Naxos — todas las islas Cícladas", "68f0ec0b"], "d": ["El Ducado latino de Naxos, que duraba desde 1207 y pagaba tributo a los otomanos desde 1537, fue abolido alegando las quejas llegadas por la opresión de su pueblo por el último duque, Giacomo Crispo. Naxos, Paros, Antiparos, Andros, Siros, Míconos, Ios, Anafi y todas las islas Cícladas de alrededor pasaron con una sola decisión a la administración directa otomana. Kanunî confió durante algún tiempo la administración de las islas a Yasef Nasi; el dominio latino de tres siglos y medio terminó así en medio del Egeo.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Rebelión de Yemen y campaña de Koca Sinan Paşa a Yemen", "c8218d8e"], "d": ["El imán zaidí Mutahhar se sublevó alegando que se recaudaban impuestos por la fuerza y arrancó la administración otomana de la mayor parte de Yemen. Koca Sinan Paşa, enviado desde Estambul, restableció el dominio otomano en la región con la campaña que llevó a cabo entre 1568 y 1570, tomando Kawkabān tras un largo asedio. La campaña fue de importancia vital para conservar el control de la puerta meridional del mar Rojo y de la ruta comercial del océano Índico.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Alianza defensiva con el Sultanato de Aceh y ayuda en el océano Índico", "8e835f24"], "d": ["Los enviados de Aceh, que pidieron ayuda al Legislador frente a los ataques portugueses, ofrecieron su vasallaje a Selim II tras el fallecimiento del sultán en Szigetvár, y con él se firmó un tratado defensivo. El sultán ordenó que se enviaran desde Alejandría cañones, fusiles, municiones y artesanos; se prepararon diecisiete navíos de guerra para ser enviados a aguas de la India. La extensión de la rebelión de Yemen impidió que la flota se hiciera a la mar, pero los artilleros y artesanos otomanos que llegaron a Aceh dejaron una huella duradera en la región.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Desembarco en Chipre: toma de Limasol", "9074ccc9"], "d": ["El ejército otomano desembarcado en la isla tomó Limasol sin encontrar mucha resistencia y al día siguiente se dirigió a Lárnaca. Gracias al descontento de la población local con la administración veneciana y a su ayuda a las fuerzas otomanas, tampoco en Lárnaca se encontró una resistencia seria; el embarcadero de Tuzla fue convertido en base de desembarco de tropas y material. Venecia había concentrado su defensa en Nicosia y Famagusta; el gobernador de Pafos solo comunicó su obediencia al serdar después de la caída de Nicosia.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Conquista de Nicosia (Lefkoşa)", "413d866b"], "d": ["Tras un asedio de cuarenta y cinco días, iniciado el 25 de julio de 1570, Nicosia, capital de Chipre bajo administración veneciana, se rindió al ejército otomano. La caída del centro de la isla acorraló la resistencia veneciana en la fortaleza de Famagusta. La conquista tuvo gran eco en Occidente y aceleró el proceso que condujo a la formación de la flota de la Santa Liga, bajo la dirección del papa.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Rendición de Kyrenia — la costa septentrional de Chipre", "39fdeea5"], "d": ["La caída de Nicosia el 9 de septiembre, pasada a cuchillo, quebró la resistencia en el norte de Chipre. La fortaleza de Kyrenia, detrás de la cordillera de Pentadáctilo, al saber la suerte de la capital se rindió con condiciones ocho días después, y a su guarnición se le permitió salir de la isla y fue enviada fuera. En la isla la bandera veneciana quedó solo en Famagusta, que resistiría todavía once meses más.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Reconstrucción de la flota tras Lepanto", "db51fe44"], "d": ["Lo primero que hizo Kılıç Ali Paşa, nombrado kapudán pachá tras el desastre de Lepanto, fue reconstruir la flota, que había sufrido graves pérdidas; los arsenales trabajaron sin interrupción durante el invierno de 1571-1572. En junio de 1572 una nueva flota de unas 250 galeras y 300 galeras de reises voluntarios se hizo a la mar en el Mediterráneo. Esta rápida recuperación mostró que Lepanto no había quebrado de manera duradera el poder naval otomano.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Tratado de Estambul con Venecia — reconocimiento de Chipre", "4d08ef50"], "d": ["Venecia, que quedó sola por la disolución de la Santa Liga, hizo una paz separada con los otomanos, reconoció oficialmente que Chipre pertenecía a los otomanos y aceptó pagar una indemnización de guerra. El tratado puso claramente de manifiesto que la victoria de Lepanto no había proporcionado al mundo cristiano ganancia política alguna. Venecia evitaría desde entonces durante setenta años entrar en guerra directa con los otomanos.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Fallecimiento de Selim II", "c289f5ee"], "d": ["Selim II, que tras una caída no pudo presentarse al diván durante unos dos meses, murió. Su muerte se mantuvo en secreto en el palacio durante doce días, hasta que su hijo mayor Murad llegó a Estambul desde Manisa. Las fuentes discrepan sobre el día de la muerte: Selânikî dice el 15 de diciembre; Gerlach, Mehmed b. Mehmed y Cenâbî dicen el 13 de diciembre.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Proclamación de la muerte de Selim II y acceso al trono de Murad III", "84334d70"], "d": ["La muerte de Selim II y el acceso al trono de Murad III, traído de Manisa, se proclamaron oficialmente el 22 de diciembre de 1574. El nuevo sultán permanecería veintiún años en el trono, y su sultanato se recordaría por las largas guerras con Irán en el este, la víspera de la Larga Guerra en el oeste y la adulteración del akçe en el interior. El antiguo orden continuó en el gobierno del Estado hasta la muerte de Sokullu Mehmed Paşa en 1579.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Batalla de Wadi al-Mahazin (Alcazarquivir) — Abd al-Malik, con apoyo otomano, aniquiló al ejército portugués", "21280dac"], "d": ["Abd al-Malik, que se sentó con apoyo otomano en el trono de Marruecos, aniquiló en Wadi al-Mahazin al gran ejército del rey de Portugal Sebastián; como en la batalla murieron los tres soberanos a la vez, en las fuentes occidentales se la llama «batalla de los Tres Reyes». El poder militar de Portugal se derrumbó y el país pasó poco después a manos de España. Abd al-Malik también murió en la batalla; su hermano Ahmad al-Mansur, que le sucedió, comunicó la victoria a Estambul mediante una delegación. La relación entre los dos Estados se mantuvo al nivel de intercambio de enviados y regalos, no de tributo ni de vasallaje, y poco después se tensó por la cuestión de los regalos.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Declaración de lealtad de los habitantes de Derbent a Lala Mustafa Pasha — la Puerta de Hierro (Demirkapı) bajo administración otomana", "9c55aeff"], "d": ["Durante la campaña de Shirvan, una delegación de siete personas de los habitantes de Derbent fue a presencia del serdar Lala Mustafa Pasha, que se encontraba en Ereş, y declaró su lealtad. Derbent (Demirkapı), que cierra el estrecho paso entre la muralla del Cáucaso y el mar Caspio, desempeñó como paso obligado de los caminos terrestres del norte un papel clave en la conservación de Shirvan. El dominio otomano se mantuvo allí hasta 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Conquista de Shirvan: toma de Shamakhi", "9afae4c1"], "d": ["El ejército que se abrió hacia el Cáucaso tras la Victoria de Çıldır entró en Shirvan, la provincia más rica de los safávidas en la costa del Caspio, y tomó la ciudad central, Shamakhi. Özdemiroğlu Osman Pasha fue nombrado allí beylerbey y la rama septentrional de la Ruta de la Seda quedó puesta bajo control otomano. Shirvan se convertiría en el frente que más veces cambió de manos y más caro resultó de la guerra oriental, que duraría doce años.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Toma de Bakú — salida a la costa del Caspio", "eb5adab8"], "d": ["Como último eslabón de las operaciones de Shirvan, fue tomado el puerto de Bakú, en la costa occidental del mar Caspio. Los pozos de nafta de los alrededores de la ciudad eran ya entonces una fuente de ingresos conocida, y el puerto era el punto de salida de la seda iraní que llegaba por el Caspio. El Estado otomano pasó así a ser, por primera y única vez en su historia, ribereño del mar Caspio.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Conquista de Erevan (Revan) y construcción de la fortaleza", "7f623b7b"], "d": ["Ferhad Pasha, que recibió en Kars la orden de ir a Erevan y construir allí una fortaleza, marchó sobre Erevan, y la ciudad fue puesta bajo control otomano a comienzos del Ramadán de 991 (mediados de septiembre de 1583). En Erevan, que guarda la puerta septentrional del valle del Aras, se construyó una fortaleza nueva y grande, y la ciudad fue convertida en centro de un beylerbeylik. Erevan, situada en medio de la ruta del ejército entre Kars y Tabriz, era la columna vertebral logística del frente oriental. La fortaleza se construyó tan sólida que durante los dos siglos siguientes fue el objetivo constante de las guerras otomano-iraníes.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Anexión de Karabaj y Ganye", "29abaead"], "d": ["Como última ganancia de la guerra oriental de diez años, Ferhad Pasha marchó en 1588 sobre Ganye y entró en la ciudad el 1 de septiembre; la región de Karabaj, entre el Kura y el Aras, y su centro Ganye fueron puestos bajo la administración otomana. Así Shirvan, Erevan y Karabaj se unieron y se formó en el Cáucaso una línea otomana continua. El Tratado de Ferhad Pasha, firmado en 1590, confirmaría esta frontera, pero la ganancia solo pudo conservarse unos veinte años.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Conquista de Bihać", "651a7275"], "d": ["Telli Hasan Paşa, beylerbeyi de Bosnia, tras tomar en noviembre de 1591 Ripač, fortaleza avanzada de Bihać, se apoderó en 1592 de la ciudad y de la propia fortaleza; tras un asedio de diez días se rindió el comandante Lamberg. Esta conquista empujó la frontera de Bosnia a lo largo del río Una y fue la última gran ganancia otomana en vísperas de la Larga Guerra, que estallaría un año después con la muerte de Telli Hasan Paşa como mártir ante Kulpa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Comienzo de la «Larga Guerra» otomano-austriaca", "bd22c392"], "d": ["Cuando Telli Hasan Paşa, beylerbeyi de Bosnia, fue derrotado y cayó mártir ante Kulpa (Sisak), el Estado otomano declaró la guerra a Austria y comenzó la Larga Guerra, que duraría trece años. Esta guerra, en la que fue decisiva la infantería de armas de fuego, aceleró el empleo de sekban y soldados con fusil en el orden militar otomano y profundizó el declive del sipahi poseedor de timar. La guerra terminaría en 1606 con el Tratado de Zsitvatorok.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Paşa salió a la campaña de Austria — primera campaña de la Larga Guerra", "d4a2f46d"], "d": ["Tras la derrota y el martirio del beylerbeyi de Bosnia Hasan Paşa ante Sisak, el gran visir Koca Sinan Paşa convenció al sultán de ir a la guerra con palabras brillantes y promesas, y partió con 12.000 jenízaros y otras unidades. Así se abrió la primera campaña de la guerra otomano-austriaca, que duraría trece años.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Conquista de Yanıkkale (Győr)", "14b75207"], "d": ["El gran visir Koca Sinan Paşa recibió la rendición de Yanıkkale (Győr), considerada la cerradura del camino de Viena, tras un asedio de más de un mes. La caída de la fortaleza provocó gran pánico en Europa y fue la más brillante ganancia otomana en la Larga Guerra. Sin embargo, la fortaleza sólo podría mantenerse cuatro años.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Fallecimiento de Murad III", "1b62e886"], "d": ["Tras un sultanato de veintiún años, Murad III falleció en los días en que el ejército de Valaquia incendió Brăila y llegó hasta Silistra, y fue sepultado en el cementerio de Santa Sofía. Su hijo Mehmed III, llamado desde Manisa, llegó a Estambul diez días después y subió al trono (27 de enero de 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Pérdida de Esztergom ante Austria", "f420d333"], "d": ["Los defensores de Esztergom, que en el asedio dirigido por Karl von Mansfeld no recibieron ayuda suficiente, entregaron la fortaleza al archiduque Matías. Con el fin de un dominio otomano de cincuenta y dos años se rompió la cadena defensiva de la línea del Danubio y Buda quedó directamente amenazada. La fortaleza sólo pudo ser recuperada diez años después, en 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Conquista de la fortaleza de Eger (Eğri)", "3e511629"], "d": ["Tras una lucha de tres semanas, la poderosa fortaleza de Eger, que los otomanos no habían podido tomar antes, cayó por la rendición de los defensores. Esta conquista, en la que estuvo presente personalmente el sultán, reparó en cierta medida la moral que había creado la pérdida de Esztergom, y se fundó la provincia de Eger. Junto con la victoria de Mezőkeresztes, lograda dos semanas después, 1596 fue el año más exitoso de los otomanos en la Larga Guerra.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Pérdida de Yanıkkale (Győr)", "b4ccc679"], "d": ["Las tropas al mando de Miklós Pálffy y Adolf von Schwarzenberg recuperaron Yanıkkale haciendo saltar por sorpresa las puertas de la fortaleza. La pérdida de la fortaleza, que Koca Sinan Paşa había obtenido cuatro años antes con grandes esfuerzos, derrumbó la línea avanzada otomana en Hungría. Aunque ese mismo año fueron rechazadas las fuerzas enemigas que sitiaron Buda, el equilibrio de la guerra se transformó paulatinamente en una guerra de desgaste.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Sublevación de Karayazıcı Abdülhalim", "30493b0d"], "d": ["Karayazıcı Abdülhalim, que reunió a los sekban y levend huidos del ejército durante la Larga Guerra, puso bajo su control una amplia región de Anatolia central, tomó la fortaleza de Urfa (noviembre de 1599) y, proclamándose sultán con el título de «Halim Şah», envió firmanes con su propia tuğra. Considerado el primer jefe de la gran oleada celalí, Karayazıcı murió en 1602 y su movimiento fue continuado por su hermano Deli Hasan. La sublevación es el comienzo de la época de la «gran huida» (büyük kaçgunluk), en que el campesino de Anatolia abandonó en masa su tierra.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Defensa de Kanije por Tiryaki Hasan Paşa", "d56a5e6a"], "d": ["El archiduque Fernando y sus aliados, que querían recuperar Kanije, conquistada un año antes, sitiaron la fortaleza durante más de dos meses; Tiryaki Hasan Paşa resistió con sus 9000 hombres. Pese a no recibir ayuda del exterior, rechazó los asaltos generales y con salidas (huruç) obligó al enemigo a retirarse con graves pérdidas. La defensa se hizo épica en la historiografía otomana y el «Asedio de Kanije» se convirtió en un género literario en sí mismo.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Fallecimiento de Mehmed III y acceso al trono de Ahmed I", "da735fde"], "d": ["A la muerte de Mehmed III, el 20 de diciembre, subió al trono su hijo Ahmed I, de catorce años. El que fuera el primer sultán que se sentó en el trono siendo niño y sin haber salido a un sanjacado muestra que de hecho había terminado la costumbre de formar a los príncipes en las provincias. En el sultanato de Ahmed I se abandonaría el fratricidio y se pasaría al principio de «ekberiyet» (sucesión del miembro varón de más edad).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Recuperación de Esztergom", "7330f273"], "d": ["El gran visir Lala Mehmed Paşa sitió Esztergom, perdida diez años antes, y la incorporó de nuevo a la administración otomana. En la misma campaña fueron recuperadas también Pest y Vác, y los otomanos reorganizaron su línea en Hungría. Este éxito permitió sentarse a la mesa con relativa fuerza en Zsitvatorok al año siguiente; Esztergom permanecería en manos otomanas hasta 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Victoria de la llanura de Oruç y sofocación de la rebelión de Canbolatoğlu", "30f93532"], "d": ["Canbolatoğlu Ali Paşa, que había constituido un beylicato independiente en Alepo y buscaba una alianza con Toscana, fue gravemente derrotado en la llanura de Oruç por el gran visir Kuyucu Murad Paşa. Con el restablecimiento de la autoridad central en Siria se quebró la rama más peligrosa de la oleada celalí. La despiadada liquidación de Kuyucu Murad Paşa, que duró dos años, restableció el orden en Anatolia, aunque fuera de forma temporal.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Victoria de Alaçayır y sofocación de la rebelión de Kalenderoğlu", "55db0485"], "d": ["Kalenderoğlu, jefe celalí que sometía a tributo las regiones de Manisa y Bursa, fue derrotado en Alaçayır por Kuyucu Murad Paşa y tuvo que huir a Irán. Con esta victoria fue dispersado el último de los grandes ejércitos celalíes de Anatolia. La dura liquidación de Kuyucu Murad Paşa, que según se dice echaba a los rebeldes que mandaba matar en pozos que hacía cavar, aunque aseguró el orden a corto plazo, no pudo compensar la pérdida de población y producción de Anatolia.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Concesión de la primera ahidname a los Países Bajos", "5d9d117e"], "d": ["Cornelis Haga, enviado de la República de las Provincias Unidas, logró obtener de Ahmed I una ahidname con el mismo alcance que las concedidas a Francia e Inglaterra. Los Países Bajos ganaron así el derecho a abrir embajada en Estambul, consulados en los puertos otomanos y a comerciar bajo su propia bandera. Esta ahidname simboliza la entrada en el mercado otomano de las potencias marítimas del norte, que sustituyeron a Venecia en el comercio mediterráneo.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Muerte de Ahmed I y acceso al trono de Mustafa I — principio de ekberiyet", "9901c09e"], "d": ["Ahmed I, de veintiocho años, falleció tras una enfermedad de estómago de cincuenta y un días, y en lugar de su hijo fue puesto en el trono su hermano Mustafa I. Así, abandonado el orden de sucesión de padre a hijo, se pasó de hecho al sistema de «ekberiyet», en que sube al trono el miembro varón de más edad de la dinastía. Este primer sultanato, que duró noventa y seis días, es también el comienzo de la época en que los príncipes se criaban en el «kafes».", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Deposición de Mustafa I y acceso al trono de Osman el Joven (Osman II)", "e0f552f2"], "d": ["Mustafa I fue destronado al cabo de noventa y seis días por no estar en su sano juicio, y Osman II, hijo de catorce años de Ahmed I, se convirtió en sultán. Según la transmisión basada en Hasanbeyzâde, en la decisión de deponerlo influyó el jefe de los eunucos negros (Kızlar Ağası), Mustafa Ağa. Osman el Joven, con su proyecto de suprimir el cuerpo de jenízaros y crear un nuevo ejército, es considerado el primer nombre radical de los debates de reforma otomanos. Este proyecto le costaría la vida cuatro años después.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Tratado de Serav — renovación de la paz con Irán", "e778aca8"], "d": ["El Tratado de Serav, alcanzado con Irán tras el desastre de Pul-i Shikaste, confirmó en gran parte las condiciones del Tratado de Nasuh Paşa de 1612; la cantidad anual de seda que debían enviar los safávidas se redujo de doscientas cargas a cien. Así se cerró la segunda fase de las guerras orientales que duraban desde 1603. La paz no sería duradera: con la pérdida de Bagdad en 1623 la guerra se reavivaría.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Campaña de Hotin y Tratado de Hotin", "bc4c823c"], "d": ["El campamento fortificado que Chodkiewicz montó ante Hotin no pudo ser superado por el gran ejército que Osman II dirigía en persona, y tras meses de asaltos no se obtuvo resultado. Por el tratado firmado el 9 de octubre se reconoció el río Dniéster como frontera y los polacos se comprometieron a impedir las incursiones de los cosacos. La campaña, que pese a presentarse como victoria no dio resultado, reforzó la desconfianza del joven sultán hacia los jenízaros y su intención de liquidar el cuerpo.", "7d812c58"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Segunda deposición de Mustafa I y acceso al trono de Murad IV", "1b3a9e74"], "d": ["Mustafa I, que fue puesto por segunda vez en el trono tras el asesinato de Osman II, fue depuesto de nuevo al cabo de un año y tres meses, y Murad IV, de once años, fue proclamado sultán. Durante los primeros nueve años el Estado fue gobernado de hecho por su madre Kösem Sultan y los notables del palacio. Murad IV tomaría personalmente el gobierno a partir de 1632 e iniciaría una época de dura centralización.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Pérdida de Bagdad ante los safávidas", "db81be0c"], "d": ["Al término de las negociaciones que Bekir Subaşı, sublevado en Bagdad, mantuvo con los safávidas, su hijo Derviş Mehmed, que defendía la ciudadela, entregó la ciudad a las fuerzas del sah Abbas. La pérdida de una de las ciudades simbólicas de la herencia del califato y de la mayor parte de Irak provocó gran indignación en Estambul. Recuperar Bagdad sería durante quince años el único objetivo de la política oriental otomana.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Sofocación de la rebelión de Abaza Mehmed Paşa con centro en Erzurum", "e6da2729"], "d": ["Abaza Mehmed Paşa, beylerbeyi de Erzurum, que se sublevó contra los jenízaros con la pretensión de vengar el asesinato de Osman II, mantuvo durante años Anatolia oriental bajo su control y resistió al centro. Con el asedio de Erzurum por el gran visir Hüsrev Paşa tuvo que rendirse, fue perdonado y destinado a Bosnia. El fin de la rebelión fue condición previa para que Murad IV pudiera salir a campaña contra Irán.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Primera ejecución de un şeyhülislam: Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["El şeyhülislam Ahîzâde Hüseyin Efendi fue ejecutado cerca de Büyükçekmece, aduciéndose su mediación en el desorden militar y el haber enviado al sultán una advertencia escrita sobre el procedimiento judicial. Al ser el primer şeyhülislam otomano ejecutado, quebró la arraigada tradición de que el castigo más grave para los miembros del ilmiye era el destierro. El suceso se considera símbolo de la autoridad endurecida de Murad IV y de la ruptura del equilibrio entre Estado y ulema.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Conquista de Erevan por Murad IV", "b65a9b73"], "d": ["Murad IV, que partió de Estambul el 28 de marzo de 1635, sitió Erevan el 28-29 de julio y recibió la rendición de la fortaleza el 8 de agosto; a continuación entró en la desalojada Tabriz y mandó destruir la ciudad. El sultán hizo construir en el Palacio de Topkapı el Quiosco de Erevan en memoria de la victoria. Esta campaña fue la primera gran operación oriental, tras una interrupción de treinta años, en que el sultán dirigió personalmente el ejército.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Pérdida de Erevan ante los safávidas", "fbb8dd25"], "d": ["Tras la retirada del ejército otomano, las fuerzas del sah Safi sitiaron Erevan y la recuperaron en ocho meses. Lo rápido de la pérdida de la fortaleza mostró lo difícil que era logísticamente un dominio duradero en el Cáucaso. Erevan sería dejada también a Irán por el Tratado de Qasr-e Shirin de 1639 y los otomanos renunciarían a su pretensión sobre Azerbaiyán.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Reconquista de Bagdad", "4d2f27f3"], "d": ["Murad IV, que salió de Estambul el 8 de mayo de 1638, recuperó Bagdad, en manos safávidas desde hacía quince años, tras un violento asedio de cuarenta días; en el asedio cayó mártir el visir Tayyar Mehmed Paşa. Con la conquista de la ciudad se restableció la administración otomana en Irak y el sultán recibió el título de «Conquistador de Bagdad». La conquista, que se consolidó con el Tratado de Qasr-e Shirin del año siguiente, sentó las bases de la actual frontera entre Turquía e Irán.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Muerte de Murad IV y acceso al trono del sultán İbrahim", "e2ca1ca0"], "d": ["A la muerte de Murad IV, que falleció a los veintiocho años, subió al trono su hermano İbrahim, único miembro varón superviviente de la dinastía. En el sultanato del nuevo sultán, que había vivido años en el kafes, los gastos de palacio y las luchas de influencia dentro del palacio sacudieron el orden del Estado. Ocho años después, con su deposición y asesinato, se produciría el segundo regicidio de la historia otomana.", "4c336200"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Recuperación de la fortaleza de Azov a los cosacos", "e5fcf160"], "d": ["La fortaleza de Azov, que los cosacos del Don habían tomado en 1637, fue evacuada ante la operación conjunta de Sultanzâde Mehmed Paşa y el kan de Crimea Mehmed Giray IV; los cosacos se retiraron incendiando la fortaleza. La recuperación de la puerta norte del mar Negro cerró la peligrosa época en que las incursiones cosacas llegaron hasta el Bósforo de Estambul. La fortaleza sería perdida en 1696, esta vez ante el zar ruso Pedro I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Comienzo de la campaña de Creta y conquista de La Canea", "a1b0c77f"], "d": ["Con el pretexto de que corsarios de Malta habían atacado un navío otomano de peregrinos y se habían refugiado en Creta, se declaró la guerra a Venecia, y la flota al mando de Yûsuf Paşa desembarcó tropas en la isla. Tras un asedio de cincuenta y cuatro días fue tomada la fortaleza de La Canea y se estableció en Creta la primera base otomana duradera. Así comenzó la guerra más larga de la historia otomana; la isla sólo podría ser conquistada por completo veinticuatro años después, en 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Conquista de Rétimo — división de Creta en dos", "8f2c4353"], "d": ["Un año después de la toma de La Canea, cayó también la fortaleza de Rétimo, en la parte central de la isla, y la mitad occidental de Creta pasó íntegramente a la administración otomana. A Venecia solo le quedaron la capital, Candía, y el extremo oriental; la isla vivió veintitrés años dividida en dos. La toma de Rétimo fue el paso que inició el asedio de Candía — aquí comenzó el asedio más largo de la historia.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Pérdida de Klis ante Venecia", "5473c22c"], "d": ["En el frente de Dalmacia de la guerra de Creta (Candia), el contraataque del comandante veneciano Leonardo Foscolo alcanzó también Klis, centro del sanjacado desde 1537; la fortaleza pasó a Venecia. El que los otomanos concentraran toda su fuerza en Creta hizo imposible recuperar esta pérdida en la frontera de Dalmacia: Klis no volvería a la administración otomana; el centro del sanjacado fue trasladado a Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Comienzo del asedio de Candia", "13016b10"], "d": ["Tras la toma de La Canea y Rétimo, el ejército otomano puso bajo asedio a Candia, el último gran apoyo de Venecia en la isla. Este bloqueo, que duraría veintiún años, quedó registrado como uno de los asedios más largos de la historia militar mundial. Durante el asedio, los intentos de la flota veneciana de cerrar el estrecho de los Dardanelos trasladarían la guerra al corazón del Egeo.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Asesinato de la Gran Valide Kösem Sultan", "9d763f79"], "d": ["Kösem Sultan, de unos sesenta y dos años, fue hallada en una habitación del Harén y asesinada por Başlala Uzun Süleyman Ağa y sus hombres, que actuaban por orden de Turhan Sultan, madre de Mehmed IV. La muerte de esta poderosa mujer de la dinastía, que dirigió la política del Estado durante tres reinados, se considera el fin de hecho de la época llamada «Sultanato de las Mujeres». La autoridad vacante abrió el camino a que, cinco años después, Köprülü Mehmed Paşa llegara al gran visirato con poderes extraordinarios.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Desastre de los Dardanelos y pérdida de Bozcaada y Lemnos", "e01a1f7e"], "d": ["La gran victoria naval que el almirante veneciano Mocenigo obtuvo en junio de 1656 ante el estrecho de los Dardanelos aniquiló casi por completo a la flota otomana; a continuación fueron ocupadas Bozcaada, Lemnos y Samotracia. Con el bloqueo veneciano del estrecho se dispararon los precios de los alimentos en Estambul y se extendió el temor a un ataque a la capital. Este desastre fue la causa directa de que en septiembre de 1656 Köprülü Mehmed Paşa fuera llevado al gran visirato con condiciones y poderes extraordinarios.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Victoria de los Dardanelos y recuperación de Bozcaada", "603da863"], "d": ["La flota movilizada por Köprülü Mehmed Paşa derrotó el 19 de julio de 1657 a la flota veneciana ante el estrecho; a continuación las fuerzas al mando de Kurd Paşa recuperaron Bozcaada el 25 de agosto, y el 30 de agosto los venecianos evacuaron por completo la isla. En noviembre fue liberada también Lemnos, se rompió el bloqueo de los Dardanelos y se reabrió la ruta de abastecimiento de Estambul. Köprülü pasó personalmente a la isla y mandó reparar las fortificaciones; este éxito es la primera gran ganancia militar de la época de los Köprülü.", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["Recuperación de Lemnos a Venecia", "a4c3c69b"], "d": ["Lemnos, tomada por Venecia en julio de 1656, volvió a los otomanos en noviembre de 1657.", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Conquista de Yanova (Ineu) y campaña de Transilvania", "d1089616"], "d": ["Köprülü Mehmed Paşa, que salió a campaña para castigar al príncipe de Transilvania Jorge II Rákóczi —quien, emprendiendo sin permiso una campaña a Polonia, había violado la protección otomana—, marchó por Belgrado y tomó la estratégica fortaleza de Yanova. Se nombró un nuevo príncipe para Transilvania y se recordó con dureza el vínculo de vasallaje. Esta campaña fue el primer eslabón del intento otomano de restablecer su autoridad en Europa central. Transilvania ya era un principado vasallo de los otomanos; la toma de Yanova no fue una conquista a un Estado extranjero, sino sacar esta fortaleza de la administración del principado vasallo y vincularla directamente a un sanjacado otomano; el resto del principado quedó en estatuto de vasallo.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Sofocación de la rebelión de Abaza Hasan Paşa", "4ba74321"], "d": ["Abaza Hasan Paşa, que se apoyó en los beylerbeyis de Anatolia y los agás sekban contra las duras purgas de Köprülü Mehmed Paşa, inició una gran sublevación exigiendo la destitución del gran visir. La rebelión fue sofocada en Alepo y se eliminó a los cabecillas; fue la última resistencia colectiva de los pachás provinciales contra el centro. La autoridad de Köprülü quedó así indiscutida, y el cargo de gran visir volvió a elevarse a centro ejecutivo real del Estado.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Conquista de Várad (Oradea)", "0e6ad300"], "d": ["En el marco de la campaña organizada contra el príncipe de Transilvania Jorge II Rákóczi, que había declarado la guerra a los otomanos, fueron tomadas la fortaleza y la ciudad de Várad. Con la caída de una de las fortalezas clave de Transilvania se fundó en la región una nueva provincia otomana (Provincia de Varad). La conquista alarmó a los Habsburgo y fue una de las causas directas de la guerra otomano-austriaca que comenzaría tres años después. Otros lugares incorporados en la misma fecha: Varat. Tampoco aquí se tomó el territorio a un Estado extranjero: Transilvania ya era un principado vasallo otomano; la conversión de Várad en provincia sólo sacó la administración de esta ciudad al principado vasallo y la vinculó directamente al sultán, como dos años antes en Yanova.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Batalla de San Gotardo (St. Gotthard)", "61ebc1f2"], "d": ["Las fuerzas otomanas que cruzaron el río Raab fueron detenidas por el ejército europeo aliado al mando de Montecuccoli y sufrieron graves pérdidas. La batalla se considera un punto de inflexión en la historia militar por haber mostrado por primera vez con claridad la superioridad del fuego disciplinado de la infantería con fusil sobre la carga de la caballería otomana. Pese a la derrota, los otomanos lograron obtener condiciones ventajosas en el Tratado de Vasvár, firmado nueve días después.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Tratado de Vasvár", "089c978c"], "d": ["El tratado, firmado pese al desastre de San Gotardo, estableció que Uyvar (Érsekújvár) y Várad quedaran en manos otomanas, que Transilvania quedara neutral bajo protección otomana y que Austria pagara un «obsequio» de 200.000 kuruş. Esta paz de veinte años es uno de los raros ejemplos en que el bando que perdió la guerra ganó en la mesa. El descontento que el tratado provocó en la opinión pública de los Habsburgo alimentaría el movimiento de la Hungría central y, indirectamente, la campaña de Viena de 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Comienzo del régimen de los dayes en Argel", "e99faa51"], "d": ["La milicia (ocak) de Argel y la taife-i reîs (capitanes corsarios) depusieron al último agha y eligieron daye vitalicio a Hacı Mehmed. Desde entonces Argel fue gobernada no por un beylerbeyi nombrado por Estambul, sino por el daye que la propia milicia local elegía de entre sus filas; el vínculo otomano quedó limitado a la lectura del nombre del sultán en la jutba, al estandarte y a la obligación de campaña. Argel pasó así de eyalato a ocaklık; el mismo cambio lo vivieron Túnez en 1705 con los husseinitas y Trípoli de Berbería en 1711 con los karamanlíes.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Comienzo de la campaña de Polonia — Mehmed IV y Fâzıl Ahmed Paşa al frente del ejército", "75e15a39"], "d": ["Como los ataques de Polonia contra el hetman de Ucrania Petro Doroshenko, que había pasado a protección otomana, continuaban, Estambul pidió al rey polaco que desistiera de los ataques; al no llegar respuesta favorable, se decidió la campaña contra Polonia. El gran visir Fâzıl Ahmed Paşa partió hacia Polonia el 4 de junio de 1672 con el ejército en que se hallaba también el sultán. La campaña concluiría con la conquista de Kamieniec y el Tratado de Buczacz.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Conquista de Kamieniec y fundación de la Provincia de Podolia", "c3f4f6d0"], "d": ["Tras un asedio de nueve días fue recibida la rendición de Kamieniec, considerada la fortaleza más fuerte de Polonia en el este; Mehmed IV hizo el 2 de septiembre la primera oración de viernes en la mezquita convertida de la catedral. Con la fortaleza como centro se fundó la Provincia de Podolia, y la bandera otomana llegó a su punto más septentrional en territorio de la actual Ucrania. Kamieniec seguiría siendo el extremo noroccidental del imperio hasta el Tratado de Karlowitz de 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Paşa recibió Uman de Polonia", "0d3543a0"], "d": ["Kara Mustafa Paşa, enviado contra Polonia, recibió Uman, una de las fortalezas en poder de Polonia; la ciudad permaneció bajo administración otomana hasta Karlowitz.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Conquista de la fortaleza de Chyhyryn (Çehrin)", "a17cedd0"], "d": ["Tras la operación infructuosa de Melek İbrahim Paşa el año anterior, el gran visir Merzifonlu Kara Mustafa Paşa, al mando personal, sitió la fortificada Chyhyryn (19/21 de julio) y la tomó el 21 de agosto. La caída de la fortaleza, símbolo de la rivalidad otomano-rusa por el hetmanato cosaco de Ucrania, obligó a Rusia a la paz. Este éxito fue también una de las fuentes de la confianza de Merzifonlu para dirigirse hacia Viena.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Tratado de Bahçesaray — primera paz oficial con Rusia", "df82bc0b"], "d": ["Tras las campañas de Chyhyryn, al término de las conversaciones llevadas a cabo con la mediación del kan de Crimea, se firmó entre el Estado otomano y Rusia una paz de veinte años, reconociéndose como frontera el río Özü (Dniéper). Por ser el primer tratado de alcance general entre los dos Estados, se considera el documento inicial de las relaciones otomano-rusas. Gracias a la paz se aseguró el frente oriental y el ejército pudo ser dirigido a Europa central.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Concesión a Imre Thököly del berat de reino de la Hungría central", "3cd8d51d"], "d": ["El noble húngaro protestante Imre Thököly, que se sublevó contra la presión de los Habsburgo, empezó a ser considerado desde abril de 1682 «rey electo de la Hungría central», y el 16 de septiembre el beylerbeyi de Buda, İbrahim Paşa, le presentó las insignias principescas. Así se fundó bajo protección otomana un nuevo Estado húngaro vasallo. Esta intervención hizo inevitable la guerra con Austria e inició la cadena que conducía al Segundo Asedio de Viena del año siguiente.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Pérdida de Ayamavra (Léucade) ante Venecia", "e6905fee"], "d": ["La flota de Venecia, que se había unido a la Santa Liga, tras bombardear la ciudad ocupó la isla de Ayamavra, en el mar Jónico. Con la caída de Preveza ese mismo año quedó quebrado el control otomano en la boca del Adriático. Estas pérdidas fueron los pasos iniciales de la operación en que Morosini se apoderaría de toda la Morea en tres años.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Pérdida de Coron ante Venecia", "2ed762bc"], "d": ["Las fuerzas venecianas al mando de Morosini se apoderaron de la fortaleza de Coron, en el extremo suroccidental de la península de la Morea; la ciudad permanecería desde entonces treinta años bajo administración veneciana. La caída de Coron fue la primera gran ganancia de la operación veneciana dirigida a la conquista de la Morea. La fortaleza sólo pudo ser recuperada en 1715 por el ejército otomano al mando de Silâhdar Ali Paşa.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Recuperación de Atenas — retirada de Venecia", "03393b46"], "d": ["Morosini, que en septiembre de 1687 bombardeó la Acrópolis y voló el Partenón, comprendió, tras pasar el invierno en Atenas, que no podría sostenerse en la ciudad. Ante la epidemia de peste, las dificultades de abastecimiento y la recuperación de las fuerzas otomanas, la guarnición veneciana evacuó la ciudad y se retiró a la Morea. Atenas volvió así sin combate a la administración otomana, pero la destrucción sufrida por el Partenón no pudo revertirse.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) se rindió a Caraffa — pasó a manos de Austria", "7f0a8d38"], "d": ["Tras el asedio de tres días de Antonio Caraffa, Lipova se rindió entre el 12 y el 22 de junio de 1688 y pasó a manos de Austria. Los otomanos recuperaron después la ciudad, Austria la volvió a tomar en 1691; en la campaña de 1695 los otomanos restablecieron el control.", "9ddd4e2f"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Rechazo del asedio veneciano de Negroponte (Eğriboz)", "aae7e6a0"], "d": ["Morosini, que tras apoderarse de la Morea se volvió hacia el Egeo, intentó tomar Negroponte con un asedio de más de tres meses; pero ante las fortificaciones reforzadas en el invierno de 1687-1688 y la resistencia de la guarnición tuvo que retirarse con graves pérdidas. Este fracaso detuvo el avance veneciano en el Egeo y dañó el prestigio militar de Morosini. Negroponte seguiría también en manos otomanas en Karlowitz.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Pérdida de la fortaleza de Kanije ante Austria", "553b45f3"], "d": ["Kanije, estrechamente bloqueada desde enero de 1690 por un ejército habsburgo de 60.000 hombres, tras resistir meses sin recibir ayuda, se perdió por el acuerdo de rendición firmado por su último guardián, Mustafa Paşa. Así terminó en la fortaleza, recordada por la defensa épica de Tiryaki Hasan Paşa, un dominio otomano de noventa años. La pérdida de Kanije fue el derrumbe del último gran apoyo otomano en el oeste de Hungría.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Fallecimiento de Solimán II", "d2478080"], "d": ["Solimán II, que tras pasar unos cuarenta años en el kafes fue entronizado en 1687, murió en Edirne, enfermo, hacia el mediodía del viernes 22 de junio de 1691, mientras seguía los preparativos del ejército; su reinado duró tres años, ocho meses y dos días. El gran visir había dado de antemano las instrucciones necesarias para que, en caso de morir el sultán, su hermano Ahmed fuera entronizado. La oración fúnebre se hizo el mismo día en el Alay Köşkü; su cuerpo fue traído a Estambul y enterrado a la derecha de Solimán el Legislador, en su mausoleo.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Acceso al trono de Ahmed II", "52947b14"], "d": ["A la muerte de Süleyman II subió al trono en Adrianópolis su hermano Ahmed II, de cuarenta y nueve años. Su sultanato coincidió con los años más duros de las guerras de la Santa Liga; dos meses después de su acceso, en Slankamen, cayó mártir el gran visir Fâzıl Mustafa Paşa. En cambio, el sistema de malikâne puesto en práctica en su época fue una de las disposiciones más importantes que cambiaron la estructura a largo plazo de las finanzas otomanas.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Fallecimiento de Mehmed IV en Edirne", "17388b7e"], "d": ["Mehmed el Cazador, depuesto en 1687, fue llevado a Edirne durante la campaña húngara de 1689 de Solimán II y fue testigo también del reinado de su otro hermano, Ahmed II. Murió en esta ciudad que tanto amaba. Su cuerpo fue traído a Estambul y enterrado en el mausoleo de su madre Turhan Sultan, junto a Yenicami.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Fallecimiento de Ahmed II en Edirne", "c6306c08"], "d": ["Ahmed II, cuyo reinado de cuatro años transcurrió en guerra, murió en Edirne a los cincuenta y dos años de istiskā (hidropesía). Su cuerpo fue traído a Estambul y sepultado en el mausoleo de Solimán el Legislador. Le sucedió su sobrino Mustafa II.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Toma de Basora por los iraníes", "a9cdf3a3"], "d": ["Mientras el Estado otomano estaba ocupado en el oeste con las guerras de la Santa Alianza, Basora sufrió, tras la epidemia de peste de 1690, el saqueo primero del jeque muntafiq Mâni y después de Ferecullah, kan de Huveyze. Aprovechando esta confusión, los iraníes tomaron la ciudad en 1696 y dejaron en Basora una guarnición.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Tratado de Estambul — cesión de Azov a Rusia", "79db4724"], "d": ["En Karlowitz sólo había podido hacerse con Rusia un armisticio de dos años; la paz permanente se firmó en Estambul tras un año y medio de duras negociaciones. El Estado otomano cedió oficialmente a Rusia la fortaleza de Azov, perdida en 1696, y las tierras de su entorno, y renunció al tributo anual que el kan de Crimea recibía de Moscú. A cambio, Rusia obtuvo el derecho a tener un enviado permanente en Estambul; así la presencia rusa en la costa norte del mar Negro quedó registrada jurídicamente.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Recuperación de Kürne y Basora por Daltaban Mustafa Pasha", "7adb777d"], "d": ["Daltaban Mustafa Pasha, nombrado tras el Tratado de Karlowitz para el gobierno de Bagdad y el serasquierato de Basora, marchó hacia el sur con las fuerzas de Alepo, Raqqa, Sivas y Karaman y con una flota fluvial que descendió desde Birecik. Los jeques tribales de los alrededores se sometieron uno a uno, el comandante iraní de la guarnición de Basora, Davud Khan, abandonó la ciudad, y Kürne y Basora volvieron a entrar en la administración otomana.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Fallecimiento de Mustafa II", "626c394d"], "d": ["Mustafa II, que dejó el trono a su hermano Ahmed III con el Suceso de Edirne, murió unos cinco meses después de ser depuesto en Edirne, ciudad que tanto amaba. A su enfermedad se había sumado la aflicción por los últimos acontecimientos. Algunas fuentes occidentales escriben que entre el pueblo estaba extendida la opinión de que había sido envenenado.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Comienzo del gobierno mameluco (Kölemen) en Bagdad", "abe52618"], "d": ["Con el nombramiento de Hasan Paşa, de origen georgiano, para el gobierno de Bagdad, comenzó en Irak la época en que, en lugar de los gobernadores nombrados por el centro, dominó un grupo gobernante formado por sus propios esclavos. Con el gobierno de Süleyman Paşa en 1749 el sistema se asentó por completo y la Sublime Puerta tuvo que nombrar no a quien quería, sino a uno de los kölemen que se habían hecho con la influencia. Esta estructura semiautónoma, aunque resultó útil en la defensa de la frontera con Irán, debilitó durante siglo y medio el control de la autoridad central sobre Irak.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Fundación de la dinastía husseinita en Túnez", "cb1a98f9"], "d": ["En el vacío de autoridad surgido por la invasión de Túnez por las fuerzas de Argel, el agá de sipahis de origen turco Husayn b. Ali se hizo con el beylicato y adquirió legitimidad al comunicar su lealtad al sultán otomano. La dinastía que fundó gobernó Túnez entre 1705-1735 y 1756-1957; el régimen del ocak fue sustituido por un orden de beylicato transmitido de padre a hijo. Así nació el primer ejemplo de estructuras dinásticas vinculadas al centro pero de hecho autónomas en los ocaks de Occidente (Garp ocakları).", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Toma de Orán (Vahran) y Mazalquivir a los españoles", "b67ce06a"], "d": ["Las fuerzas del beylerbeyi del Ocak de Argel, tras un largo asedio, se apoderaron de Orán, que desde hacía dos siglos estaba en manos de una guarnición española, y de su puerto, Mazalquivir. Fue el mayor éxito de los ocaks de Occidente, bajo protección otomana, contra España en el Mediterráneo occidental, y aseguró el flanco occidental de Argel. La ciudad sufriría de nuevo la ocupación española en 1732, pero sería recuperada definitivamente en 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Tratado del Prut — recuperación de Azov y Taganrog", "bac5d2a1"], "d": ["El tratado de siete artículos, firmado con la rendición del ejército ruso cercado a orillas del Prut, estableció la devolución a los otomanos de la fortaleza de Azov con su territorio y municiones. Se arrasarían las fortificaciones de Taganrog, Kámenka y Yenikale, y las partes no construirían nuevas fortalezas en esas regiones. Se derrumbó el orden de flota y bases que Pedro I había creado durante dieciséis años en Vorónezh y Azov; la llegada de Rusia al mar Negro se retrasó unos cincuenta años.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Fundación de la dinastía Karamanlı en Trípoli de Berbería", "e1105d4a"], "d": ["En Trípoli de Berbería, agobiada por la disputa de los agás del ocak, el oficial de caballería Ahmed Karamanlı se hizo con el gobierno y oficializó su situación con el berat de beylerbeyi recibido de Estambul. Por obra de Ahmed Paşa, su hijo Mehmed Paşa y su nieto Yûsuf Paşa nació una dinastía que duró de 1711 a 1835; surgió una estructura semiindependiente que fundó su propia flota y firmó tratados directamente con los Estados europeos. Este período sólo terminaría en 1835 con la vinculación directa de la provincia al centro.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Tratado de Adrianópolis con Rusia", "14901a70"], "d": ["Tras declararse dos veces más la guerra por el incumplimiento de las promesas dadas en el Prut, se firmó finalmente en Edirne una paz permanente, al aceptar los rusos los compromisos. El tratado confirmó las condiciones del Prut; Rusia no se inmiscuiría en los asuntos de Polonia, se retiraría de las tierras cosacas y no impediría el regreso a su país del rey de Suecia Carlos XII, «el Cabeza de Hierro» (Demirbaş Şarl). El cierre del frente norte hizo posible que el Estado otomano volviera su rostro hacia los frentes de la Morea y de Venecia. Otros lugares incorporados en la misma fecha: Hotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Declaración de guerra a Venecia — preparación de la campaña de la Morea", "d970b122"], "d": ["En el Diván se tomó la decisión de guerra alegando que Venecia apoyaba a los rebeldes montenegrinos, confiscaba naves comerciales otomanas y oprimía con duros impuestos la Morea, que había recibido en Karlowitz. La campaña preparada por el gran visir Silâhdar Damad Ali Paşa concluiría al año siguiente con la recuperación de toda la península de la Morea en menos de cien días. Pero este éxito movilizaría a Austria y abriría la puerta, en 1716, a una guerra mucho más grave.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Tinos (İstendil): entrega de la última isla veneciana en el Egeo", "4abec891"], "d": ["La flota que salió para la campaña de la Morea fondeó, en su camino, ante Tinos (İstendil), la única isla que le quedaba a Venecia en el Egeo. Aunque el Ducado de Naxos había caído en 1566, la isla, que gracias a su población latina había llevado bandera veneciana ciento cincuenta años más, se rindió sin derramamiento de sangre tras un breve asedio. Así se borró la última huella de Venecia en el mar Egeo y este se convirtió por completo en un mar interior otomano.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Conquista de Nauplia — fortaleza clave de la Morea", "62a5808a"], "d": ["Nauplia (Anabolu), capital de Venecia en la Morea y su fortificación más fuerte, cayó cuando el baluarte de Palamidi fue tomado tras nueve días de bombardeo. La rapidez con que fue tomada la fortaleza quebró la resistencia en el resto de la península. Aquí se completó de hecho la recuperación de la Morea, perdida en Karlowitz.", "9b883577"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Rendición de Modon", "43faa909"], "d": ["Tras la caída de Nauplia, la fortaleza de Modon, en el extremo suroccidental de la Morea, fue sitiada por el ejército por tierra y por la flota por mar, y se rindió en poco tiempo. Este puerto, utilizado durante doscientos años en las campañas de Venecia en el Mediterráneo oriental, era el punto de escala obligado donde los barcos tomaban agua y víveres. Su pérdida puso fin a la capacidad de movimiento de la flota veneciana en el Egeo.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Rendición de Coron — conclusión de la campaña de la Morea", "e4b9c8a4"], "d": ["Con la rendición de la fortaleza de Coron, que guarda la entrada del golfo de Mesenia, la administración veneciana terminó por completo en la península de la Morea. La península, perdida en Karlowitz, fue recuperada íntegramente solo tres meses después de iniciarse la campaña. Como continuación de la misma campaña, en septiembre de 1715 fue tomada también a Venecia la isla de Santa Maura (Lefkada), en el mar Jónico. Esta rapidez forzó a Venecia a hacer entrar a Austria en la guerra y abrió, tres años después, el camino a Passarowitz.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Toma de la isla de Citera (Çuha Adası / Kythira)", "494de6c6"], "d": ["La isla de Citera (Çuha Adası), en el extremo meridional de la Morea, fue recibida por la flota tras completarse la península. La isla, que vigila el paso entre el mar Jónico y el Egeo, era el puesto avanzado que Venecia utilizaba para controlar esas aguas. Sin embargo, no permaneció como única isla conservada por los otomanos: tres años después fue devuelta a Venecia en Passarowitz.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Austria y Venecia constituyeron una alianza — la puerta de la guerra otomano-austriaca de 1716-1718", "99511ca2"], "d": ["Tras la recuperación de la Morea a Venecia por los otomanos, Austria firmó un tratado de alianza con Venecia alegando que se había violado el Tratado de Karlowitz; el príncipe Eugenio, en una carta al gran visir, pidió la devolución de los lugares tomados a Venecia. En la consulta celebrada en el campamento de Davutpaşa, por la presión del gran visir Ali Paşa, se declaró la guerra a Austria y para ello se obtuvo una fetva del şeyhülislam.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["El gran visir Ali Paşa salió a la campaña de Austria", "2fbdce42"], "d": ["Tras la declaración de guerra a Austria, el serdar-ı ekrem Ali Paşa salió a la campaña de Austria con un ejército de más de 100.000 hombres; la flota, en cambio, se dirigió ese mismo verano a Corfú. El ejército marcharía desde Belgrado sobre Petrovaradin, y en el desastre de comienzos de agosto el gran visir caería mártir.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Desastre de Petrovaradin (Varadin) — martirio de Damad Ali Paşa", "265c1d81"], "d": ["El ejército otomano, que cruzó el Danubio por Belgrado, se encontró ante Petrovaradin con las fuerzas austriacas al mando del príncipe Eugenio; aunque en el primer ímpetu la carga de los jenízaros forzó las trincheras enemigas, las filas se rompieron con el derrumbe del ala de caballería. El gran visir Silâhdar Damad Ali Paşa cayó mártir de un disparo en la frente, y el campamento y el tren de artillería cayeron por completo en manos del enemigo. Este desastre, que las crónicas otomanas recuerdan como el «año de Varadin», fue el primer eslabón de la cadena que conducía a la pérdida de Timișoara y, al año siguiente, de Belgrado.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Fracaso del Asedio de Corfú", "b2aa7011"], "d": ["El serasker de la Morea Kara Mustafa Paşa por tierra y el kapudán pachá Canım Hoca Mehmed Paşa con la flota por mar atacaron Corfú; la isla era la base clave de Venecia en el Adriático. Pero la extraordinaria fortificación de la fortaleza, los refuerzos traídos por la flota veneciana y las noticias del desastre en el frente del Danubio llevaron al levantamiento del asedio. El no haber tomado Corfú apagó el ánimo creado por la reconquista de la Morea y desplazó el centro de gravedad de la guerra a Hungría.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Pérdida de Timișoara (Temeşvar) ante Austria", "27fe1365"], "d": ["Tras el desastre de Petrovaradin, el príncipe Eugenio marchó directamente sobre Timișoara, y la fortaleza se entregó mediante capitulación (vire) al término de un asedio de más de cuarenta días. La ciudad, conquistada en 1552 en tiempos del Legislador y que durante 164 años, como centro de beylerbeyilik, se consideró el pilar oriental de la defensa de Hungría, se perdió así. Con la caída de Timișoara toda la región del Banato pasó a Austria y la frontera otomana fue empujada al sur del Danubio.", "3f3368fd"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Rendición de la fortaleza de Haram (Yeni Palanka) a Austria — perdida la orilla del Danubio del Banato", "38ee4c6d"], "d": ["Mercy, general de caballería austriaco encargado de tomar el resto del Banato tras la caída de Timișoara, marchó el 14 de noviembre sobre Haram (Yeni Palanka), a orillas del Danubio; cuando llegó a la fortaleza el 16 de noviembre, la guarnición otomana de 200 hombres se rindió izando bandera blanca con la condición de retirarse libremente. Así también la línea del Danubio del Banato meridional, en manos otomanas desde 1552, pasó a Austria.", "8026e3e4"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Tratado de Passarowitz — la Morea ganada, Belgrado y el Banato perdidos", "d46aa216"], "d": ["La Morea había sido recuperada a Venecia, pero Austria, que entró en la guerra, se impuso en la mesa con las victorias que logró en Petrovaradin y Belgrado. El tratado firmado con la mediación de Inglaterra y los Países Bajos dejó la Morea en poder del Imperio otomano, a cambio de lo cual fueron cedidos a Austria, junto con Belgrado, el norte de Serbia, el Banato y la Pequeña Valaquia; en palabras del TDV, «la Bosnia septentrional fue dejada por completo a Austria» — fortalezas como Dubica de Bosnia y Bosanski Brod, a lo largo del Sava, pasan a Austria en el mapa desde este día (la frontera exacta la trazaron uno a uno los comisarios; el TDV no cita estas fortalezas por su nombre); Venecia, por su parte, conservó posiciones en la costa jónica como Préveza y Citera. Con el comercio (ahidnâme) firmado el mismo día, el derecho de aduana cobrado a las mercancías austríacas fue reducido del cinco al tres por ciento. El tratado, al registrar la retirada del Estado otomano en Europa central, sentó, con la paz de veintisiete años que abrió, el terreno de la Época de los Tulipanes (Lâle Devri, 1718-1730): la primera imprenta otomana (1727, İbrahim Müteferrika), los comités de traducción, las observaciones sobre la vacuna de la viruela y una nueva vida de palacio y de cultura son producto de estos años de paz bajo el gobierno de Nevşehirli Damad İbrahim Pasha.", "3a9f1433"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Campaña oriental: toma de Tiflis y comienzo de la guerra con Irán", "78343dc2"], "d": ["Con el derrumbe del Estado safávida por la invasión afgana y el descenso de Rusia a las costas del Caspio, el Estado otomano envió un ejército hacia el este para que el vacío no quedara por completo en manos de la influencia rusa. Con la toma de Tiflis, Georgia se vinculó a la administración otomana; a continuación continuó el avance hacia Ganyá, Erevan y Najicheván. Esta campaña, llevada a cabo tras la apariencia pacífica de la Época de los Tulipanes, fue el comienzo de una larga aventura oriental que duraría trece años y terminaría con la devolución de todos los lugares ganados.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Campaña de Irán de 1723: entrada en Shirvan y Georgia", "c81189fc"], "d": ["Al derrumbarse el Estado safávida por la invasión afgana, se abrió una campaña hacia el este con el pretexto de impedir que Rusia descendiera a las costas del Caspio. El ejército de Erzurum entró por Georgia en Tiflis, y la columna de Shirvan en Shamakhi, recuperando territorios perdidos ciento treinta años antes. Esta campaña fue el último gran avance otomano en el Cáucaso.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Toma de Kermanshah — la puerta de los Zagros", "ad14799f"], "d": ["El ejército de Bagdad atravesó los pasos de los Zagros y tomó Kermanshah, considerada la puerta occidental de Irán. La ciudad estaba en el camino de las caravanas y los ejércitos que va de Bagdad a Isfahán, y su toma aseguraba la seguridad oriental de la provincia de Irak. Este avance inició, en el país safávida en disolución, la carrera de reparto entre el Imperio otomano y Rusia.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Mukāsemenâme de Estambul — reparto de Irán con Rusia", "fce8eec2"], "d": ["Para evitar que el Imperio otomano y Rusia se enfrentaran por el hundido territorio safávida, se firmó un tratado de reparto con la mediación del embajador francés. Las costas occidental y meridional del mar Caspio quedaron para Rusia; Georgia, Shirvan, Azerbaiyán y las ciudades del Irán occidental, para el Estado otomano. Este reparto, que sobre el papel parecía una gran ganancia, pronto quedaría anulado de hecho con el ascenso de Nader Shah. Según el tratado, las fértiles tierras de Shirvan, como Shabrán y Mushkur, quedaron del lado ruso (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Toma de Najicheván", "bdf14d0a"], "d": ["Las fuerzas otomanas, avanzando a lo largo del Araxes, tomaron Najicheván y Ordubad; Culfa fue también incorporada al livá de Najicheván. La ciudad, puerta noroccidental de Irán, quedó adscrita a la recién creada provincia de Revan. Así, la frontera otomana volvió a alcanzar su línea más oriental de la época de Solimán el Legislador.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Conquista de Hamadán", "e1339a97"], "d": ["El ejército que marchó hacia el este desde Kermanshah tomó, tras un largo asedio, Hamadán, en el umbral occidental de la meseta de Irán. La ciudad era la última gran etapa del camino de Isfahán, el punto más oriental que los ejércitos otomanos habían podido alcanzar desde la Campaña de los Dos Irak. La Convención de Estambul firmada ese mismo año con Rusia puso por escrito el reparto del Irán en disolución entre el Imperio otomano y Rusia.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Reconquista de Revan", "88acabef"], "d": ["Tras un duro asedio de noventa días, Revan, la fortaleza clave del valle del Araxes, volvió a la administración otomana. La fortaleza, construida en 1583 y perdida en 1604, fue reforzada esta vez con una guarnición más fuerte. La duración del asedio mostraba que el ejército otomano ya no avanzaba con facilidad. Las nahiyes de Karpi (Üçkilise), Şerür, Makû y Şüregel fueron también anexadas a la provincia de Revan.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Toma de Tabriz — conquista de Azerbaiyán", "e502a4f7"], "d": ["Tabriz, sitiada de nuevo tras el intento fallido del año anterior, se rindió al ejército otomano después de un duro combate librado calle por calle. Merend, Maraga y Sovukbulak (Mahabad), dependientes de la provincia de Tabriz, pasaron también a la administración otomana. Ese mismo año fueron tomadas además Lori, Ganye, Ardabil y Hurremabad, de modo que las regiones que correspondían al Imperio otomano en virtud del Acuerdo de Estambul quedaron ocupadas de hecho. Esta extensión alcanzada en el este fue la frontera más avanzada desde la época del Tratado de Ferhad Pasha, pero mantenerla supuso una pesada carga para el ejército y el tesoro.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Conquista de Gence — fin de la campaña del Cáucaso", "875bca7a"], "d": ["Gence, último objetivo de las operaciones en el Cáucaso, fue entregada como centro del Karabaj, entre el Kura y el Araxes. Con la culminación de la línea de Shirván, Revan, Najicheván y Gence, el Estado otomano alcanzó en el Cáucaso la extensión que tenía en 1590. Sin embargo, esta ganancia fue efímera: el ascenso de Nader Shah recuperaría toda la región en diez años.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Tratado de Hamadán — incorporación del oeste de Irán al Imperio otomano", "94a29dc3"], "d": ["Con el tratado firmado con el gobernante afgano Ashraf Shah terminó una guerra de cuatro años y se reconocieron jurídicamente los territorios del oeste de Irán ocupados por el Estado otomano. A cambio, Ashraf Shah aceptó el califato del sultán otomano y se comprometió a que la jutba se leyera en Irán en nombre del sultán. Esta victoria diplomática tuvo corta vida: la contraofensiva iniciada por Nader Shah en 1730 borraría en pocos años lo ganado con el tratado.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Pachá tomó Urmía (Rumiye)", "eac7f64d"], "d": ["En la campaña de Irán, Hekimoğlu Ali Pachá tomó primero Urmía (Rumiye) y después Tabriz, evacuada a los otomanos, el 15 de noviembre de 1731. El TDV no da el día de la toma de Urmía; solo se sabe el año y que fue anterior a Tabriz.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Tratado de Ahmed Pasha — devolución de gran parte del oeste de Irán", "590d839f"], "d": ["Tras la victoria de Nader Shah en Malayir y sus sucesivas ofensivas, el gobernador de Bagdad, Ahmed Pasha, firmó un texto de paz sin consultar al centro. Según el tratado se aceptó el río Aras como frontera; ciudades del oeste de Irán como Hamadán, Kermanshah, Ardalán, Ardabil y Tabriz fueron devueltas a Irán, mientras que Ganye y Tiflis permanecieron en poder otomano. Este texto, recibido con indignación en Estambul, fue considerado insuficiente también por Nader Shah, y la guerra se reavivó antes de que terminara el año 1732.", "b7cf810a"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Nueva pérdida de Orán (Vahran) a manos de España", "20485027"], "d": ["La gran flota de desembarco enviada por el rey de España Felipe V llegó ante Orán al mando del conde de Montemar, derrotó a las fuerzas del Odjak de Argel y recuperó la ciudad. El puerto, conquistado veinticuatro años antes, permanecería sesenta años más en manos de una guarnición española. Esta pérdida, que mostró los límites del poder de los odjaks occidentales (Garp) en el Mediterráneo occidental, solo pudo compensarse con la conquista definitiva de Orán en 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Reforma del cuerpo de humbaracı al estilo europeo y fundación del Humbarahâne", "d980cf2a"], "d": ["Humbaracı Ahmed Pasha, de origen francés, que había entrado al servicio otomano, convirtió con el apoyo del gran visir Hekimoğlu Ali Pasha el cuerpo de humbaracı (bombarderos) en una unidad asalariada y organizada al estilo europeo. A trescientos soldados reclutados en Bosnia se les dio instrucción regular basada en el cálculo y la geometría; se prepararon nuevos reglamentos de organización, equipamiento y jubilación, y con técnica moderna se fabricaron cien morteros de bombas y cincuenta mil bombas. El Humbarahâne, donde se enseñaba geometría, se considera el primer núcleo de la enseñanza moderna de ingeniería militar en el Imperio otomano.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Fallecimiento de Ahmed III", "455f7fba"], "d": ["Ahmed III, depuesto en 1730 por la rebelión de Patrona Halil, pasó los últimos seis años de su vida en el apartamento del Palacio de Topkapı reservado a los sultanes depuestos y murió a los sesenta y tres años. Fue sepultado en Bahçekapı, en el mausoleo de su abuela Turhan Sultan, junto a Yenicami.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Tratado de Estambul — cesión del Cáucaso meridional a Irán", "8c205aab"], "d": ["La segunda guerra con Irán, que duró cuatro años, terminó con el tratado firmado tras la derrota de Arpaçay y la pérdida de Ganye y Tiflis. El Estado otomano se retiró de todos los territorios del Cáucaso meridional y del oeste de Irán que había obtenido desde 1723, y la frontera volvió a la línea de Qasr-i Shirin de 1639. De las campañas orientales de trece años quedaron una pesada carga financiera y un tesoro vaciado; en cambio, el cierre del frente oriental fue una ganancia vital para la nueva guerra que comenzaba con Rusia.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Caída de la fortaleza de Özi (Očakov) en manos de los rusos", "f93e61f3"], "d": ["El ejército ruso al mando del mariscal Münnich sitió la fortaleza de Özi, en la desembocadura del Dniéper; con la explosión del polvorín la defensa se derrumbó y la fortaleza cayó con enormes pérdidas humanas. La pérdida de Özi, considerada la llave de la costa noroccidental del mar Negro, abrió a los rusos el camino de Crimea y provocó un gran pánico en Estambul. Al año siguiente los rusos evacuarían la fortaleza a causa de la epidemia y las dificultades de abastecimiento, y esta volvería a manos otomanas.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Victoria de Banaluka — liberación de Bosnia", "f603865a"], "d": ["Cuando las fuerzas austríacas entraron en Bosnia y sitiaron Banaluka, el gobernador de Bosnia, Hekimoğlu Ali Pasha, acudió en auxilio con las fuerzas reunidas entre la población local e infligió una dura derrota al enemigo, superior en número. Esta victoria hizo fracasar desde el primer movimiento el plan austríaco de ocupar Bosnia, y el norte de la provincia fue recuperado por completo. Banaluka fue uno de los puntos de inflexión que levantaron la moral del ejército otomano, que desde 1683 retrocedía continuamente ante Austria.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Victoria de Hisarcık (Grocka) — apertura del camino de Belgrado", "2101cdff"], "d": ["El ejército austríaco, que avanzaba para proteger Belgrado, cayó en una emboscada en un estrecho desfiladero a orillas del Danubio y sufrió graves pérdidas en un combate que duró todo el día. Mientras las fuerzas del mariscal Wallis se replegaban desordenadamente hacia Belgrado, el ejército otomano llegó hasta la fortaleza e inició el asedio. Hisarcık fue la victoria en campo abierto más decisiva lograda ante Austria desde Karlowitz y condujo directamente a la recuperación de Belgrado.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Tratado de Niš — paz con Rusia, neutralización de Azov y fin de las incursiones de Crimea", "674f974e"], "d": ["Rusia, que quedó sola cuando Austria aceptó la paz en Belgrado, se vio obligada a poner fin a la guerra con la mediación del embajador francés Villeneuve. Se demolieron las fortificaciones de la fortaleza de Azov y la región fue declarada territorio neutral entre los dos Estados; Rusia aceptó la condición de no mantener buques de guerra ni de comercio en el mar Negro. Así, el objetivo ruso de salir al mar se aplazó una generación más, y el Estado otomano se levantó de la mesa con ganancias por última vez en el siglo XVIII.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Özi vuelve de la ocupación rusa: entregada tras la demolición de la fortaleza por la paz de 1739", "7ecc2bef"], "d": ["Los rusos habían tomado Özi el 11 de julio de 1737. En virtud de la paz acordada con Rusia en 1739, tras la demolición de las fortificaciones de la fortaleza esta fue entregada de nuevo a los otomanos; el Imperio otomano conservó Özi hasta 1788, antes del Tratado de Iași.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Defensa de Mosul — rechazo de Nader Shah", "c03ffbc1"], "d": ["Nader Shah, que había tomado Kirkuk y Erbil y llegado ante Mosul, bombardeó la ciudad durante cuarenta días y lanzó asaltos generales sucesivos. La defensa dirigida por el gobernador Hüseyin Pasha al-Jalili, que armó también a la población de la ciudad, obligó al ejército iraní a levantar el asedio con graves pérdidas. La resistencia de Mosul evitó la pérdida de todo Irak y consolidó durante un siglo la influencia de la familia Jalili en la ciudad.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Alianza de Dir'iyya — fundación del primer emirato saudí en Néyed", "188751bf"], "d": ["El emir Muhammad ibn Saud, que acogió bajo su protección en Dir'iyya al sabio Muhammad ibn Abd al-Wahhab, expulsado de Uyayna, selló con él una alianza que ponía la autoridad política al servicio de la predicación religiosa. Este pacto inició una nueva historia para la familia Saud y reunió en torno a un solo movimiento los dispersos emiratos de oasis de Néyed. Este poder, que en medio siglo se extendería hasta Kerbala, La Meca y Medina, obligaría al Estado otomano a defender su soberanía en el Hiyaz.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Tratado de Kerden — fin de las guerras otomano-iraníes", "1d3a919e"], "d": ["Con el tratado firmado tras la última guerra, que duró cuatro años, se renovó sin cambios la frontera de Qasr-i Shirin de 1639; ninguna de las dos partes obtuvo ganancias territoriales. La insistente petición de Nader Shah de que el yafarismo fuera reconocido como quinta escuela jurídica quedó sin respuesta; en cambio, se acordó que los peregrinos iraníes pudieran hacer la peregrinación libremente y que se intercambiaran embajadores. Así concluyeron de hecho las guerras otomano-iraníes, que habían durado más de dos siglos; esta frontera se ha conservado en gran medida hasta hoy.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Muerte de Mahmud I y ascenso al trono de Osman III", "30203700"], "d": ["Mahmud I, que durante su reinado de veinticuatro años recuperó los territorios perdidos por el Tratado de Belgrado y apoyó la reforma del cuerpo de humbaracı, falleció al regresar de la ceremonia de saludo del viernes. Le sucedió su hermano Osman III, que había vivido en el «kafes» hasta los cincuenta y ocho años. Comenzó un reinado breve e inquieto; durante el de Osman III, que cambió seis grandes visires en tres años, reinó un marcado estancamiento en los asuntos del Estado.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Muerte de Osman III y ascenso al trono de Mustafa III", "3ac10f85"], "d": ["Tras la muerte de Osman III, después de un reinado de tres años, subió al trono Mustafa III, abierto a las ideas de reforma e interesado de cerca en los asuntos del Estado. El nuevo sultán, apoyándose en la experiencia del gran visir Koca Ragıp Pasha, trató de sanear la hacienda y renovar el ejército; en este período se crearon los artilleros de tiro rápido del barón de Tott. Sin embargo, la guerra con Rusia en la que se entró en 1768 eclipsaría todos los logros de un reinado de diecisiete años.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Declaración de guerra a Rusia — incidente de Balta y comienzo de la guerra de 1768-1774", "9c6aabe0"], "d": ["Cuando las tropas rusas y cosacas que perseguían a la Confederación de Bar en Polonia asaltaron e incendiaron la localidad otomana fronteriza de Balta, el Diván decidió la guerra y el embajador ruso fue encarcelado en Yedikule. La guerra, a la que se entró sin una preparación militar seria y tras haber sido declarada con seis meses de antelación, comenzó mal desde el principio. Esta lucha, que duraría seis años, se convertiría, con el ataque de Çeşme, el desastre de Kartal y la ocupación de Crimea, en una de las series de derrotas más graves de la historia otomana.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Pérdida de la fortaleza de Hotin a manos de los rusos", "66d43ea4"], "d": ["Tras haber rechazado dos intentos del ejército ruso al mando del príncipe Golitsyn, el ejército se retiró por la derrota que sufrió el gran visir entre Kamenets y Hotin, y los guardias evacuaron la fortaleza. La pérdida sin resistencia de la fortificación otomana más fuerte al norte del Danubio abrió a los rusos las puertas de Valaquia y Moldavia. Ambos principados fueron ocupados ese mismo año; Hotin solo pudo recuperarse en 1774 por el Tratado de Küçük Kaynarca.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Desastre de la llanura de Kartal (Kagul)", "6f408eaf"], "d": ["Tres semanas después del incendio de la flota en Çeşme, el principal ejército otomano a orillas del Danubio se dispersó en la llanura de Kartal ante las tropas, mucho menos numerosas pero disciplinadas, del mariscal Rumyantsev. El campamento, los bagajes y cientos de cañones cayeron en manos del enemigo; las tropas que huían sufrieron grandes pérdidas al cruzar el Danubio. La destrucción, en un mismo verano, tanto de la flota como del ejército de tierra condujo a la caída sucesiva de Kili, Akkerman, Ismail y Bender y a la ocupación de Crimea.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Ocupación rusa de la península de Crimea", "217837b0"], "d": ["Los ejércitos rusos, que un año antes habían tomado Budjak, atravesaron Or Kapı al mando del príncipe Dolgorukov e invadieron toda la península de Crimea. El kan fue depuesto y se instaló en el trono a Sahib Giray, favorable a Rusia, dando así el primer paso para separar el kanato del Imperio otomano. La pérdida de Crimea, escudo septentrional del Imperio otomano durante tres siglos, fue el comienzo del proceso que llevaría a su independencia en 1774 y a su anexión directa en 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Muerte de Mustafa III y ascenso al trono de Abdülhamid I", "42cba8e2"], "d": ["En lugar de Mustafa III, fallecido en el momento más angustioso de la guerra rusa, subió al trono, a los cuarenta y nueve años, su hermano Abdülhamid I, que había pasado cuarenta y tres años en el «kafes» del palacio. El nuevo sultán, que heredó uno de los períodos más difíciles del Estado, tuvo que afrontar las duras condiciones del Tratado de Küçük Kaynarca, que se firmaría ese mismo año. Su reinado de quince años transcurriría entre la pérdida de Crimea y una nueva guerra rusa, y terminaría en 1789 con la apoplejía que sufrió al leer la noticia de la caída de Özi.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Desastre de Kozluca — la derrota que condujo a Küçük Kaynarca", "8e0542f9"], "d": ["Las fuerzas otomanas reunidas ante Shumen fueron derrotadas en Kozluca por las columnas unidas de Suvórov y Kamenski, y la mayor parte del ejército se dispersó. Con este desastre no quedó fuerza alguna capaz de resistir en los Balcanes; las vanguardias rusas sitiaron Shumen y el cuartel general del gran visir quedó amenazado. El hecho de que, antes de que pasara un mes, se acudiera a sentarse a la mesa en Küçük Kaynarca y se aceptaran condiciones extraordinariamente duras es consecuencia directa de esta derrota.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Cesión de Bucovina (norte de Moldavia) a Austria", "190f9caa"], "d": ["Aprovechando la debilidad provocada por Küçük Kaynarca, Austria reclamó Bucovina, la región que une Moldavia y Transilvania, y obtuvo ese territorio sin entrar en guerra, mediante amenazas y sobornos. La pérdida de esta región fértil y estratégica al suroeste de Hotin dividió de hecho en dos el voivodato de Moldavia. Esta cesión, realizada sin disparar un solo tiro, se consideró una de las señales más claras de que el Estado otomano había perdido su capacidad de disuasión. Con la cesión de Bucovina en 1775, Suceava y Czernowitz pasaron a Austria (día sin confirmar).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Ocupación iraní de Basora", "0161e709"], "d": ["Sadiq Khan, hermano del gobernante zand Karim Khan, tomó Basora tras un asedio de un año, y el Estado otomano perdió el puerto más importante del golfo de Basora. La ocupación golpeó directamente la ruta comercial de la India, los ingresos de los dátiles y las perlas y la defensa meridional de Irak. La ciudad solo pudo recuperarse en 1779, durante las luchas por el trono surgidas en Irán con la muerte de Karim Khan.", "838306ba"]},
"OLAYLAR_EK5:1779-03-10:0":{"b": ["Convención de Aynalıkavak — acuerdo provisional sobre Crimea", "9b3b0468"], "d": ["Los dos Estados, que habían llegado al borde de la guerra por quién ocuparía el kanato de Crimea, firmaron en el palacio de Aynalıkavak, con la mediación de Francia, un texto aclaratorio. Rusia aceptó retirar sus tropas de Crimea y el Estado otomano reconocer el kanato de Şahin Giray, favorable a Rusia; se confirmó el derecho de califato religioso del sultán sobre Crimea. Este frágil equilibrio, que duraría cuatro años, se derrumbaría por completo en 1783 con la anexión directa de la península por Rusia.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Construcción de la fortaleza de Anapa — línea defensiva del Cáucaso", "be92a80f"], "d": ["Al perderse Crimea tras Küçük Kaynarca, se emprendió la construcción de una nueva fortaleza en la desembocadura del río Kubán para preservar la influencia otomana en el Cáucaso. Anapa, levantada sobre los restos de una colonia genovesa, se convirtió en poco tiempo, con su bazar, sus baños y sus más de doscientos cincuenta comercios, en una ciudad que aseguraba el contacto con las tribus circasianas. La fortaleza siguió siendo, durante cuarenta y ocho años, el puesto más avanzado otomano frente al descenso de Rusia hacia el Cáucaso.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Destitución y ejecución del gran visir Halil Hamîd Pachá", "c44001ca"], "d": ["El gran visir reformista Halil Hamîd Pachá, de cuyos servicios Abdülhamid I había mostrado satisfacción en diversas ocasiones, fue destituido de improviso hacia la mañana del 31 de marzo de 1785 y desterrado a Gallípoli, y todos sus bienes fueron confiscados. Se le dieron primero la provincia de Abisinia, el sanjacado de Yeda y el cargo de shaij del Haram de La Meca; pasaba abril de 1785 en Ténedos preparando el viaje cuando fue destituido también de ese gobierno, y, al llegar el firmán de ejecución, fue muerto por Karakethüdâzâde Ali, hombre de Cezayirli Gazi Hasan Pachá. Su cabeza cortada fue enviada a Estambul y expuesta en Ortakapı. Según el TDV, aunque esta caída repentina se interpretó como acusación de un complot para destronar al sultán y poner en su lugar al príncipe Selim, las causas reales habrían sido probablemente la indignación por su silencio ante la anexión de Crimea, la hostilidad de los círculos perjudicados por sus reformas y la oposición de Gazi Hasan Pachá.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Declaración de guerra a Rusia — comienza la guerra otomano-rusa de 1787-1792", "3bfb870c"], "d": ["Ante el ostentoso viaje de Catalina II a Crimea y su toma de Georgia bajo su protección, el Diván decidió la guerra con el fin de revertir la anexión, y el embajador ruso fue encerrado de nuevo en Yedikule. Sin embargo, el ejército no estaba preparado, el tesoro estaba vacío y la búsqueda de aliados había resultado infructuosa. La guerra, que duraría cinco años, terminaría con la caída de Özi entre matanzas, la pérdida de Ismail y las duras condiciones del Tratado de Iași.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Entrada de Austria en la guerra — lucha en dos frentes", "ae912290"], "d": ["En virtud de la alianza secreta que había concertado con Rusia en 1781, el emperador austríaco José II declaró la guerra al Estado otomano y avanzó en dirección a Belgrado y Bosnia. El ejército otomano se vio obligado a combatir de golpe en dos frentes: Rusia al norte y Austria al oeste. A pesar de las victorias logradas sobre los austríacos en Lazarethane, Mehadia y Şebeş, el frente occidental también se derrumbaría en 1789 con la pérdida de Belgrado.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Alianza otomano-prusiana", "03b88e51"], "d": ["Selim III, que buscó aliados en Europa nada más subir al trono, firmó con Prusia un tratado de alianza que preveía la ayuda mutua; Prusia se comprometió a declarar la guerra a Rusia y Austria, y el Estado otomano a no hacer la paz sin recuperar Crimea. Fue el primer texto de alianza verdaderamente recíproca firmado en la historia otomana con un Estado europeo y mostraba el abandono de la concepción clásica de que «no hay alianza con los infieles». Prusia no entró en la guerra, pero al forzar a Austria a la paz allanó el camino al Tratado de Sistova.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Caída de la fortaleza de Ismail y matanza", "6a296b0c"], "d": ["La fortaleza de Ismail, considerada la fortificación más fuerte del delta del Danubio, fue tomada en un solo día mediante un sangriento asalto general dirigido por el general Suvórov; la guarnición y gran parte de la población de la ciudad fueron pasadas a cuchillo. Esta matanza, que tuvo amplio eco en Europa, causó una profunda conmoción en la opinión pública otomana y quebró la columna vertebral de la línea defensiva del Danubio. La fortaleza sería recuperada un año después por el Tratado de Iași, pero la suerte de la guerra ya estaba echada.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Tratado de Sistova — cierre del frente austríaco", "58741f1d"], "d": ["Gracias a la presión de Prusia y a que la Revolución francesa mantenía ocupada a Austria en el oeste, los dos Estados llegaron a la paz tomando como base las fronteras anteriores a la guerra. Austria devolvió todos los lugares que había ocupado, Belgrado incluida; el Estado otomano solo aceptó pequeñas rectificaciones en la frontera con Croacia. El cierre del frente occidental en estas condiciones permitió al Estado otomano concentrar toda su fuerza contra Rusia y limitó la pérdida del Tratado de Iași.", "45643640"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Tratado de Iași — pérdida definitiva de Crimea y frontera del Dniéster (Turla)", "a56fd194"], "d": ["Con el tratado firmado al término de la guerra de cinco años se aceptó el río Turla (Dniéster) como frontera; la orilla izquierda del río quedó para Rusia y la derecha para el Imperio otomano, y Özi y sus alrededores se perdieron definitivamente. El Estado otomano abandonó por completo la esperanza de recuperar Crimea y reconoció jurídicamente la anexión de 1783; Valaquia y Moldavia fueron devueltas con una exención de impuestos de dos años. Al aceptarse además la obligación de una indemnización de guerra de doce millones de kuruş, el norte del mar Negro quedó cedido de forma permanente a Rusia. Otros lugares incorporados en la misma fecha: Ismail.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Evacuación de Vehrân (Orán) por los españoles y su cesión a Argel", "9f95cee6"], "d": ["Cuando el terremoto de 1790 destruyó en gran parte la fortaleza y la ciudad, España, que ya no podía sostener la costosa guarnición que mantenía desde hacía tres siglos, llegó a un acuerdo con el odjak de Argel y le cedió sin guerra Vehrân y Mazalquivir. Así se liquidó también el último puesto europeo de la costa del norte de África. La Argelia otomana dominó toda la costa durante treinta y ocho años, hasta la ocupación francesa.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Gobierno de hecho de Pazvandoğlu Osman en Vidin", "0ce70361"], "d": ["Pazvandoğlu Osman, que se sublevó contra las disposiciones del Nizam-ı Cedid, hizo huir al gobernador de Vidin, se apoderó de la ciudad y la fortificó con profundas trincheras a lo largo del Danubio. En 1797, en el apogeo de su poder, reunió casi ochenta mil hombres y puso bajo su control Nicópolis, Sistova, Rusçuk, Sofía y Niš; se presentó a sí mismo no como rebelde sino como reformador. El asedio de meses que la Sublime Puerta llevó a cabo en 1798-1799 fue infructuoso, y gobernó de forma semiindependiente el norte de Bulgaria hasta su muerte en 1807.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Apertura de la Mühendishâne-i Berrî-i Hümâyun", "e9a3a34b"], "d": ["Para formar oficiales de artillería, zapadores y cartógrafos para el ejército del Nizam-ı Cedid, se abrió en Hasköy la escuela de ingeniería terrestre, equivalente en el ejército de tierra de la Escuela de Ingeniería Naval fundada en 1773. En el programa se enseñaron álgebra, geometría, mecánica, fortificación y balística, y se tradujeron libros de matemáticas y artillería de lenguas europeas. Esta escuela, considerada la raíz de la enseñanza moderna de la ingeniería en Turquía, se tiene por el comienzo de la actual Universidad Técnica de Estambul.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Declaración de guerra a Francia y alianza con Rusia e Inglaterra", "80e95bd7"], "d": ["Ante la ocupación de Egipto por Napoleón, el Estado otomano rompió la tradicional amistad francesa de dos siglos y medio y declaró la guerra a Francia. En el mismo proceso, por primera vez en su historia, se alió con Rusia y permitió que la flota rusa pasara por los Estrechos y saliera al Mediterráneo; después se firmó también una alianza con Inglaterra. Gracias a estas alianzas las islas Jónicas fueron tomadas a los franceses, pero la apertura de los Estrechos a una flota extranjera sentó un precedente que más tarde tendría un precio muy alto.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Toma de Preveza a los franceses — batalla de Nicópolis", "d8e5e892"], "d": ["Tras la caída de la República de Venecia en 1797, las islas Jónicas y las plazas continentales de Preveza, Parga y Vonitsa pasaron a manos de Francia. Ali Pachá de Tepelena, gobernador de Ioánina, aprovechando la guerra desencadenada por la invasión francesa de Egipto, marchó sobre Preveza e infligió una grave derrota a la guarnición francesa entre las ruinas de Nicópolis, a las afueras de la ciudad. Así, este puerto, dejado a Venecia en Passarowitz, volvió a la administración otomana ochenta años después.", "eeebcaf6"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Defensa de Acre — rechazo de Napoleón", "56b5c45b"], "d": ["Napoleón, que avanzaba de Egipto a Siria, sitió Acre y lanzó asaltos sucesivos durante dos meses; la ciudad fue defendida por Cezzar Ahmed Pasha con el apoyo de la flota inglesa y de las tropas del Nizam-ı Cedid enviadas desde Estambul. Napoleón, obligado a levantar el asedio y replegarse a Egipto, enterró ante estas murallas su sueño de extenderse hacia el este. La noticia fue recibida con gran alegría en Estambul y se consideró la prueba de que el ejército instruido, recién creado, había superado su primer examen serio.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Ataque wahabí a Kerbala", "522341ed"], "d": ["Las fuerzas wahabíes, salidas de Néyed, entraron en Kerbala, saquearon la ciudad, destruyeron el mausoleo del imán Husayn y mataron a más de tres mil personas. Los gobernadores mamelucos del Estado otomano en Irak no pudieron impedir el ataque; el hecho provocó una gran reacción tanto en Irán como en Estambul. Esta agresión proclamó que el movimiento saudí había dejado de ser un emirato de oasis para convertirse en una potencia regional que amenazaba las ciudades santas otomanas.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Kartli-Kajetia (Georgia oriental) fue anexionada a Rusia", "3b650c5e"], "d": ["El zarato de Kartli-Kajetia, que en 1783 aceptó el protectorado ruso y en 1795 sufrió la devastadora campaña de Irán, fue disuelto; por una orden del 12 de septiembre de 1801 fue declarado provincia de Rusia y se comenzó a implantar el sistema administrativo ruso. Desde esta fecha Georgia perdió su independencia; en pocos años Mingrelia (1803), Imericia y Gurialeti (1804) pasaron también al dominio ruso, y Rusia llegó a la frontera caucásica otomana.", "957f5cd5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Evacuación de Egipto por los franceses", "00cfdc8c"], "d": ["Como resultado de la operación conjunta por tierra y mar de las fuerzas otomanas e inglesas, fueron recibidas primero El Cairo y después Alejandría, y las fuerzas francesas fueron enviadas a su país en barcos. Al terminar la ocupación de tres años, Egipto volvió sobre el papel a la administración otomana, pero la lucha por el dominio entre sus beyes mamelucos y las tropas albanesas sumió al país en el caos. Este vacío prepararía, en pocos años, el terreno para el ascenso de Mehmed Ali de Kavala.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Tratado de París — restablecimiento de la paz con Francia", "1b76991f"], "d": ["Con el tratado firmado tras la evacuación de Egipto terminó oficialmente el estado de guerra entre el Estado otomano y Francia y se renovaron las antiguas capitulaciones. Se permitió la entrada de los buques mercantes franceses en el mar Negro; a cambio, Francia reconoció la integridad territorial otomana. El establecimiento de la paz devolvió margen de maniobra a la política exterior de Selim III, que estaba acorralada junto a Rusia e Inglaterra.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Toma de Taif por los wahabíes", "7b791359"], "d": ["Las fuerzas wahabíes al mando de Saud ibn Abd al-Aziz sitiaron y saquearon Taif en su primer movimiento hacia el Hiyaz; la ciudad cayó como primera puerta de acceso a las tierras santas. Para el sultán otomano, que ostentaba el título de protector de los Dos Santuarios, este fue un golpe que sacudía directamente la legitimidad del sultanato. Dos meses y medio después, ese mismo ejército marcharía sobre La Meca.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Primera toma de La Meca por los wahabíes", "21157c05"], "d": ["Dos meses y medio después de la caída de Taif, las fuerzas wahabíes entraron en La Meca, destruyeron los mausoleos y establecieron un orden conforme a su propia concepción; el sharif Ghalib se vio obligado a retirarse a Yeda. El cierre de las rutas de peregrinación tuvo eco en todo el mundo islámico y obligó a Estambul a pedir ayuda militar al gobernador de Egipto, Mehmed Ali. Este primer dominio duraría solo tres meses.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Recuperación de La Meca por el sharif Ghalib", "83d08dff"], "d": ["El sharif Ghalib, que se había retirado a Yeda, sitió La Meca con las fuerzas que reunió y, tras un asedio de veinticinco días, recuperó la ciudad de manos de los wahabíes; la jutba volvió a leerse en nombre de los otomanos. Este segundo dominio tampoco sería duradero: las fuerzas de Saud volverían a tomar la ciudad en 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Comienzo de la Primera Insurrección serbia", "0f6e8767"], "d": ["Cuando los dahis janízaros rebeldes que habían tomado el poder en Belgrado mataron en masa a los notables serbios, comenzó una resistencia armada bajo la dirección de Karađorđe. El movimiento, que al principio se mantuvo fiel al sultán y se dirigió solo contra los dahis, se transformó pronto en una rebelión nacional que reclamaba autonomía e independencia. Las fuerzas serbias tomaron Belgrado en 1806; este levantamiento fue el primer eslabón de los movimientos nacionalistas de independencia en los Balcanes.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Ocupación de Medina por los wahabíes", "84e310d7"], "d": ["Tras La Meca, Medina cayó también en manos de las fuerzas wahabíes; se repartió el tesoro de la Rawda al-Mutahhara y se derribaron los mausoleos con cúpula de la ciudad. Así, las dos ciudades santas salieron a la vez del control otomano y las caravanas de peregrinos procedentes de Damasco y Egipto no pudieron partir durante años. Medina solo pudo ser recuperada siete años después, en 1812, por el ejército egipcio al mando de Tosun Pasha, hijo de Mehmed Ali Pasha.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Comienzo de la guerra con Rusia (guerra otomano-rusa de 1806-1812) y cierre de los Estrechos", "ea170804"], "d": ["Cuando Selim III, que tras la victoria de Napoleón en Austerlitz se había acercado a Francia, destituyó a los voivodas de Valaquia y Moldavia a pesar de la presión rusa, los ejércitos rusos ocuparon ambos principados y comenzó la guerra. El Estado otomano cerró los Estrechos a la flota rusa; en respuesta, Inglaterra se puso del lado de Rusia y envió una flota a Estambul. Esta guerra, que duraría seis años, entrelazada con la rebelión de Kabakçı y la deposición de Selim III, terminaría con la pérdida de Besarabia en el Tratado de Bucarest de 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Llegada de la flota inglesa ante Estambul (operación Duckworth)", "195bb58f"], "d": ["Inglaterra, que quería obligar al Estado otomano a romper sus lazos con Francia, hizo pasar por los Dardanelos a la flota del almirante Duckworth y la fondeó ante Estambul. Con la dirección también del embajador francés Sébastiani, la población de Estambul se movilizó, las baterías costeras se reforzaron en pocos días y la flota, sin haber podido bombardear la ciudad, se vio obligada a retirarse; en el regreso sufrió graves pérdidas en los Dardanelos. Que la capital fuera amenazada por primera vez tan de cerca por una flota extranjera colocó la cuestión de los Estrechos en el centro de la diplomacia europea.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Estrangulamiento de Mustafa IV", "eeb75c20"], "d": ["Tras la muerte de Alemdar Mustafa Pachá, sorprendido en un asalto, y al querer los rebeldes marchar sobre el palacio, el depuesto Mustafa IV fue estrangulado por orden de su hermano Mahmud II. Su cadáver fue sepultado en Bahçekapı, en el mausoleo de su padre Abdülhamid I; entre los rebeldes se difundió el rumor de que el ataúd estaba vacío.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Tratado de los Dardanelos (Kale-i Sultaniye) — paz con Inglaterra y regla de los Estrechos", "fe282117"], "d": ["Con el tratado firmado con Inglaterra tras el fracaso de la operación Duckworth terminó la guerra entre los dos Estados y se devolvieron a los comerciantes ingleses sus antiguos privilegios. La disposición del texto, llamada «regla antigua» (kadim kaide), dejó constancia de que en tiempo de paz ningún buque de guerra extranjero podría pasar por los Estrechos. Este principio se convirtió, durante todo el siglo XIX, en el fundamento jurídico de todos los arreglos internacionales que darían forma al régimen de los Estrechos.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Desastre de Slobozia — cerco del ejército del Danubio", "54b60fd1"], "d": ["La mayor parte del ejército otomano que había cruzado el Danubio ante Rusçuk fue acorralada en Slobozia por la maniobra de envolvimiento que Kutúzov realizó desde la orilla opuesta del río y quedó abandonada al hambre. Miles de soldados tuvieron que rendirse; la fuerza en manos del gran visir se disolvió de hecho y la Sublime Puerta tuvo que pedir un armisticio un mes después. Esta derrota es la causa directa de que se aceptara ceder Besarabia en el Tratado de Bucarest de 1812.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Recuperación de Belgrado y represión de la Primera Insurrección serbia", "06f56f52"], "d": ["Los rebeldes serbios, privados del apoyo ruso por el Tratado de Bucarest, no pudieron resistir la operación conjunta de las fuerzas llegadas de Bosnia y Rumelia; Hurşid Ahmed Pasha entró en Belgrado y la sublevación de nueve años fue reprimida por completo. Karađorđe huyó a Austria y el sanjacado de Semendire volvió a depender directamente de la administración otomana. Sin embargo, las duras medidas aplicadas desencadenarían, dos años después, una segunda insurrección, esta vez duradera, bajo la dirección de Miloš Obrenović.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Segunda Insurrección serbia y principado de Miloš Obrenović", "e6e82ad2"], "d": ["Contra las duras medidas aplicadas tras la represión de la primera insurrección estalló un nuevo levantamiento bajo la dirección de Miloš Obrenović; esta vez la Sublime Puerta prefirió el entendimiento a la fuerza. Mediante el acuerdo alcanzado, Miloš fue reconocido con el título de «príncipe supremo» (başknez) y la facultad de recaudar impuestos y de llevar los asuntos internos quedó en manos de los knez serbios. Este primer núcleo de autonomía de hecho fue el punto de partida del proceso que se extendería hasta el firmán de 1830 y la independencia de 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Insurrección de Valaquia — Ypsilantis cruza el Prut y levantamiento de Vladimirescu", "67d46a98"], "d": ["Alexandros Ypsilantis, general del ejército ruso, cruzó el Prut en nombre de la Filikí Etería e intentó iniciar un levantamiento general griego en Valaquia y Moldavia; en los mismos días Tudor Vladimirescu puso también en movimiento a los campesinos locales. Los dos movimientos no pudieron unirse: Vladimirescu respondió a la invitación de Ypsilantis a combatir juntos contra los turcos con las palabras «No me he alzado contra los turcos, sino contra los griegos», y poco después fue asesinado por hombres de Ypsilantis. La insurrección fue reprimida por las fuerzas otomanas en mayo, pero terminó el régimen de los voivodas fanariotas y el fuego de la rebelión se extendió a la Morea.", "935b260a"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Fundación del Segundo Estado saudí en Riad", "34dad3bd"], "d": ["Seis años después de la caída de Dir'iyya en 1818 y la destrucción del primer Estado saudí, Turki ibn Abdallah expulsó las guarniciones egipcias de Néyed y fundó un nuevo emirato saudí con centro en Riad. La nueva estructura prefirió permanecer en Néyed, evitando extenderse hacia el Hiyaz, y se mantuvo alejada del enfrentamiento directo con las fuerzas otomano-egipcias. Este segundo Estado duraría hasta finales del siglo y constituiría el segundo eslabón de la cadena que conduce a la fundación de la actual Arabia Saudí. Otros asentamientos perdidos en la misma fecha: Dir'iyya (Néyed).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Convención de Akkerman — concesiones a Serbia y a los principados", "c75f15d0"], "d": ["El Estado otomano, que se había quedado sin ejército inmediatamente después de la abolición del cuerpo de los Janízaros, se vio obligado a aceptar un tratado de duras condiciones ante el ultimátum de Rusia. Se confirmó la autonomía prometida a Serbia, se admitió que los voivodas de Valaquia y Moldavia no podrían ser destituidos sin la aprobación de Rusia y se concedió plena libertad a los buques mercantes rusos en los Estrechos. Cuando la Sublime Puerta declaró dos años después que no reconocía el tratado a causa de la cuestión griega, Rusia lo tomaría como motivo de guerra.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Liquidación del sistema de timar", "84d5d1d6"], "d": ["Un año después de la abolición del cuerpo de los Janízaros, unos 5.200 sipahis con timar de cincuenta y tres sanjacados de Rumelia y Anatolia fueron transformados, junto con sus ingresos de timar, en caballería del Asâkir-i Mansûre. Así terminó de hecho el régimen del timar, columna vertebral durante cuatro siglos del orden otomano de la tierra, los impuestos y el ejército. Los timares vacantes fueron transferidos al tesoro y se abrió el camino al paso a un ejército central asalariado y a un sistema de impuestos en dinero.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Fundación del Tıphâne-i Âmire — comienzo de la enseñanza médica moderna", "ac3e57c0"], "d": ["Para formar médicos y cirujanos para el recién creado ejército del Asâkir-i Mansûre, se abrió en Şehzadebaşı el Tıphâne-i Âmire por propuesta del médico jefe Mustafa Behçet Efendi. Las clases se organizaron según el plan de estudios europeo y la enseñanza se impartió al principio en francés; pocos años después se fundó también el Cerrahhâne-i Âmire y las dos instituciones se fusionaron. Esta escuela, considerada el comienzo de la enseñanza médica moderna en Turquía, se tiene por el origen de la actual Facultad de Medicina de Estambul.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Comienzo de la guerra otomano-rusa de 1828-1829", "9dff4e05"], "d": ["Tras el incendio de la flota en Navarino y la declaración de la Sublime Puerta de que no reconocía la Convención de Akkerman, Rusia abrió la guerra en dos frentes a la vez. Como el cuerpo de los Janízaros acababa de ser abolido y el nuevo ejército estaba aún en proceso de formación, la defensa otomana fue débil desde el principio; mientras los rusos cruzaban el Danubio, en el este tomaron Kars y Ajaltsije. El ejército ruso, que en un año avanzó hasta Edirne, impondría las duras condiciones del Tratado de Edirne de 1829 y la independencia de Grecia.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Primer tratado con los Estados Unidos de América", "d737516f"], "d": ["Con el tratado de comercio y navegación firmado tras años de contactos, los Estados Unidos obtuvieron en territorio otomano el estatuto de nación más favorecida y el derecho de paso comercial por los Estrechos. Un artículo secreto aparte preveía que el Imperio otomano pudiera hacer construir barcos en los astilleros norteamericanos cuando lo deseara y comprar barcos ya construidos y madera; el Senado de los Estados Unidos ratificó el tratado, pero rechazó ese artículo secreto por 27 votos contra 18. Aun así, la vía de los barcos no se cerró: Henry Eckford vendió en 1831 al Imperio otomano el barco que había traído, y los maestros norteamericanos que trabajaron en Aynalıkavak dotaron a la flota de nuevos tipos de buques. Este tratado fue el documento de la primera relación de alcance amplio que el Estado otomano estableció con un Estado fuera de Europa.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Fin del gobierno mameluco en Bagdad", "7e1d38a3"], "d": ["Mahmud II, que seguía una política de centralización, declaró rebelde al gobernador de Bagdad, Davud Pasha, que no enviaba el dinero solicitado y había hecho matar al funcionario enviado desde el centro. La fuerza al mando de Ali Rıza Pasha tomó la ciudad tras un asedio de noventa días y los mamelucos fueron casi todos liquidados. Así terminó la administración mameluca semiindependiente, vigente desde 1704, e Irak volvió a depender directamente del centro.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Fundación de la Mekteb-i Harbiye en el cuartel de Maçka", "bf31c7d9"], "d": ["Para proporcionar al Asâkir-i Mansûre-i Muhammediyye oficiales formados al estilo europeo, se abrió en el cuartel de Maçka la Mekteb-i Fünûn-ı Harbiyye. A los alumnos se les enseñaron matemáticas, cartografía, fortificación y lenguas extranjeras; poco después se reforzó el cuadro docente enviando estudiantes a Viena y París. Esta escuela fue el lugar donde nacieron la tradición de oficiales formados en escuelas del ejército otomano y, con ella, la nueva generación de militares-intelectuales que surgiría a finales del siglo XIX.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Trípoli de Berbería pasa a depender directamente del centro — fin de la dinastía Karamanli", "faabcb96"], "d": ["Debido a las luchas por el trono dentro de la familia Karamanli y a la creciente presión europea tras la ocupación de Argel por Francia en 1830, la Sublime Puerta intervino directamente en Trípoli de Berbería. La flota enviada desde Estambul entró en la ciudad, el último bey Karamanli fue destituido y llevado a Estambul, y la provincia fue entregada a un gobernador nombrado desde el centro. Con el fin de la dinastía, tras un período de 124 años, se consolidó la última porción de territorio que el Estado otomano administraba directamente en el norte de África.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Abolición del cargo de defterdar y creación del Ministerio de Hacienda (Maliye Nezâreti)", "89f8125e"], "d": ["Se suprimió el cargo de defterdar, cabeza del orden financiero otomano clásico, y se creó el Maliye Nezâreti, un ministerio al estilo europeo, y los tesoros dispersos se reunieron en una sola mano. Ese mismo año, las demás unidades de la Sublime Puerta fueron también reorganizadas bajo el nombre de nezâret, pasando a una estructura de consejo de ministros moderno. Esta reorganización fue uno de los pasos más importantes que prepararon la infraestructura administrativa del Edicto de Tanzimat, que se proclamaría un año después.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Instalación de los ingleses en Adén", "ddbd556b"], "d": ["Inglaterra, basándose en el acuerdo de comercio y amistad firmado en 1802 con el sultán de Lahej, Ahmed ibn Abd al-Karim, desembarcó tropas en el puerto de Adén y tomó la ciudad bajo su control. Este puerto, que guarda la entrada del mar Rojo, se convirtió en un punto clave de la estrategia imperial inglesa como base de abastecimiento de carbón en la ruta de la India. Aunque la reivindicación del Estado otomano sobre Yemen se mantuvo sobre el papel, su dominio de hecho en la costa meridional no volvió jamás después de esta fecha.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Regreso a la costa de Tihama: toma de Hodeida, Zabid y Moca", "353982d2"], "d": ["En la costa de Yemen, que había quedado sin dueño tras la retirada del ejército egipcio en 1840, desembarcaron fuerzas al mando de Tevfik Pasha bajo la supervisión del sharif de La Meca y anexionaron a la administración otomana los puertos de Hodeida, Zabid y Moca. Se quiso avanzar hasta Saná, pero la resistencia de la población obligó a regresar a Hodeida; así, las tierras altas quedaron en manos de los imames zaidíes y el dominio otomano se mantuvo durante veintitrés años solo en la franja de Tihama. El interior de Yemen solo sería recuperado en 1872 con la campaña de Ahmed Muhtar Pasha.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Convención de Baltalimanı: protectorado conjunto otomano-ruso en Valaquia y Moldavia", "d3bb22e9"], "d": ["Cuando las revoluciones de 1848 se extendieron a Valaquia y Moldavia, las fuerzas otomanas y rusas habían ocupado conjuntamente los principados. Mediante la convención firmada en Baltalimanı se acordó que los voivodas no serían elegidos, sino nombrados por el sultán por un período de siete años, y que los dos Estados establecerían un control conjunto en la región. El acuerdo, que preservaba la soberanía otomana sobre el papel, reconoció a Rusia un derecho de codominio de hecho y aceleró la separación de los principados del Danubio respecto del Imperio otomano.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Cuestión de los refugiados húngaros: Kossuth y sus compañeros se refugian en el Imperio otomano", "1c7d7ef4"], "d": ["Cuando la revolución húngara de 1848-1849 fue aplastada por la intervención rusa y austríaca, Lajos Kossuth y miles de refugiados húngaros y polacos se refugiaron en territorio otomano. Austria y Rusia exigieron con dureza la devolución de los refugiados; la Sublime Puerta, con el apoyo de Inglaterra y Francia, rechazó la extradición y estableció al grupo en Kütahya. El entorno de Kossuth permaneció allí unos dieciocho meses y cientos de refugiados se hicieron musulmanes y entraron al servicio otomano. El hecho se consideró una de las raras victorias diplomáticas que elevaron el prestigio del Imperio otomano del Tanzimat ante la opinión pública europea.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Fundación del Encümen-i Dâniş: la primera academia otomana en Estambul", "6fda1365"], "d": ["El Encümen-i Dâniş, fundado por decisión del Meclis-i Maârif-i Umûmiyye, es la primera academia científica otomana, constituida para preparar libros científicos y de texto en turco. Se inauguró con una ceremonia el 18 de julio de 1851 en el edificio del Dârülmaârif; entre sus miembros, locales y extranjeros, figuraba también Ahmed Cevdet Pasha. Aunque tuvo corta vida, obras como la Târih y el Kavâid-i Osmâniyye de Cevdet Pasha fueron producto de esta institución, que se considera piedra angular de que el turco se convirtiera en lengua científica.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Victoria de Oltenitsa: primer éxito otomano en el frente del Danubio", "a660ad2f"], "d": ["En la fase inicial de la guerra de Crimea, el serdar-ı ekrem Ömer Lütfi Pasha cruzó el Danubio y rechazó con graves pérdidas a las fuerzas rusas en Oltenitsa. La victoria, al detener el avance ruso nada más empezar la guerra, mostró a Europa la fuerza que el ejército otomano había adquirido con la instrucción posterior al Tanzimat. Este éxito preparó el terreno psicológico que facilitó la decisión de Inglaterra y Francia de entrar en la guerra al lado del Imperio otomano.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Tratado de alianza con Inglaterra y Francia en Estambul", "04809278"], "d": ["El tratado de alianza firmado en la guerra de Crimea entre el Estado otomano, Inglaterra y Francia contra Rusia dispuso que los tres Estados llevaran a cabo operaciones conjuntas y que los aliados no hicieran la paz por separado antes del final de la guerra. Así, por primera vez en su historia, el Estado otomano entró en una alianza militar con grandes Estados europeos como parte en pie de igualdad. Este tratado constituyó también el fundamento jurídico de la admisión formal del Imperio otomano en el sistema de Estados europeos, dos años después en París.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Creación de la Şehremaneti de Estambul: primera organización municipal moderna", "be4af27f"], "d": ["La crisis de infraestructuras provocada por los soldados aliados amontonados en Estambul durante la guerra de Crimea y por el aumento de la población puso de manifiesto la insuficiencia de la administración urbana clásica centrada en el cadí. Con la Şehremaneti, fundada según modelos europeos, la limpieza, la tasación de precios, el control de los mercados y las obras de urbanismo se reunieron en una sola mano; al año siguiente se constituyó en Beyoğlu-Galata el Sexto Distrito Municipal (Altıncı Daire-i Belediye) como zona piloto. Este paso se considera el comienzo del municipalismo moderno en el Imperio otomano.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Tratado de París: fin de la guerra de Crimea y admisión del Imperio otomano en el sistema de Estados europeos", "4aee0e2a"], "d": ["Con el Tratado de París, que puso fin a la guerra de Crimea, el Estado otomano fue declarado miembro en pie de igualdad del derecho de gentes europeo y su integridad territorial quedó bajo la garantía común de las grandes potencias. El mar Negro fue neutralizado, se invalidó la pretensión rusa de protección sobre los súbditos ortodoxos, obtenida desde Küçük Kaynarca, y el sur de Besarabia (los distritos de Kili, Cahul, Ismail y Bolgrad) fue entregado a Moldavia. Sin embargo, el mismo tratado, al convertir el Edicto de Reforma (Islahat Fermanı) en un compromiso internacional, abrió también la puerta a la intervención en los asuntos internos.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Apertura del palacio de Dolmabahçe: traslado del centro administrativo desde Topkapı", "71ad26d0"], "d": ["El palacio que Abdülmecid había encargado en 1842 a la familia Balyan se abrió tras catorce años de obras, y el centro administrativo del Estado se trasladó de Topkapı, donde llevaba cuatro siglos, a la orilla del Bósforo. Con su estilo europeo, su escalera de cristal y su Salón de Ceremonias (Muayede), el palacio fue la expresión en piedra de la pretensión occidentalizadora del Tanzimat. Su enorme coste se convirtió en uno de los capítulos más criticados de los años en que la hacienda otomana entró en la espiral del endeudamiento exterior.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Unión de Valaquia y Moldavia bajo Cuza: nacimiento de Rumanía", "baef4da5"], "d": ["En las elecciones organizadas tras el Tratado de París, ambos principados eligieron voivoda al coronel Alexandru Ioan Cuza y realizaron así la unión de hecho. Aunque la Sublime Puerta y Austria se opusieron, con el apoyo de Francia hubo que aceptar el hecho consumado. Esta unión, que sobre el papel seguía dependiendo del Imperio otomano, tomaría en 1862 el nombre de Rumanía y proclamaría unilateralmente su independencia en 1877; es un punto de inflexión en la disolución del dominio otomano en el Danubio.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Incidente de Kuleli: primer intento de golpe contra Abdülmecid en Estambul", "e3653b21"], "d": ["Una sociedad secreta mixta de militares y civiles, que reaccionaba contra la política del Tanzimat y contra la igualdad que el Edicto de Reforma concedía a los no musulmanes, fue asaltada durante una reunión en la mezquita de Kılıç Ali Pasha mientras planeaba deponer al sultán. Como los acusados fueron juzgados en el cuartel de Kuleli, el suceso se conoce con este nombre; las penas de muerte fueron conmutadas por el destierro. Se considera el primer intento de golpe de palacio emprendido en la historia otomana por una organización constituida por motivos ideológicos.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Guerra civil drusa-maronita en el Monte Líbano y sucesos de Damasco", "5595fdd6"], "d": ["Los enfrentamientos que estallaron en mayo de 1860 con la muerte de dos drusos cerca de Sidón se convirtieron en la guerra civil drusa-maronita más sangrienta de la montaña, y en julio se extendieron a Damasco, con miles de cristianos muertos. Ante el desembarco de tropas por parte de Francia, la Sublime Puerta envió a la región a Fuad Pasha con poderes extraordinarios; se llevó a cabo una dura acción de castigo. Los sucesos sirvieron de pretexto a la intervención europea y fueron la causa directa de que el Líbano obtuviera un estatuto especial.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Comienzo de la publicación de Tercümân-ı Ahvâl: primer periódico turco privado en Estambul", "24792957"], "d": ["Tercümân-ı Ahvâl, publicado por Agâh Efendi y con Şinasi a cargo de la redacción, es el primer periódico turco publicado sin apoyo del Estado. En el prólogo de su primer número se defendió el derecho del pueblo a opinar sobre sus propios asuntos, y el periódico, al publicar por entregas Şair Evlenmesi de Şinasi, abrió también la puerta de la literatura turca moderna. El nacimiento del concepto de opinión pública y de la prensa de oposición en el Imperio otomano se remonta a esta fecha.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Reglamento del Monte Líbano: estatuto de mutasarrifato privilegiado para el Líbano", "bf375603"], "d": ["El reglamento preparado por presión de las grandes potencias tras las matanzas de 1860 convirtió el Monte Líbano en un mutasarrifato privilegiado, dependiente directamente de la Sublime Puerta y gobernado por un consejo administrativo constituido según el equilibrio entre confesiones. Se exigió que el mutasarrif fuera un súbdito otomano cristiano católico y que su nombramiento se sometiera a la aprobación de las grandes potencias; el primer mutasarrif fue Davud Pasha. Este orden duraría hasta 1915 y constituiría el núcleo del Estado libanés moderno.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Muerte de Abdülmecid y ascenso al trono del sultán Abdülaziz", "27204d7c"], "d": ["Cuando Abdülmecid, que firmó durante su reinado de veintidós años los edictos de Tanzimat y de Reforma, sucumbió a la tuberculosis, subió al trono su hermano Abdülaziz. En sus primeros años el nuevo sultán dio esperanzas con medidas de ahorro y una vida sencilla; convirtió la flota en una de las pocas potencias del mundo. Sin embargo, al final de su reinado se acumularon la pesada deuda exterior, la bancarrota de 1875 y las sublevaciones balcánicas, que prepararon el terreno para el movimiento de deposición de 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Los principados unidos adoptan el nombre de Rumanía", "d960e3fc"], "d": ["Valaquia y Moldavia, unidas de hecho desde la doble elección de Cuza en 1859, reunieron en 1862 sus asambleas y gobiernos bajo un solo techo en Bucarest y adoptaron oficialmente el nombre de Rumanía. Aunque el Estado otomano conservó jurídicamente la calidad de soberano y el tributo anual, perdió de hecho el control sobre el principado. El fin de la influencia otomana de cuatro siglos al norte del Danubio se simboliza con esta fecha.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Anexión de Suakin, Massawa y Dahlak a Egipto", "a0924860"], "d": ["Massawa, que el sultán Abdülmecid había concedido en 1846 al jedive de Egipto Mehmed Ali Pasha junto con Suakin como sâlyâne (asignación de ingresos), fue incorporada en tiempos del jedive İsmâil Pasha, con Dahlak y Suakin, a los dominios de Egipto y organizada con estatuto de kaymakamlık. Así, estos tres puertos de la costa africana del mar Rojo, aunque siguieron siendo jurídicamente territorio otomano, pasaron administrativamente de depender directamente de la Sublime Puerta a depender de El Cairo — entraron en el mismo estrato subordinado que su vecino Egipto y Sudán.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Comienzo de la Insurrección de Creta (1866-1869)", "3679b861"], "d": ["El levantamiento de gran envergadura que estalló en la isla con el apoyo abierto de Grecia convirtió por primera vez en un problema internacional la demanda de enosis (unión con Grecia) de los griegos de Creta. La dura guerra de montaña, que duró tres años, causó graves pérdidas al ejército otomano y tuvo gran eco en la opinión pública europea. La insurrección solo pudo apagarse en 1868, cuando Âlî Pasha fue a la isla y puso en vigor un reglamento que concedía amplios privilegios.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Retirada de las últimas guarniciones otomanas de Belgrado y de las fortalezas de Serbia", "b34217db"], "d": ["Por la presión de las grandes potencias y la insistente petición del príncipe Mihailo, la Sublime Puerta aceptó evacuar las últimas bases militares que le quedaban en Serbia; el 18 de abril de 1867 se arrió la bandera otomana de la fortaleza de Belgrado y se entregaron las llaves al príncipe. Así terminó la presencia militar otomana de hecho, vigente desde 1521, y desapareció el último gran obstáculo en el camino de Serbia hacia la independencia. La soberanía del sultán quedó reducida a una simple cuestión de bandera simbólica y de tributo.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Concesión del título de jedive a los gobernadores de Egipto", "09e10c12"], "d": ["Gracias a la intensa gestión de İsmâil Pasha, de la tercera generación de la dinastía de Kavala, y al dinero que hizo llegar a Estambul, el gobernador de Egipto recibió el título de jedive (hidiv), que subrayaba su superioridad sobre los demás gobernadores. En los mismos años el orden de sucesión se cambió de modo que pasara de padre a hijo, y a Egipto se le concedieron facultades de carácter soberano, como contraer deuda exterior, conceder condecoraciones y mantener consulados. Estos pasos son el primer eslabón de la cadena que aceleró la separación jurídica de Egipto respecto del Imperio otomano.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Reglamento de Creta: amplios privilegios administrativos para la isla", "12052262"], "d": ["Para poner fin a la insurrección de tres años, el gran visir Âlî Pasha pasó personalmente a la isla y, mediante el reglamento publicado con la aprobación del sultán, se concedieron a los cretenses consejos administrativos mixtos, tribunales locales, el uso del griego en los trámites oficiales y facilidades fiscales. Este arreglo mantuvo en pie treinta años más el dominio otomano en la isla. Pero los privilegios concedidos a la población cristiana debilitaron la posición de los cretenses musulmanes y sembraron las semillas de la crisis de 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Apertura del Şûrâ-yı Devlet: fundación del Consejo de Estado otomano", "70b16497"], "d": ["Por la orden imperial (irade) del 5 de marzo de 1868, el Meclis-i Ahkâm-ı Adliyye fue dividido en dos, dejando los asuntos administrativos y legislativos al Şûrâ-yı Devlet y los judiciales al Dîvân-ı Ahkâm-ı Adliyye; la institución se inauguró con una ceremonia en la Sublime Puerta y su primera presidencia se confió a Midhat Pasha. Se le encargó preparar los proyectos de ley, resolver los litigios administrativos y llevar los juicios de funcionarios. Con su estructura de miembros mixtos musulmanes y no musulmanes, se considera la primera aplicación institucional de la idea de la separación de poderes en el Imperio otomano.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Apertura del canal de Suez: acortamiento de la ruta de la India a través de Egipto", "377ccd04"], "d": ["Las obras, iniciadas en 1859, duraron diez años y el canal de 163 kilómetros, que une el Mediterráneo con el mar Rojo, entró en servicio con una ceremonia fastuosa. Al acortarse en miles de millas la ruta que une Europa con la India, Egipto se convirtió de golpe en un punto clave del comercio mundial. Este valor geoestratégico sería la causa principal de que Inglaterra ocupara Egipto trece años después de la apertura del canal; la deuda que el canal cargó sobre Egipto llevaría al jedivato a la bancarrota.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Fundación del Exarcado búlgaro: separación de la Iglesia búlgara del Fanar", "33a8272c"], "d": ["Por firmán del sultán se creó una Iglesia búlgara autónoma (exarcado), separada del Patriarcado griego, y se dejó a un plebiscito decidir qué distritos dependerían del exarcado. Aunque la Sublime Puerta dio este paso para quebrar la influencia griega, el resultado fue el contrario: la Iglesia se convirtió en el centro organizado de la identidad nacional búlgara y de la pretensión búlgara sobre Macedonia. Así se sentaron las bases institucionales de la rivalidad búlgaro-greco-serbia en los Balcanes y de las insurrecciones de 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Incorporación de Asir a la administración directa", "4559e099"], "d": ["Cuando la apertura del canal de Suez aumentó el valor estratégico del mar Rojo, se vio que las montañas de Asir, en medio de la ruta terrestre hacia el Yemen, no podían quedar sin control. Las fuerzas de Redif Pachá, que partieron en campaña hacia el Yemen, entraron en Abha, ligaron la región directamente a la administración otomana y se estableció el sanjacado de Asir. Debido a la geografía montañosa y a la influencia de los Idrisíes, este dominio nunca llegó a consolidarse del todo.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Campaña de Midhat Pasha a Néyed: restablecimiento del dominio otomano en Lahsa", "7db51461"], "d": ["Midhat Pasha, gobernador de Bagdad, aprovechó la lucha por el trono dentro de la familia saudí para enviar tropas a la costa occidental del golfo de Basora y anexionó la región de Lahsa a la provincia de Basora con el nombre de sanjacado de Néyed. Abdullah ibn Faysal fue nombrado mutasarrif y el dominio otomano quedó establecido sobre el papel. La campaña tenía por objeto detener la extensión de la influencia inglesa en el golfo y ese mismo año condujo también a que Catar entrara bajo control otomano.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Muerte del gran visir Âlî Pasha: fin de la generación del Tanzimat", "1cf0141c"], "d": ["Con la muerte de Âlî Pasha, que tras la muerte de Fuad Pasha en 1869 cargó él solo con la política del Tanzimat, se agotó la generación de maestros diplomáticos que habían dirigido durante treinta años la política exterior del Estado. La administración arbitraria y favorable a Rusia de Mahmud Nedim Pasha, que le sucedió, consolidó el gobierno personal de Abdülaziz. En los cinco años siguientes a la muerte de Âlî Pasha la hacienda quebró, los Balcanes se sublevaron y el cambio de sultán se hizo inevitable.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Establecimiento del control otomano en Catar", "3b453165"], "d": ["Por invitación del jeque Qasim ibn Thani, que estaba bajo presión inglesa, las fuerzas otomanas desembarcaron en la península de Catar y en el otoño de 1871 se estableció el control otomano en la región. Catar fue organizado como un distrito (kaza) dependiente del sanjacado de Néyed y el jeque fue nombrado kaymakam. Este movimiento fue el logro más concreto de la política de avance que Midhat Pasha llevaba a cabo contra Inglaterra en el golfo; la bandera otomana ondeó en la península hasta 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Firmán de sucesión a Túnez — el beylicato a la familia de Mehmed Sâdık Pachá", "1509ebb0"], "d": ["Mediante un firmán expedido gracias a las gestiones de Hayreddin Pachá, enviado a Estambul por el bey de Túnez Mehmed Sâdık Pachá, que aprovechó la derrota de Francia ante Prusia, Túnez fue concedida a Mehmed Sâdık Pachá y a sus descendientes por derecho de sucesión, permaneciendo ligada directamente a Estambul. No se negociarían guerra ni paz sin permiso del sultán, no se cedería a nadie ningún territorio del país y se atenderían las peticiones de soldados de los otomanos. Francia no reconoció el firmán; diez años después ocupó Túnez.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Toma de Saná: restablecimiento de la autoridad otomana en Yemen", "978e20a0"], "d": ["Cuando el valor estratégico del mar Rojo aumentó con la apertura del canal de Suez, la Sublime Puerta envió a Yemen al ejército de reserva (fırka-i ihtiyâtiyye) al mando de Ahmed Muhtar Pasha. Con la toma de Saná se restableció la autoridad del Estado en el interior de Yemen, perdido de hecho desde hacía dos siglos, y la región se convirtió en provincia (vilayet). Pero la lucha contra los imames zaidíes no terminó nunca; las insurrecciones de 1891, 1898 y 1904 constituyeron el frente interno más caro y más largo del Imperio otomano. Otros lugares incorporados en la misma fecha: Saná, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Comienzo de la Insurrección de Herzegovina: nueva llamarada de la Cuestión de Oriente", "571b18ec"], "d": ["El levantamiento de los campesinos cristianos de los alrededores de Nevesinje, a causa de los pesados impuestos y la opresión de los notables (ayan), se extendió rápidamente a toda Herzegovina y se alimentó con voluntarios llegados de Serbia y Montenegro. La insurrección, que provocó las imposiciones de reformas por parte de Austria y Rusia, desencadenó al año siguiente las sublevaciones búlgaras y las declaraciones de guerra de Serbia y Montenegro. Así se rompió el primer eslabón de la gran cadena que llevaría a la Guerra de 1877-78 (Guerra del 93) y a la pérdida de los Balcanes por el Tratado de Berlín.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Bancarrota de la hacienda otomana: reducción a la mitad de los pagos de la deuda exterior", "2cac2fa5"], "d": ["Los empréstitos contraídos uno tras otro desde 1854, los gastos de la guerra de Crimea, las construcciones de palacios y la hambruna de Anatolia de 1873-74 convirtieron el déficit presupuestario en un abismo que superaba los cinco millones de liras. El gobierno de Mahmud Nedim Pasha declaró de hecho una moratoria al anunciar que los pagos de intereses y capital de la deuda se reducirían a la mitad durante cinco años. Esta decisión, que provocó una gran reacción en las bolsas europeas, inició el proceso que seis años después desembocaría en el Decreto de Muharrem y la creación de la Administración de la Deuda Pública Otomana (Düyûn-ı Umûmiyye).", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Deposición de Murad V y ascenso al trono de Abdülhamid II", "cffb2271"], "d": ["Murad V, que subió al trono tras la deposición de Abdülaziz, quedó incapacitado para el cargo por su salud mental, sacudida por la muerte de su tío y por el incidente de Çerkes Hasan; de los noventa y tres días de su reinado, solo en siete tuvo cabal juicio. Depuesto por fetua del şeyhülislam, fue sustituido por su hermano Abdülhamid II. El nuevo sultán subió al trono prometiendo a Midhat Pasha que proclamaría el régimen constitucional; comenzaba una época que duraría treinta y tres años.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Conferencia de los Astilleros (Tersane): imposición de reformas balcánicas por las grandes potencias", "b5006a2c"], "d": ["La conferencia que las grandes potencias reunieron en Estambul para resolver la crisis balcánica exigió la división de Bulgaria en dos provincias autónomas y la aplicación en Bosnia-Herzegovina de reformas bajo control internacional. La Sublime Puerta, que el día de la apertura de la conferencia anunció con salvas de cañón la proclamación de la Constitución (Kanûn-ı Esâsî), trató de responder a las imposiciones con una reforma constitucional. Los delegados lo tomaron por una maniobra dilatoria y se dispersaron el 20 de enero de 1877; cuatro meses después Rusia declaró la guerra.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Apertura en Dolmabahçe de la primera Asamblea de Diputados (Meclis-i Meb'ûsan)", "429bb279"], "d": ["Los 115 diputados elegidos conforme a la Constitución (Kanûn-ı Esâsî) se reunieron por primera vez el 19 de marzo de 1877 en una ceremonia celebrada en el Salón de Ceremonias del palacio de Dolmabahçe; así comenzó en la historia otomana el período de la asamblea representativa. Los diputados musulmanes y no musulmanes interrogaron duramente al gobierno y debatieron la conducción de la guerra y la responsabilidad de los ministros. Esta valiente oposición sería la principal causa de que la vida de la asamblea fuera tan corta.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Comienzo de la defensa de Plevna: la resistencia de Gazi Osman Pasha", "0e04a878"], "d": ["Osman Pasha, que en la Guerra del 93 marchó de Vidin a Plevna para cortar el camino de Estambul al ejército ruso que había cruzado el Danubio, fortificó la localidad con baluartes y trincheras y comenzó una legendaria defensa de cinco meses. Tres grandes ataques ruso-rumanos sucesivos fueron rechazados con graves pérdidas, y el ejército, dirigido personalmente por el zar Alejandro II, se vio obligado a sitiar la plaza. Plevna pasó a la historia como el más brillante éxito defensivo del ejército otomano en el siglo XIX.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Caída de Plevna: derrumbe del frente del Danubio", "185e7602"], "d": ["Osman Pasha, a quien se le habían agotado los víveres tras el asedio de cinco meses, emprendió una salida (huruç) por el río Vid; herido y hecho prisionero, la ciudad se rindió. Los comandantes rusos saludaron al pasha prisionero devolviéndole su sabre y a Osman Pasha se le dio el título de «Gazi». Con la caída de Plevna se abrió el camino al ejército ruso; en dos meses cayeron Sofía, Filibe y Edirne, y las vanguardias rusas llegaron a Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Ocupación de Sofía por las fuerzas rusas", "ef369d22"], "d": ["El ejército ruso, que tras la caída de Plevna había atravesado los Balcanes, entró en Sofía, que había quedado indefensa. La ciudad no volvería a la administración otomana: a finales de 1878 sería la capital del Principado autónomo de Bulgaria y, de hecho, en 1879. En el mapa, a partir de esta fecha Sofía sale de la administración directa otomana y pasa a la ocupación rusa provisional y después a la administración búlgara autónoma.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Armisticio de Edirne: fin de las hostilidades en la Guerra del 93", "1f899180"], "d": ["Con la caída sucesiva de Sofía, Filibe y Edirne y la llegada del ejército ruso a las costas del mar de Mármara, la Sublime Puerta se vio obligada a pedir un armisticio. El cese del fuego firmado en Edirne hizo que el Imperio otomano aceptara condiciones preliminares de paz como la autonomía de Bulgaria, la independencia de Montenegro, Serbia y Rumanía y una pesada indemnización de guerra. Estas condiciones se convertirían, un mes después, en el texto del tratado de San Stefano (Ayastefanos).", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Suspensión indefinida de la Asamblea de Diputados por Abdülhamid II", "e770b540"], "d": ["Ante las duras críticas de los diputados, que responsabilizaban al gobierno y al palacio del desastroso resultado de la guerra, Abdülhamid II suspendió indefinidamente la asamblea, apoyándose en la facultad que le otorgaba la Constitución (Kanûn-ı Esâsî). Así se cerró el primer parlamento otomano, que había funcionado unos once meses, y comenzó la época de despotismo (istibdat) que duraría treinta años. La asamblea no pudo volver a reunirse hasta después de la Revolución de 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Tratado de San Stefano (Ayastefanos): proyecto de la Gran Bulgaria", "2c7cc611"], "d": ["El Tratado de San Stefano, que puso fin a la Guerra del 93, creaba una enorme Bulgaria autónoma que se extendía hasta el Egeo e incluía Macedonia; reconocía la independencia de Serbia, Montenegro y Rumanía; cedía a Rusia Kars, Ardahan, Batum y Doğubayazıt, e imponía además una indemnización de guerra imposible de pagar. Este texto, que hacía descender a Rusia hasta el Mediterráneo, provocó la violenta reacción de Inglaterra y Austria. Sin llegar a aplicarse, fue reordenado en cuatro meses por el Congreso de Berlín; aun así, quedó como el documento que anunció el fin de la Rumelia otomana.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Kars, Ardahan y Batum fueron cedidas a Rusia — elviye-i selâse", "99bdfad2"], "d": ["Por el Tratado de Berlín, el Estado otomano cedió a Rusia Kars, Ardahan y Batum a cuenta de parte de la indemnización de guerra; Doğubayazıt y el valle de Eleşkirt, que en San Stefano habían sido dados a Rusia, quedaron en poder otomano. Aunque Batum fue cedida como puerto franco, solo pudo conservar este estatuto hasta 1886. Los rusos hicieron de Kars una provincia dependiente del gobierno general de Transcaucasia, con centro en Tiflis; de la población de elviye-i selâse, que ascendía a unas 100.000 personas, hubo de emigrar hacia el lado de Erzurum.", "e5049807"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Ocupación de Bosnia-Herzegovina y de Yenipazar por Austria-Hungría", "e5f901df"], "d": ["Basándose en la autorización otorgada por el Tratado de Berlín, los ejércitos austrohúngaros entraron en Bosnia; aunque el gobierno otomano había aceptado no resistir, la población local musulmana y ortodoxa de Sarajevo y Mostar tomó las armas y opuso durante tres meses una dura resistencia. La ocupación solo pudo completarse el 20 de octubre de 1878. La soberanía jurídica del sultán se mantuvo sobre el papel hasta 1908, pero la Bosnia otomana de cuatro siglos se perdió de hecho y comenzó una gran ola de emigración musulmana. Otros asentamientos perdidos en la misma fecha: Banaluka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Decreto de Muharrem y fundación de la Administración de la Deuda Pública Otomana (Düyûn-ı Umûmiyye)", "02b7cc03"], "d": ["Las negociaciones mantenidas tras la bancarrota de 1875 con los representantes de los Estados acreedores concluyeron en el decreto del 28 de Muharrem de 1299 (20 de diciembre de 1881): el principal de la deuda se redujo en más de la mitad, y a cambio las fuentes de ingresos más productivas, como los derechos sobre la sal, el tabaco, la seda, el timbre y la pesca, fueron cedidas a la Administración de la Deuda Pública (Düyûn-ı Umûmiyye İdaresi), gestionada directamente por los acreedores. Esta administración, que empleaba a miles de funcionarios, se transformó dentro del Estado en una organización financiera aparte. Se considera la fecha en que terminó de hecho la independencia financiera otomana.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — el único puerto que no cayó ante el Mahdi", "5a37b198"], "d": ["Mientras desde febrero de 1884 todas las regiones del Sudán oriental, salvo Suakin, pasaban al dominio de Muhammad Ahmad al-Mahdi, el puerto se mantuvo en pie con la protección militar de una fuerza inglesa de tres batallones al mando del general Graham. Fue el comienzo de un período en que se separaron la situación de hecho y la de derecho: aunque la costa estaba de hecho bajo control militar inglés, su vínculo administrativo sería retirado a Egipto en 1885 y pasaría a depender directamente de la provincia de Yemen, es decir, de la Sublime Puerta — orden que duró hasta que en 1888 terminó con la ocupación de Zeila por Francia.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Asesinato de Midhat Pasha en la prisión de Taif", "f4562261"], "d": ["Midhat Pasha, artífice de la Constitución (Kanûn-ı Esâsî) y nombre emblemático de la Primera Monarquía Constitucional, había sido declarado culpable por el Tribunal de Yıldız en el caso de la muerte de Abdülaziz y, con la pena de muerte conmutada por destierro, enviado a Taif. Según el registro del TDV, en la noche del 7 al 8 de mayo de 1884 fue estrangulado en su celda, y como causa oficial se anunció la enfermedad de «şîrpençe». Su muerte se convirtió en el símbolo de la liquidación de la oposición constitucional durante el reinado de Abdülhamid II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Concesión a los alemanes del ferrocarril Haydarpaşa-Ankara", "5705b163"], "d": ["Por orden del sultán, la concesión de construcción y explotación de la línea Haydarpaşa-Ankara fue otorgada al banquero Alfred von Kaulla, que representaba al Deutsche Bank, y se fundó la Compañía de los Ferrocarriles de Anatolia. Esta concesión fue el punto de inflexión que rompió el monopolio anglo-francés en el transporte y la política exterior otomanos y estableció la influencia alemana. Con la concesión de la línea de Bagdad, que se otorgaría a la misma compañía once años después, nacería el sueño de «Berlín-Bagdad», que se convertiría en uno de los ejes principales de la rivalidad de las grandes potencias antes de la Primera Guerra Mundial.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Fundación en Estambul de la Sociedad de Unión Otomana (İttihâd-ı Osmânî Cemiyeti)", "b7187939"], "d": ["Cuatro estudiantes de la Escuela Militar de Medicina fundaron la Sociedad de Unión Otomana (İttihâd-ı Osmânî Cemiyeti) como organización secreta contra el régimen despótico (istibdat); esta estructura se transformó pronto en la Sociedad de Unión y Progreso (İttihat ve Terakkî Cemiyeti), que reuniría bajo su techo a todos los elementos opositores del movimiento de los Jóvenes Turcos. La organización, basada en células, se unió a los exiliados en Europa y a los oficiales de Salónica. De esta pequeña célula de estudiantes saldría el cuadro que haría proclamar en 1908 la Segunda Monarquía Constitucional y que gobernaría solo el Estado a partir de 1913.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Asalto al Banco Otomano: acción de los activistas dashnak en Gálata", "08b3095f"], "d": ["Un grupo armado de la organización armenia Dashnaktsutyun asaltó la sede central del Banco Otomano en Gálata con el fin de atraer la atención de Europa sobre la cuestión armenia, tomó rehenes y amenazó con hacer volar el edificio. La crisis terminó, con la intervención de los embajadores, a cambio de la salida del país de los activistas en un barco. Los sangrientos sucesos que tuvieron lugar en Estambul en los días siguientes al asalto fueron decisivos para que la cuestión armenia se convirtiera en una palanca de intervención internacional.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Comienzo de la guerra otomano-griega de 1897: frente de Tesalia", "33e490ab"], "d": ["Ante el desembarco de la flota y las tropas de Grecia en Creta y los ataques de bandas en la frontera de Rumelia, el Estado otomano declaró la guerra. El ejército otomano, instruido por la misión alemana de reforma, avanzó rápidamente en Tesalia y en un mes tomó Yenişehir, Çatalca y Domokos; el ejército griego se dispersó. Los territorios ganados fueron devueltos por la intervención de las grandes potencias, pero la guerra quedó como la única victoria militar decisiva del reinado de Abdülhamid II y no pudo impedir la pérdida de hecho de Creta.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Concesión a los alemanes del ferrocarril Konya-Bagdad", "fd8b6cbd"], "d": ["Tras la visita del káiser Guillermo II a Estambul y Damasco en 1898, se otorgó a la Compañía de los Ferrocarriles de Anatolia la preconcesión de una línea que se extendería de Konya a Bagdad y Basora. El proyecto del ferrocarril de Bagdad significaba para el Imperio otomano reforzar el control central sobre las provincias árabes y para Alemania llegar al golfo de Basora. Este proyecto, al que Inglaterra y Rusia se opusieron con vehemencia, se convirtió en uno de los expedientes más controvertidos de la rivalidad imperialista que condujo a la Primera Guerra Mundial.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Comienzo en Damasco de la construcción del ferrocarril del Hiyaz", "62f58f68"], "d": ["La línea, ordenada por orden imperial de Abdülhamid II del 2 de mayo de 1900, comenzó a construirse el 1 de septiembre de 1900 con una ceremonia oficial celebrada en Damasco. El proyecto, realizado íntegramente con donaciones recogidas en el mundo islámico y con el trabajo de ingenieros y soldados otomanos, redujo de cuarenta a cinco días el viaje de los peregrinos entre Damasco y Medina. Fue a la vez una obra de prestigio que reforzaba la autoridad espiritual del califato y una inversión estratégica que consolidaba el control militar sobre el Hiyaz.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Programa de Mürzsteg: control internacional de las reformas en Macedonia", "4c7464da"], "d": ["Tras la insurrección de Ilinden, los emperadores de Rusia y Austria se reunieron en Mürzsteg y prepararon un nuevo paquete de reformas para Macedonia. El programa preveía colocar dos agentes civiles extranjeros junto al inspector general otomano, reorganizar la gendarmería con oficiales europeos y modificar las fronteras administrativas según criterios de nacionalidad. Aunque la Sublime Puerta se resistió alegando que se lesionaban sus derechos de soberanía, se vio obligada a aceptar ante la presión conjunta; el programa fue uno de los factores fundamentales que aceleraron la organización unionista entre los jóvenes oficiales.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Fallecimiento de Murad V", "396659a7"], "d": ["Murad V, que permaneció unos tres meses en el trono en 1876 y fue depuesto, vivió prisionero veintiocho años bajo estricta vigilancia tras los intentos de devolverlo al trono, y murió de diabetes. Fue sepultado junto a su madre en el mausoleo Cedîd Havâtîn de Yenicami. Pasó a la historia como el sultán otomano que menos tiempo permaneció en el trono.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Pérdida de Saná a manos del imam Yahya", "e7f876cb"], "d": ["La insurrección que el imam zaidí Yahya Hamid al-Din inició en 1904 terminó en abril de 1905 con la caída de Saná tras un asedio; la ciudad salió de la administración otomana y durante el asedio se declararon hambre y epidemia. La geografía montañosa de Yemen, la longitud de las líneas de abastecimiento y la legitimidad local del imamato zaidí hicieron frágil el dominio otomano desde su fundación. La ciudad sería recuperada cinco meses después a costa de graves pérdidas, pero el problema de Yemen no se cerraría hasta 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Atentado de Yıldız: ataque con bomba contra Abdülhamid II", "1ee2e1a6"], "d": ["La organización Dashnaktsutyun perpetró un atentado haciendo estallar un landó con una bomba de relojería al paso del coche del sultán, que salía de la ceremonia de saludo del viernes (selâmlık); el retraso de unos minutos de Abdülhamid, que conversaba con el şeyhülislam, le salvó la vida. En la explosión murieron veintiséis personas y más de cincuenta resultaron heridas. El hecho endureció aún más la obsesión por la seguridad del sultán y su régimen despótico basado en la organización de espías; fue también tema del poema «Bir Lahza-i Taahhur» de Tevfik Fikret.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Recuperación de Saná: represión de la insurrección del imam Yahya", "dec3b8f9"], "d": ["La insurrección iniciada en 1904 bajo la dirección del imam zaidí Yahya terminó en abril de 1905 con la caída de Saná, y en la ciudad se declararon hambre y epidemia. Los ejércitos de refuerzo al mando de Ali Rıza Pasha y Ahmed Feyzi Pasha, con una operación que llevaron a cabo entre el 15 de julio y el 1 de septiembre de 1905 y que contó también con el apoyo de las fuerzas de Taiz, recuperaron la ciudad a costa de graves pérdidas y la insurrección fue reprimida. La campaña de Yemen supuso para el ejército otomano decenas de miles de bajas y una enorme carga financiera; entre los oficiales de Rumelia, el miedo al «destierro a Yemen» estaba entre las quejas que alimentaban la organización unionista.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Reunión de la primera Asamblea de Diputados (Meclis-i Meb'ûsan) de la Segunda Monarquía Constitucional", "e7fd2716"], "d": ["La asamblea, formada mediante elecciones en dos grados tras una interrupción de treinta años, se abrió el 17 de diciembre de 1908 con el discurso del sultán, y su presidencia recayó en Ahmed Rıza Bey, líder del movimiento de los Jóvenes Turcos. Compuesta por diputados turcos, árabes, albaneses, griegos, armenios y judíos, la asamblea fue el último gran ensayo del ideal otomanista. Sin embargo, la independencia de Bulgaria, la anexión de Bosnia y la declaración de unión de Creta a Grecia habían ensombrecido este optimismo antes incluso de que la asamblea se abriera.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Ejército de Acción y deposición de Abdülhamid II: ascenso al trono de Mehmed V Reşad", "6a65a704"], "d": ["A raíz del Incidente del 31 de Marzo, el Ejército de Acción (Hareket Ordusu), partido de Salónica, entró en Estambul en la noche del 22 al 23 de abril por cuatro columnas y el 24 de abril se rindió el palacio de Yıldız. La Asamblea General Nacional (Meclis-i Umûmî-i Millî) decidió el 27 de abril la deposición de Abdülhamid II; el sultán fue enviado a Salónica y en su lugar subió al trono su hermano Mehmed V Reşad. Así terminó el gobierno personal de treinta y tres años, pero fue sustituido por una nueva época en que el sultán se convirtió en un símbolo y gobernó la Sociedad de Unión y Progreso con el apoyo del ejército.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Insurrección de Albania: resistencia armada en Kosovo y Shkodër", "93ed30c6"], "d": ["La política fiscal centralista del gobierno unionista, la campaña de recogida de armas y el debate sobre el alfabeto latino sublevaron a las tribus albanesas, consideradas hasta entonces uno de los elementos más leales al Estado. Aunque el ejército al mando de Mahmud Şevket Pasha reprimió duramente la insurrección, la inquietud se reavivó en 1911 y 1912. Estas insurrecciones desgastaron al ejército otomano en vísperas de la guerra de los Balcanes y aceleraron también el nacimiento del movimiento nacional albanés.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Tratado de Ouchy: cesión de Trípoli de Berbería y Bengasi a Italia", "4ffa1fd2"], "d": ["La Sublime Puerta, que no podía afrontar un conflicto en dos frentes ante los preparativos de guerra de los Estados balcánicos, firmó en la localidad suiza de Ouchy una paz secreta con Italia y cedió Trípoli de Berbería y Bengasi. El Estado otomano perdió así su último territorio en África; a cambio se prometió la restitución de Rodas y de las Doce Islas (Dodecaneso) ocupadas por Italia, aunque esa promesa no se cumplió jamás. Cuando se firmó el tratado, la guerra de los Balcanes ya había comenzado.", "d54a35d9"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Ocupación griega de Lemnos", "9555af1d"], "d": ["En la Primera Guerra de los Balcanes la flota griega ocupó Lemnos; el puerto de Mudros, en la isla, se convirtió en base para el bloqueo del estrecho de los Dardanelos. La isla fue dejada a Grecia en Lausana (24 de julio de 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Ocupación griega de Tasos", "6c03c7f0"], "d": ["En la Primera Guerra de los Balcanes, Grecia ocupó Tasos y Samotracia.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Ocupación griega de Samotracia", "911e82a3"], "d": ["En la Primera Guerra de los Balcanes, Grecia ocupó Samotracia.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Ocupación griega de Lesbos (Mitilene)", "6b2b07ba"], "d": ["La flota griega desembarcó en Mitilene; la isla fue tomada por el ejército y la flota griegos al final de la Primera Guerra de los Balcanes. La Conferencia de Londres (mayo de 1913) confirmó la situación.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Desembarco griego en Quíos", "901c6539"], "d": ["Los griegos desembarcaron en Quíos, bombardeada el 7 de abril de 1912 en la Primera Guerra de los Balcanes; la guarnición otomana se rindió el 3 de enero de 1913. La isla fue dejada a Grecia por el Tratado de Lausana (24 de julio de 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Asesinato del gran visir Mahmud Şevket Pasha en Estambul", "68e60e63"], "d": ["Mahmud Şevket Pasha, nombrado gran visir tras el Asalto a la Sublime Puerta (Bâb-ı Âli Baskını), fue muerto a tiros contra su coche, cerca de Çarşıkapı, cuando se dirigía al Ministerio de la Guerra. La Sociedad de Unión y Progreso, haciendo recaer el atentado sobre la oposición, inició una amplia ola de detenciones y ejecuciones, y el partido Libertad y Entente (Hürriyet ve İtilâf Fırkası) fue liquidado de hecho. Con este suceso quedó definitivamente establecida la dictadura de partido único de los unionistas, basada en el triunvirato Enver-Talat-Cemal.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Comienzo de la Segunda Guerra de los Balcanes: la disputa de los aliados por el reparto", "48d088a2"], "d": ["Los aliados balcánicos, que no lograron repartirse los territorios tomados al Imperio otomano por el Tratado de Londres, se enfrentaron entre sí; con el ataque de Bulgaria a las posiciones serbias y griegas comenzó la segunda guerra. Cuando Rumanía y Montenegro entraron también en el frente contra Bulgaria, el ejército búlgaro se derrumbó. El Estado otomano, aprovechando la ocasión, sobrepasó la línea Midye-Enez trazada por el Tratado de Londres y recuperó Tracia oriental junto con Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Tratado de Estambul: paz con Bulgaria y reconocimiento de Edirne", "c8c18b2d"], "d": ["El tratado firmado entre el Estado otomano y Bulgaria tras la Segunda Guerra de los Balcanes, aceptando el río Maritsa (Meriç) como frontera, registró jurídicamente que Edirne, Kırklareli, Didymoteicho (Dimetoka) y Tracia oriental permanecían en poder del Imperio otomano. Dedeağaç fue dejada en Bulgaria (Kavala, en cambio, había pasado a Grecia en julio de 1913 tras la ocupación búlgara del otoño de 1912 y quedó registrada en Grecia por el Tratado de Bucarest del 10 de agosto de 1913); se regularon el intercambio recíproco de población entre los dos países y los derechos de los musulmanes de Bulgaria. La garantía de la única porción de territorio que pudo recuperarse del desastre balcánico es este texto. Otros lugares incorporados en la misma fecha: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Recuperación de Ténedos e Imbros — Tratado de Atenas", "ec084d09"], "d": ["De las islas del norte del Egeo ocupadas por Grecia en la Guerra de los Balcanes, Ténedos e Imbros, que guardan la entrada de los Dardanelos, fueron consideradas indispensables para la defensa de Çanakkale en las negociaciones del Tratado de Atenas y fueron devueltas a los otomanos. Las demás islas permanecieron en Grecia. Estas dos islas fueron los últimos territorios que el Imperio conservó en el Egeo y en Lausana fueron también dejadas a Turquía.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Tratado de Atenas: paz con Grecia y cesión de Salónica y Ioánina", "8e94def7"], "d": ["El tratado firmado entre el Estado otomano y Grecia reconoció oficialmente el paso a Grecia de Salónica, Ioánina (Yanya) y el sur de Macedonia, perdidos en la guerra de los Balcanes, y se renunció a los derechos otomanos sobre Creta. Se regularon con detalle los derechos religiosos y de propiedad de los musulmanes que permanecían en Grecia, el estatuto de los vakıfs y el nombramiento de los muftíes. El estatuto de las islas del Egeo quedó sin resolver y permaneció como fuente de tensión constante entre los dos Estados.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Firma en Estambul del tratado secreto de alianza otomano-alemana", "0472efb3"], "d": ["En cuanto estalló la guerra en Europa, se firmó en la mansión del gran visir Said Halim Pasha un tratado secreto de alianza entre el Estado otomano y Alemania; el texto preveía que el Imperio otomano se pusiera al lado de Alemania en caso de que Rusia entrara en guerra contra Alemania. El tratado se ocultó incluso al gabinete y solo lo conocían cuatro personas. Tres meses después, con el Asalto al mar Negro, el Estado otomano sería arrastrado de hecho a la guerra, y el destino del Imperio quedó atado a este documento.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Abolición unilateral de las capitulaciones", "ec773d18"], "d": ["El gobierno otomano, en un momento en que Europa estaba ocupada con la guerra, anunció que abolía unilateralmente, a partir del 1 de octubre de 1914, las capitulaciones que concedían a los extranjeros privilegios judiciales, financieros y aduaneros. El fin de este régimen de privilegios de cuatro siglos fue recibido en el país con un gran entusiasmo de independencia, y se celebraron festejos en Estambul. Todos los Estados, incluida la aliada Alemania, protestaron contra la decisión; las capitulaciones solo pasarían definitivamente a la historia en 1923, en Lausana.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Asalto al mar Negro: bombardeo de puertos rusos por la flota otomana", "8ad4ef61"], "d": ["El Goeben y el Breslau (Yavuz y Midilli), que habían escapado de Alemania y se incorporaron a la flota otomana como si hubieran sido «comprados», salieron al mar Negro al mando del almirante Souchon, bombardearon los puertos rusos y hundieron barcos. Esta orden, que Enver Pasha dio a espaldas del gabinete, puso fin de hecho a la neutralidad. En una semana Rusia, Inglaterra y Francia declararon la guerra, y el Estado otomano entró de forma irreversible en la Primera Guerra Mundial.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Toma de Fao por las fuerzas anglo-indias — apertura del frente de Irak", "08663813"], "d": ["A la mañana siguiente del día en que los Estados de la Entente declararon la guerra al Estado otomano, la brigada anglo-india que esperaba en Bahréin desembarcó en Fao, en la desembocadura del Shatt al-Arab. La pequeña unidad otomana de la ruinosa fortaleza de Fao se retiró bajo el fuego de los buques de guerra, y la estación de la línea telegráfica de la India cayó en manos inglesas. Así se abrió el frente de Irak.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Proclamación de la Gran Guerra Santa (Cihâd-ı Ekber): lectura de la fetua de yihad en la mezquita de Fatih", "2a6174e8"], "d": ["Las cinco fetuas emitidas por el şeyhülislam Ürgüplü Hayri Efendi fueron leídas en la mezquita de Fatih en nombre del califa-sultán, y se llamó a todos los musulmanes a la yihad contra los Estados de la Entente. Esta jugada, en la que Alemania depositaba grandes esperanzas, tenía por objeto sublevar a los musulmanes de las colonias inglesas y francesas. El levantamiento general esperado no se produjo; al contrario, la sublevación del emir de La Meca, el sharif Husayn, con apoyo inglés dos años después, mostró de forma amarga los límites de la influencia política del califato.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Rendición de Kürne a los ingleses", "621d36b0"], "d": ["Las fuerzas del gobernador de Basora, Subhi Bey, que tras la caída de Basora se habían retirado a Kürne, donde se unen el Tigris y el Éufrates, se rindieron en la mañana del 9 de diciembre de 1914 después de los combates del 4 al 8 de diciembre.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["Egipto es puesto bajo protectorado inglés y se proclama el sultanato", "55d4e520"], "d": ["Ante la entrada del Estado otomano en la guerra, Inglaterra declaró que ponía oficialmente bajo su protectorado a Egipto, que mantenía ocupado de hecho desde 1882; el jedive Abbas Hilmi Pasha, que seguía leal al Imperio otomano, fue depuesto y en su lugar fue instalado Hüseyin Kâmil con el título de «sultán». Así se puso fin de manera unilateral a la soberanía jurídica otomana, vigente desde 1517. La Sublime Puerta no reconoció la decisión y dos meses después intentó recuperar Egipto con la Operación del Canal.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Operación de Sarıkamış: catástrofe en el frente del Cáucaso", "5cbde7f0"], "d": ["Enver Pasha, con el fin de recuperar Kars-Ardahan-Batum, perdidos en 1878, y de sublevar a los turcos del Cáucaso, lanzó al III Ejército en invierno a una maniobra para envolver a las fuerzas rusas por las montañas de Allahuekber. Por la insuficiencia del equipo de invierno, el agotamiento del abastecimiento y las ventiscas de hasta treinta grados bajo cero, el ejército se derritió antes de entrar en combate; decenas de miles de soldados murieron congelados. La operación fue una de las mayores catástrofes del Imperio otomano en la guerra y dejó indefenso el frente oriental durante dos años.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Primera Operación del Canal: ofensiva contra Suez a través del desierto del Sinaí", "02dd72f5"], "d": ["Cemal Pasha, comandante del IV Ejército, lanzó una ofensiva a través del desierto del Sinaí con el fin de liberar Egipto de la ocupación inglesa y cerrar al tráfico el canal de Suez. Aunque las tropas otomanas llegaron a la orilla oriental del canal y algunas lograron cruzar, se retiraron ante la superioridad inglesa y la ausencia de la sublevación popular egipcia esperada. La operación no alcanzó su objetivo, pero obligó a Inglaterra a mantener una gran fuerza en Egipto y tuvo así un efecto estratégico indirecto.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Promulgación de la Ley de Deportación y Reasentamiento (Sevk ve İskân / Tehcir)", "2f2bc22c"], "d": ["Tras la insurrección de Van y el avance ruso, el gobierno promulgó la ley provisional que permitía a los comandantes del ejército trasladar a otras regiones a la población considerada perturbadora de la seguridad en la retaguardia del frente, y el sultán la sancionó el 27 de mayo de 1915. Como resultado de su aplicación, la mayor parte de la población armenia de las provincias orientales y meridionales de Anatolia fue enviada en dirección a Siria y Mosul; durante los traslados hubo muy elevadas pérdidas de vidas por enfermedades, hambre y ataques. La decisión ha quedado como la cuestión más grave de los últimos años del Imperio otomano y, hasta hoy, la más controvertida.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Las tropas otomanas recuperaron Muş de la ocupación rusa", "fb1be113"], "d": ["Seis meses después de la primera ocupación rusa de Muş, el XVI Cuerpo de Ejército otomano entró en la población en la contraofensiva de Bitlis-Muş.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş volvió a manos rusas", "43ad8a03"], "d": ["Ante la contraofensiva rusa, el destacamento otomano evacuó Muş; la población volvió a ser ocupada por los rusos entre el 22 y el 25 de agosto de 1916 y permaneció en su poder hasta la primavera de 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş fue liberada definitivamente de la ocupación rusa", "f0e89703"], "d": ["Muş, que había caído bajo ocupación rusa en la Primera Guerra Mundial, fue recuperada definitivamente por las fuerzas otomanas el 1 de mayo de 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Fallecimiento de Abdülhamid II en el palacio de Beylerbeyi", "c9662582"], "d": ["Abdülhamid II, depuesto en 1909, llevado primero a Salónica y, tras la pérdida de la ciudad en la guerra de los Balcanes, a Estambul, y mantenido bajo arresto domiciliario en el palacio de Beylerbeyi, falleció. Durante su reinado de treinta y tres años había intentado ganar tiempo manteniendo al Estado alejado de las guerras, pero se le recordaba también por su régimen despótico. Su funeral fue sepultado con una gran multitud en el mausoleo de Mahmud I, en Divanyolu; su muerte coincidió con un año de guerra en que el orden que él había establecido hacía tiempo que había sido liquidado.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Tratado de Brest-Litovsk: recuperación de Kars, Ardahan y Batum", "da82636f"], "d": ["El tratado firmado entre Rusia, que se había retirado de la guerra tras la revolución bolchevique, y las Potencias Centrales cerró el frente oriental y devolvió al Estado otomano Kars, Ardahan y Batum (Elviye-i Selâse), perdidos por el Tratado de Berlín de 1878. Fue la única ganancia territorial obtenida en la historia otomana tras un lapso de cuarenta años. Pero tras el Armisticio de Mudros la región se perdería de nuevo, y la solución definitiva llegaría con el Tratado de Kars de 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Las tropas otomanas entraron en Artvin", "ca7d1778"], "d": ["Las tropas otomanas, que el 25 de marzo cruzaron la frontera de 1914, marcharon sobre Elviye-i Selâse, cuya frontera anterior a 1878 había sido devuelta por Brest-Litovsk, y entraron en Artvin el 28 de marzo de 1918. Artvin había sido dejada a Rusia en 1878 como parte del sanjacado de Batum; el artículo «Artvin» del TDV escribe el regreso solo como «marzo de 1918» y da el día según Sarı.", "224ac850"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan pasó a manos del ejército turco", "7fd9e3db"], "d": ["En las operaciones de Elviye-i Selâse, el ejército otomano tomó Ardahan el 3 de abril de 1918, tras Artvin; Ardahan había caído en la Guerra del 93, en 1877, y había sido dejada a Rusia en 1878. Kars sería tomada un mes después, el 25 de abril.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Recuperación de Batum", "d37a1a0d"], "d": ["Con la retirada de Rusia de la guerra mediante el Tratado de Brest-Litovsk, el ejército otomano, que avanzaba hacia el este, recuperó cuarenta años después el puerto de Batum, perdido en 1878. Este puerto, en el extremo oriental del mar Negro, era la salida marítima del petróleo de Bakú. La ganancia duró solo siete meses; tras el Armisticio de Mudros, la región debería ser evacuada.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars pasó a la administración otomana", "02cbf0b3"], "d": ["En Brest-Litovsk se había decidido la devolución de los tres sanjacados —Kars, Ardahan y Batum— perdidos por el Tratado de Berlín de 1878; el ejército otomano entró en Ardahan el 3 de abril, en Batum el 14 de abril y en Kars el 25 de abril de 1918, y la administración quedó establecida de hecho. Estos territorios, conocidos como «Elviye-i Selâse», fueron considerados la compensación de la pérdida sufrida desde la Guerra del 93. Tras el armisticio se perderían de nuevo y solo quedarían definitivamente ligados a Turquía con el Tratado de Kars de 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Iğdır fue ocupada — avance en el valle del Araxes", "87ebf4d3"], "d": ["En el marco del avance iniciado en febrero de 1918, las unidades turcas derrotaron a las unidades armenias en Serderabad, al norte del Araxes, y ocuparon Iğdır el 20 de mayo de 1918. Iğdır no formaba parte de Elviye-i Selâse, sino que era el distrito de Sürmeli de la gobernación de Erivan; se estableció así la primera administración otomana en la región en unos 180 años.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Fallecimiento de Mehmed V Reşad y ascenso al trono de Mehmed VI Vahdeddin", "d302ba07"], "d": ["Mehmed V Reşad, cuyo reinado de nueve años transcurrió entre las guerras de Trípoli, de los Balcanes y Mundial, falleció en el período más crítico de la guerra, y en su lugar subió al trono su hermano Vahdeddin con el nombre de Mehmed VI. El nuevo sultán trató de liberarse de la tutela del cuadro unionista; cuatro meses después, al firmarse el armisticio, tendría que dirigir la liquidación del Imperio. Fue el trigésimo sexto y último sultán de la dinastía otomana.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Llegada de la flota de la Entente ante Estambul y ocupación de hecho de la ciudad", "d10cb14d"], "d": ["Tras el Armisticio de Mudros, la flota aliada, compuesta por más de sesenta unidades de barcos ingleses, franceses, italianos y griegos, fondeó ante Dolmabahçe y Estambul quedó ocupada de hecho. Después de cuatrocientos sesenta y cinco años, la capital pasaba por primera vez al control de soldados extranjeros. La frase «Se irán como vinieron» («Geldikleri gibi giderler»), que según la tradición pronunció ese mismo día Mustafa Kemal Pasha al desembarcar en Haydarpaşa y ver el panorama, sería una de las frases emblemáticas de la Lucha Nacional.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Repliegue en la región del Araxes: Iğdır fue evacuada", "57572ab4"], "d": ["En virtud de la cláusula del Armisticio de Mudros que preveía el repliegue tras la frontera de 1914, Yakup Şevki Pachá ordenó, mediante la orden del 21 de noviembre, que las unidades situadas fuera de la frontera de Brest-Litovsk fueran retiradas hasta el 4 de diciembre; Iğdır y sus alrededores fueron evacuados por completo en esa fecha. A continuación, el Gobierno Turco del Araxes fue derribado por los armenios a finales de diciembre de 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Los británicos se instalaron en Artvin", "e2cb3153"], "d": ["Dado que el Armisticio de Mudros del 30 de octubre de 1918 imponía el repliegue del ejército otomano tras la frontera de 1914, Artvin fue evacuada y ocupada por los británicos el 17 de diciembre de 1918. Según el artículo «Artvin» del TDV, la ocupación británica duró hasta abril de 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Administración británica en Batum tras Mudros", "9dd768fc"], "d": ["En virtud del Armisticio de Mudros del 30 de octubre de 1918, el Estado otomano se vio obligado a retirarse de Batum; la ciudad fue ocupada por tropas británicas el 24 de diciembre de 1918. Batum, convertida en abril de 1918 en capital de un sanjacado independiente, permaneció desde esta fecha hasta julio de 1920 bajo control británico.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan pasó al dominio georgiano", "97cf47f6"], "d": ["Ardahan, evacuada tras Mudros, fue ocupada por las fuerzas georgianas el 20 de abril de 1919, en los días en que los británicos disolvían el Gobierno del Suroeste del Cáucaso. El dominio georgiano duraría hasta el 23 de febrero de 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston entregó la administración de Kars al gobernador armenio", "efa81cb0"], "d": ["El comandante británico Preston, que el 12-13 de abril de 1919 disolvió el Gobierno del Suroeste del Cáucaso, abolió el 30 de abril de 1919 el gobierno provisional de la shura y traspasó la administración de la ciudad al armenio Karganof, nombrado gobernador de Kars; comenzó así el período de administración armenia en Kars, que duró hasta la victoria de Kâzım Karabekir el 30 de octubre de 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Congreso de Erzurum: decisión de resistencia nacional de las provincias orientales", "41ef0457"], "d": ["El congreso convocado por la Sociedad para la Defensa de los Derechos de Anatolia Oriental (Şarkî Anadolu Müdafaa-i Hukuk Cemiyeti), tras ser aplazado por la presión inglesa, se abrió con cincuenta y seis delegados, y a su presidencia fue elegido Mustafa Kemal Pasha, que había dimitido del ejército. El congreso proclamó que la patria era un todo dentro de las fronteras nacionales, que el mandato y el protectorado eran inaceptables y que, en caso de disolución del gobierno, la nación tomaría su destino en sus propias manos. Estas decisiones constituirían seis meses después el núcleo del texto del Misak-ı Millî (Pacto Nacional).", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Congreso de Sivas: unificación de la resistencia nacional bajo un solo techo", "0e9ad36b"], "d": ["El congreso, que comenzó sus trabajos el 4 de septiembre de 1919 en la Sultanî de Sivas, unió las sociedades de defensa de derechos de todo el país bajo el nombre de Sociedad para la Defensa de los Derechos de Anatolia y Rumelia y eligió un Comité de Representación (Heyet-i Temsîliyye). La propuesta de un mandato norteamericano fue rechazada tras largas discusiones. Con la declaración publicada el 11 de septiembre, la Lucha Nacional se convirtió en un movimiento político legítimo y de centro único, y comenzó una abierta lucha de poder con el gobierno de Estambul.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Protocolo de Amasya: entrevista del gobierno de Estambul con el Comité de Representación", "40e6a6ab"], "d": ["Tras la caída de Damat Ferid y la formación del gobierno de Ali Rıza Pasha, el ministro de Marina Salih Pasha fue enviado a Amasya para entrevistarse con el Comité de Representación. Mediante los protocolos acordados, el gobierno de Estambul reconoció de hecho la existencia del movimiento de Anatolia; se aceptaron la reunión de la Asamblea de Diputados (Meclis-i Meb'ûsan), la libertad de las elecciones y la preservación de las fronteras nacionales. Es la primera ganancia política oficial que obtuvo la Lucha Nacional frente a Estambul.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Aprobación del Misak-ı Millî en la última Asamblea otomana", "6322865e"], "d": ["El texto del Pacto Nacional (Ahd-i Millî), firmado por 121 diputados en la última Asamblea de Diputados otomana (Meclis-i Meb'ûsan), exigía la integridad indivisible de las tierras que quedaban dentro de la línea de Mudros y donde vivía la mayoría musulmana y turca, un plebiscito en las provincias árabes y en Tracia occidental, la abolición de las capitulaciones y la plena independencia política y financiera. El texto fue aprobado por unanimidad el 17 de febrero de 1920 y proclamado al mundo. Esta declaración fue tanto el programa político de la Lucha Nacional como el mapa de las fronteras que se defenderían en Lausana; fue la causa directa de que los Estados de la Entente ocuparan oficialmente Estambul el 16 de marzo.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Al retirarse los británicos, Artvin quedó en Georgia", "6d086b06"], "d": ["Según el artículo «Artvin» del TDV, la ocupación británica duró hasta el mes de abril de 1920; al retirarse, los británicos dejaron la ciudad a Georgia. Artvin permaneció en manos de Georgia hasta el ultimátum de la Gran Asamblea Nacional de Turquía del 23 de febrero de 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum fue entregada a la administración georgiana", "6523d095"], "d": ["La entrega formal de Batum por los británicos a los georgianos tuvo lugar el 7 de julio de 1920 (el artículo «Batum» del TDV dice solo «julio de 1920»). El gobierno de Ankara protestó el 25 de julio contra la entrega calificándola de «ocupación».", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Tratado de Gümrü: primer tratado internacional del gobierno de la Gran Asamblea Nacional de Turquía (TBMM)", "9232c690"], "d": ["Cuando el ejército del frente oriental al mando de Kâzım Karabekir recuperó Sarıkamış y Kars, Armenia pidió la paz y, con el tratado firmado en Gümrü, aceptó no reconocer Sèvres y renunciar a sus reivindicaciones territoriales en el este. Este primer tratado firmado por el gobierno de Ankara fue el primer documento internacional que rechazó de hecho Sèvres y abrió a la TBMM el camino del reconocimiento jurídico. Con la frontera oriental así asegurada, fue posible desplazar fuerzas al frente occidental.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Primera Batalla de İnönü: primera victoria del ejército regular", "4add3719"], "d": ["El ejército regular recién creado detuvo en las posiciones de İnönü a las fuerzas griegas que avanzaban desde la dirección de Bursa y las obligó a retirarse. Aunque este éxito fue de escala limitada en el aspecto militar, sus consecuencias políticas fueron muy grandes: el gobierno de Ankara fue invitado a la Conferencia de Londres, se abrió el camino al Tratado de Moscú con la Rusia soviética y se aprobó la Ley de Organización Fundamental (Teşkilât-ı Esâsiyye Kanunu). La confianza de la opinión pública interna en el ejército regular se consolidó también con esta victoria.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Segunda Batalla de İnönü: segunda ruptura de la ofensiva griega", "a974521c"], "d": ["El ejército griego, que no obtuvo resultados de la Conferencia de Londres, pasó a una nueva ofensiva en dirección a Bursa y Uşak, pero fue de nuevo detenido en las colinas de İnönü y se vio obligado a retirarse. El telegrama de Mustafa Kemal Pasha a İsmet Pasha, «Allí no habéis vencido solo al enemigo, sino también al destino adverso de la nación», fue escrito tras esta victoria. La batalla elevó el prestigio internacional de la Lucha Nacional y aceleró el proceso de retirada de Italia de Anatolia.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Acuerdo de Ankara: paz con Francia y cierre del frente meridional", "35fc32db"], "d": ["Con el acuerdo firmado en Ankara con Francia tras la victoria del Sakarya terminó la guerra en el frente meridional; las fuerzas francesas evacuaron Çukurova y el sudeste, incluidos Adana, Antep, Maraş y Urfa, y se retiraron a la frontera siria. Uno de los Estados de la Entente reconoció así de hecho al gobierno de Ankara, y se abrió la primera grieta en el frente de Sèvres. Las armas recibidas de las regiones evacuadas y las unidades liberadas desempeñaron un papel crítico en la preparación de la Gran Ofensiva.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Armisticio de Mudanya: cesión de Estambul y de los Estrechos sin guerra", "ac0d9baf"], "d": ["Cuando tras la Gran Ofensiva el ejército turco se encontró cara a cara con las fuerzas inglesas en los Dardanelos e İzmit, la conferencia reunida en Mudanya concluyó en un armisticio tras once días de duro regateo. Se acordó que Tracia oriental hasta el Maritsa fuera evacuada por Grecia en quince días y entregada a la administración turca, y que Estambul y los Estrechos fueran entregados mediante el tratado de paz. Así, la fase armada de la Lucha Nacional se cerró con una victoria diplomática ganada sin disparar un solo tiro y se abrió la puerta de Lausana.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Salida de Mehmed VI Vahdeddin de Estambul y elección de Abdülmecid Efendi como califa", "8ab0e847"], "d": ["Mehmed VI Vahdeddin, el último sultán, cuya posición se hizo discutible tras la abolición del sultanato, abandonó Estambul en la mañana del viernes 17 de noviembre de 1922 a bordo del acorazado inglés Malaya y se dirigió a Malta. Dos días después, el 19 de noviembre, la TBMM eligió a Abdülmecid Efendi como califa sin autoridad política. Así terminó de hecho el reinado de la dinastía otomana, que había durado seiscientos veintitrés años; el califato continuaría de forma simbólica quince meses más. Vahdeddin, que pasó a Malta y después a Italia, se instaló en la Villa Nobel de San Remo; sus solicitudes para ser admitido en un país musulmán no dieron resultado, y murió allí el 16 de mayo de 1926, reiterando que jamás había renunciado a sus derechos de sultanato y califato.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Fallecimiento del último sultán, Mehmed VI Vahdeddin, en San Remo", "7149ed0e"], "d": ["Mehmed Vahdeddin, último sultán otomano, que se estableció en la ciudad italiana de San Remo tras salir de Estambul, murió el 16 de mayo de 1926 sin haber sabido que se había reunido el congreso del califato (13 de mayo de 1926), en el que declaraba que nunca había renunciado a sus derechos al sultanato y al califato. Se hallaba en grave penuria de dinero; debía 60.000 liras a los comerciantes de San Remo y, al enterarse de su muerte, los acreedores hicieron embargar los enseres de su casa.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Conquista de la región de Bolu por Konuralp — Mudurnu, Konurapa y Bolu", "e245cd27"], "d": ["Konuralp, uno de los comandantes de Orhan Gazi, se dirigió a la región montañosa al este del Sakarya y ligó a la administración otomana Mudurnu, Konurapa y la región de Bolu; la población de la llanura de Düzce se conoce por su nombre. La fecha exacta de la conquista se desconoce; el relato se basa en la tradición de Âşıkpaşazâde. La región era entonces una zona fronteriza que cambiaba de manos entre los Candáridas y Bizancio; la conquista acercó por primera vez a los otomanos a la costa occidental del mar Negro. Tras la batalla de Ankara la región volvería a los Candáridas, pero sería recuperada definitivamente en tiempos de Mehmed el Conquistador.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Toma de las poblaciones bizantinas al sur de Mármara — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Tras la toma de Nicea y de Izmit, las poblaciones que Bizancio conservaba al oeste de la llanura de Bursa pasaron una a una a la administración otomana. Gölyazı, en torno al lago Uluabat, Kirmasti, a orillas del río Susurluk, y Mihaliç completaron el corredor que unía la costa sur de Mármara con las tierras de Karesi. Estas poblaciones se rindieron durante mucho tiempo sin sufrir asedio, al quedar aisladas; la presencia bizantina en la región quedó así reducida al golfo de Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Corinto pasó al Despotado de Morea", "392495eb"], "d": ["Corinto, feudo vinculado al principado de Acaya de la familia florentina Acciaiuoli desde 1358, pasó en 1395 a manos de Teodoro, déspota bizantino de Morea. La ciudad permaneció desde entonces bajo la administración del despotado hasta la conquista otomana.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Anexión del Beylicato de los Hacıemíridas — Ordu y Ünye", "c064f07f"], "d": ["El beylicato turcomano, fundado por Bayram Bey en torno a Ordu y ampliado en la década de 1350 por su hijo Hacı Emîr, era un pequeño pero estratégico Estado costero con centro en la actual Eskipazar: era el único dominio independiente entre Samsun y Trebisonda. El emir Solimán había declarado su fidelidad en 1398 en la campaña de Canik de Bayezid el Rayo, y tras la batalla de Ankara el beylicato volvió a ser libre. En tiempos de Murad II, en los mismos años de la liquidación de los Taceddínidas, las tierras del beylicato fueron ligadas directamente a la administración otomana y la costa del mar Negro quedó unificada en una sola mano desde Samsun hasta Giresun.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Conquista de Corinto", "87a2bc59"], "d": ["En la campaña de Morea de Mehmed el Conquistador, la fortaleza de Acrocorinto fue sitiada tres meses y finalmente tomada por vía pacífica. El istmo de Corinto, considerado la puerta de Morea, pasó así a los otomanos.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Anexión de Montenegro a la administración otomana — Cetinje", "7fdb7cc8"], "d": ["Cuando la dinastía Crnojević, que gobernaba Zeta, renunció a su dominio en 1496, la región montañosa de Montenegro, patio trasero de Shkodër, fue puesta bajo administración otomana directa y organizada primero como sanjacado separado y luego como parte del sanjacado de Shkodër. El monasterio de Cetinje fue dejado en su lugar como centro religioso de la región. Debido a la aspereza de la geografía, la administración aquí nunca funcionó tan estrictamente como en las llanuras; dos siglos después, el gobierno del vladika, surgido del mismo monasterio, sería el núcleo de la independencia de hecho.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Aceptación del dominio otomano por la fortaleza de Bayezid en la campaña de los Dos Iraqs", "f29e2e17"], "d": ["Cuando el gran visir İbrahim Pachá llegó a las cercanías de Bingöl en la campaña de los Dos Iraqs, las fortalezas de Van, Toprakkale, Avnik y Bayezid, junto con muchas tribus kurdas de la región, accedieron a entrar bajo el dominio otomano. Bayezid se había unido a los otomanos en 1514 en la campaña de Selim I el Severo, pero al volver el ejército los safávidas habían recuperado la región.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz pasó de nuevo a los safávidas — regreso de la campaña de los Dos Iraqs", "80b8b761"], "d": ["En la campaña de los Dos Iraqs el ejército había entrado en Tabriz, pero como el objetivo principal era Bagdad no se dejó una guarnición permanente en la ciudad. Cuando el ejército, que pasó el invierno en Bagdad, volvía hacia el oeste, el sha Tahmasp volvió a entrar en el Azerbaiyán evacuado y recuperó Tabriz. Este fue el patrón repetido de las guerras otomano-safávidas: Tabriz fue tomada cinco veces y las cinco veces no pudo ser conservada; la ciudad solo tendría una guarnición otomana de larga duración en 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Van y Erciş cayeron en manos de Tahmasp (la posesión otomana terminó en 1534-35)", "cb93d561"], "d": ["En la región que había entregado Van al dominio otomano en 1534, Ulama Pachá resistió en la fortaleza de Van el asedio safávida; la fortaleza pasó a manos de los safávidas, y las fuerzas safávidas que sitiaban Erciş se habían retirado con la ayuda otomana. Cuando Solimán el Legislador llegó a Ahlat (23 de septiembre de 1535), Van estaba ya en manos de Tahmasp. Van permaneció safávida hasta 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["El sanjacado de Bayezid pasó al dominio safávida (Van y Erciş ya eran safávidas en 1535)", "806a2cf1"], "d": ["El sanjacado de Bayezid, en medio de la frontera otomano-safávida, volvió a manos de Irán (Kaya 2017 lo menciona «junto con Van y Erciş»; sin embargo, según Karataş 2025 y el TDV, Van y Erciş habían vuelto a los safávidas el 22 de septiembre de 1535 — véase la entrada anterior); en este cambio de manos, algunos lugares del sanjacado quedaron arruinados. El sanjacado cambió de manos varias veces entre los dos Estados hasta el último cuarto del siglo XVI.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["El sanjacado de Bayezid pasó de nuevo a los otomanos durante la campaña de Najicheván", "cf0171fa"], "d": ["Durante la tercera campaña de Irán (Najicheván) de Solimán el Legislador, el sanjacado de Bayezid volvió a la administración otomana. En la campaña de 1554, Bayazıt fue una importante base para el ejército; el sanjacado entró definitivamente bajo la soberanía otomana en 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Pérdida de Revan ante el sha Abbas", "34413cf2"], "d": ["Cuando el frente oriental quedó indefenso en los años en que las rebeliones celalíes bloqueaban Anatolia, el sha Abbas, que había reorganizado su ejército al estilo europeo, pasó a la ofensiva. La fortaleza de Revan, construida por Ferhad Pachá en 1583, se rindió tras siete meses de asedio. El primer eslabón de la línea del Cáucaso ganada con el Tratado de Ferhad Pachá se había roto, y en los tres años siguientes todo el Cáucaso meridional se perdería.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Pérdida de Tiflis y Gence", "3fb51753"], "d": ["Tras la caída de Revan, el ejército safávida avanzó a lo largo del valle del Kura; Gence, centro del Karabaj, y Tiflis, capital de Georgia, se perdieron una tras otra. El Estado otomano libraba al mismo tiempo en el frente austriaco una larga guerra de trece años y se ocupaba de los celalíes en Anatolia; no había fuerzas que enviar al este. Así terminó de hecho el amplio orden de provincias del Cáucaso establecido con el Tratado de Ferhad Pachá de 1590.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Pérdida de Shirván — Shamakhi, Bakú y Derbent", "81beab11"], "d": ["La provincia de Shirván, en la costa del Caspio, ganada en las campañas de 1578-1585 de Özdemiroğlu Osman Pachá, había proporcionado importantes ingresos a la hacienda otomana como fuente principal del comercio de la seda. La campaña de Abbas hacia el norte liquidó esta provincia tomando sucesivamente Shamakhi, Bakú y Derbent. La pérdida no fue solo de territorio: la ruta por la que la seda iraní fluía a Europa a través de los otomanos quedó fuera de su control, y el Estado safávida comenzó a comercializar la seda por el océano Índico.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Pérdida de Taiz", "65f20d53"], "d": ["Los otomanos abandonaron en 1038 (1629) Taiz junto con el dominio del Yemen, que fue dejado a la administración Qasimí de Saná — el primer gran paso del proceso por el que los imames zaydíes recuperaron el Yemen interior.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Pérdida del Yemen — dominio de los imames Qasimíes", "49e83e3c"], "d": ["Yemen era provincia otomana desde 1538, pero la resistencia de los imames zaydíes nunca cesó. El levantamiento iniciado por el imam al-Qasim se extendió a todo el país durante el gobierno de su hijo al-Mu'ayyad Muhammad, y las guarniciones otomanas fueron sitiadas una tras otra. En los años en que Murad IV se concentraba en Bagdad y Ereván no pudo enviarse refuerzos; Taiz se había perdido en 1629, mientras que Moca fue evacuada el 22 de octubre de 1635, en la fase final del mismo derrumbe. En 1635 las últimas tropas en Saná y Zabid también evacuaron Yemen. Así, la costa oriental del mar Rojo quedó fuera del imperio durante doscientos treinta y siete años y solo pudo recuperarse en 1872. Según la TDV İslâm Ansiklopedisi, Lahej (al-Hawta) estuvo en manos otomanas hasta 1635; desde esa fecha los imames zaydíes se hicieron influyentes.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Evacuación de Moca", "c6b3061a"], "d": ["Mustafa Bey evacuó Moca el 10 de yumada al-awwal de 1045 (22 de octubre de 1635) con las fuerzas y armas restantes; a continuación, Hasan b. Qasim, hijo del imam Qasim, nombró a sus propios hombres en Zabid y Moca y estableció también el control Qasimí en la costa de Tihama.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Pérdida de Al-Hasa ante el Emirato de Banu Jalid", "a9b6131a"], "d": ["Al-Hasa era una provincia creada en 1550 para cerrar a Portugal la costa occidental del golfo de Basora, pero estaba muy lejos de Estambul, en el extremo de una única ruta desértica. En los años en que el asedio de Creta agotaba los recursos, la tribu de Banu Jalid de la región, bajo el liderazgo de Barrak b. Ghurayr, expulsó a la guarnición otomana y fundó su propio emirato. La costa occidental del golfo permaneció durante siglo y medio en emiratos tribales; pasaría a los saudíes en 1795 y de nuevo a los otomanos en 1871.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Pérdida de Preveza y Vonitsa ante Venecia — apertura de la costa del Épiro", "1201204c"], "d": ["Venecia, que se unió a la Liga Santa, tomó antes de iniciar la campaña de Morea las dos fortalezas que guardan la entrada del golfo de Ambracia: Preveza y, en la orilla opuesta, Vonitsa. Aquel mismo verano había caído también Santa Maura (Lefkada). Estas tres posiciones permitieron introducir con seguridad la flota desde el mar Jónico hacia el interior de Grecia y se convirtieron en la base de la campaña de Morea que comenzaría al año siguiente. Preveza y Vonitsa fueron también dejadas a Venecia en Passarowitz; solo volverían a la administración otomana en 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Pérdida de Szolnok — desmoronamiento de la línea del Tisza", "51c2c8ef"], "d": ["Tras la caída de Uyvar en agosto, el ejército de los Habsburgo se volvió hacia el sur y tomó Szolnok, cabeza de puente sobre el río Tisza. La ciudad era el único paso seguro entre Buda y Transilvania; su pérdida significaba que las fortalezas otomanas de la mitad oriental de Hungría quedaban cortadas entre sí. Al año siguiente, en el asedio de Buda, fue decisivo que la ruta de abastecimiento estuviera cortada.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Pérdida de Modon ante Venecia", "114c9cc0"], "d": ["Modon, en el extremo suroeste de la península de Morea, era el puerto que Venecia había perdido tres siglos antes y que llamaba «uno de los dos ojos del Estado». La fortaleza, sitiada tras la caída de Corón, fue tomada batiéndola simultáneamente por tierra y por mar. La campaña de Morea de Morosini se apoderó así de toda la costa occidental de la península y se abrió el camino hacia el interior.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Pérdida de Pécs", "99d54cf4"], "d": ["Tras la caída de Buda en septiembre, las fuerzas de los Habsburgo descendieron hacia el sur por el oeste del Danubio y tomaron Pécs, otomana desde la época de Solimán el Legislador. La ciudad, conocida por la mezquita de Gazi Kâsım Pachá, era una de las capitales de sanjacado más desarrolladas de la provincia de Buda. Su pérdida significaba la apertura del camino que descendía a la llanura de Mohács; al año siguiente, el desastre de la Segunda Mohács tendría lugar precisamente aquí.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Pérdida de Szeged", "9fbee1b2"], "d": ["Szeged, en la confluencia de los ríos Tisza y Maros, era la puerta sur de la llanura húngara y guardaba el camino a la provincia de Timișoara. Tras la caída de Buda y de Pécs en el mismo otoño, la fortaleza, sitiada, se rindió en poco tiempo. La pérdida de tres fortalezas en una sola estación era señal de que la estructura administrativa otomana en Hungría, establecida desde 1541, comenzaba a derrumbarse.", "63dea9ab"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Pérdida de Patras — la puerta norte de Morea", "b9cff63c"], "d": ["Patras, a la entrada del golfo de Corinto, era el puerto que controlaba el paso entre Morea y Rumelia. Tras tomar la ciudad el ejército veneciano, las fortalezas de ambas orillas del golfo cayeron una tras otra y la península quedó completamente aislada por tierra. Al final de esta campaña la totalidad de Morea pasó a Venecia; la región sería gobernada hasta 1715 con el nombre de «Regno di Morea».", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Cesión de Corinto a Venecia", "9a25b6b9"], "d": ["Tras la caída de Patras, Corinto fue dejada a los venecianos por vía pacífica y la población musulmana abandonó la ciudad. En agosto de 1687 el ejército de Morosini se concentraba en Corinto para la campaña de Atenas.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Pérdida de Eger", "983391aa"], "d": ["Eger había sido tomada en 1596 en la campaña en la que participó personalmente Mehmed III, y se había convertido en capital de una provincia con su propio nombre. Esta última gran fortaleza otomana del norte de Hungría resistió un año completamente sitiada tras el desastre de la Segunda Mohács, y se rindió por hambre. Con su pérdida, el flanco norte del Estado otomano en Hungría quedó totalmente liquidado.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Pérdida de Estolni Belgrado — la ciudad de coronación de los reyes húngaros", "c6147255"], "d": ["La ciudad en la que los reyes húngaros fueron coronados y enterrados durante siglos había sido tomada en 1543 por Solimán el Legislador y se había convertido en una de las capitales de sanjacado más importantes de la provincia de Buda. Unos dos años después de la caída de Buda, la fortaleza, completamente aislada, se rindió. Con esta pérdida, la presencia otomana al oeste del Danubio quedó reducida a los alrededores de Sirmia y Osijek.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Pérdida de Szigetvár", "834910a7"], "d": ["Szigetvár era la fortaleza en la que Solimán el Legislador murió en 1566, durante el asedio, en su decimotercera y última campaña; por ello tenía un lugar simbólico en la memoria otomana. Ciento veintitrés años después, tras la caída de todas las fortalezas de su alrededor, la fortaleza, protegida por pantanos, se rindió también. El mausoleo en el que estaban enterradas las entrañas de Solimán el Legislador y la población a su alrededor fueron destruidos tras pasar a la administración de los Habsburgo.", "54f30d14"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Pérdida de Várad", "6cce360d"], "d": ["Várad era la fortaleza clave que daba acceso a Transilvania, tomada en 1660 por Köprülü Mehmed Pachá y convertida en capital de una provincia con su propio nombre. La fortaleza, que quedó completamente sola tras el desastre de Slankamen, se rindió por hambre tras un bloqueo de casi dos años. Con su pérdida la influencia otomana sobre Transilvania terminó de hecho, y el dominio de los Habsburgo se asentó al este del Tisza.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Pérdida de Yanova — cierre del camino de Transilvania", "4b5e30d8"], "d": ["Yanova era una fortaleza tomada en 1658 que mantenía la conexión entre Várad y Timișoara. Cuando quedó aislada inmediatamente después de la caída de Várad, se perdió también. Así, la provincia de Timișoara quedó completamente aislada por el norte y siguió existiendo hasta Karlowitz como el único territorio húngaro que quedaba en manos otomanas.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Establecimiento del gobierno del vladika en Montenegro — separación de hecho de Cetinje", "a924b778"], "d": ["En los años en que la Guerra de la Liga Santa relajaba el control otomano en los Balcanes, la metropolía al frente del monasterio de Cetinje se convirtió en un cargo que pasaba de padre a hijo en la familia Petrović, y la región obtuvo de hecho una administración separada. Gracias a lo inaccesible de las montañas, este vladikato subsistió durante dos siglos en una posición ni plenamente independiente ni plenamente dependiente; su independencia jurídica solo sería reconocida por el Tratado de Berlín de 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Recuperación de Corinto", "26f53e3a"], "d": ["La primera gran parada de la campaña de Morea de Damad Ali Pachá fue Corinto; los otomanos recuperaron la ciudad a los venecianos en junio de 1715 y avanzaron desde allí hacia el resto de la península.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Ofensiva de Nader: pérdida de Tabriz, Najicheván, Hamadán, Kermanshah, Maragheh y Qasr-i Shirin", "d95efd59"], "d": ["Las ciudades del oeste de Irán tomadas entre 1723 y 1727 aprovechando el hundimiento del Estado safávida se perdieron una a una por la ofensiva de Nader Jan, que se había hecho con el poder efectivo en Irán. También Ardabil y Jalhal, en Azerbaiyán, pasaron a manos de Nader. La pérdida de Hamadán, Kermanshah y Qasr-i Shirin tuvo un fuerte eco en Estambul; que el ejército no saliera en campaña y esperara en Üsküdar, y que se intentara encubrir la pérdida, fue una de las causas directas de la rebelión de Patrona Halil, estallada seis semanas después.", "3affcf18"]}
});
